 * - Primary / Secondary variants
 * - Loading state with spinner
 * - Disabled state (auto-handled with loading)
 * - Press animation (touch feedback)
 * - Dynamic utility classes (bg, color, radius)
 * - Scalable architecture (size, block, future variants)
 *
 * ----------------------------------------------------------------------------
 * USAGE
 * ----------------------------------------------------------------------------
 * <app-button
 *   type="primary"
 *   size="md"
 *   bg="bg-primary"
 *   color="text-white"
 *   radius="br-15"
 *   bind:onPress="handleTap"
 * >
 *   Submit
 * </app-button>
 *
 * ----------------------------------------------------------------------------
 * PROPERTIES
 * ----------------------------------------------------------------------------
 *
 * @property {boolean} disabled
 * - Prevents user interaction
 *
 * @property {boolean} loading
 * - Shows spinner and disables interaction
 *
 * @property {'primary'|'secondary'} type
 * - Visual style of button
 *
 * @property {'sm'|'md'|'lg'} size
 * - Controls padding & font size
 *
 * @property {boolean} block
 * - Full width button
 *
 * @property {string} radius
 * - Border radius utility class (e.g. 'br-15')
 *
 * @property {string} bg
 * - Background class (used for primary)
 *
 * @property {string} color
 * - Text color class or inline color
 *
 * ----------------------------------------------------------------------------
 * EVENTS
 * ----------------------------------------------------------------------------
 *
 * @event onPress
 * - Fired when button is tapped (if not disabled/loading)
 *
 * ============================================================================
 */

Component({
  properties: {
    /** Disable interaction */
    disabled: {
      type: Boolean,
      value: false,
    },

    /** Show loading spinner + disable button */
    loading: {
      type: Boolean,
      value: false,
    },

    /** Button variant */
    type: {
      type: String,
      value: "primary", // 'primary' | 'secondary'
    },

    /** Size variant */
    size: {
      type: String,
      value: "md", // 'sm' | 'md' | 'lg'
    },

    /** Full width button */
    block: {
      type: Boolean,
      value: false,
    },

    /** Border radius class */
    radius: {
      type: String,
      value: "br-15",
    },

    /** Background class (primary only) */
    bg: {
      type: String,
      value: "bg-primary",
    },

    /** Text color class OR inline color */
    color: {
      type: String,
      value: "",
    },

    /** Optional icon name to display on the left of the label */
    icon: {
      type: String,
      value: "",
    },

    /** Optional icon width in rpx */
    iconWidth: {
      type: Number,
      value: 30,
    },

    /** Optional icon height in rpx */
    iconHeight: {
      type: Number,
      value: 30,
    },
  },

  data: {
    /** Whether button is currently pressed (touch feedback) */
    pressed: false,

    /** Computed disabled state (disabled || loading) */
    isDisabled: false,

    /** Dynamic Color class  string */
    colorClass: "",

    /** InlineStyle class  string */
    inlineStyle: "",

    /** Final computed class string */
    buttonClass: "",
  },

  /**
   * Observe changes in props/state that affect styling
   * Automatically recompute classes
   */
  observers: {
    "type, size, block, disabled, loading, radius, bg, color, pressed":
      function () {
        this.computeClass();
      },

    color(newColor) {
      if (!newColor) return;

      // --------------------------------------------------
      // CASE 1: Utility class (text-*)
      // --------------------------------------------------
      if (newColor.startsWith("text-")) {
        this.setData({
          colorClass: newColor,
          inlineStyle: "",
        });
        return;
      }

      // --------------------------------------------------
      // CASE 2: HEX / rgb / named color → inline fallback
      // --------------------------------------------------
      this.setData({
        colorClass: "",
        inlineStyle: `color: ${newColor};`,
      });
    },
  },

  lifetimes: {
    /** Initialize class on mount */
    attached() {
      this.computeClass();
    },
  },

  methods: {
    /**
     * ------------------------------------------------------------------------
     * CLASS BUILDER (CORE LOGIC)
     * ------------------------------------------------------------------------
     * Combines:
     * - Base class
     * - Variant class
     * - Size & layout
     * - Utility classes
     * - State classes
     */
    computeClass() {
      const {
        type,
        size,
        block,
        disabled,
        loading,
        radius,
        bg,
        color,
        pressed,
      } = this.data;

      // ------------------------------------------------------------------
      // STATE
      // ------------------------------------------------------------------
      const isDisabled = disabled || loading;

      // ------------------------------------------------------------------
      // BASE + VARIANT
      // ------------------------------------------------------------------
      const baseClass = "osn-btn";

      const variantClass =
        type === "secondary" ? "osn-btn-secondary" : "osn-btn-primary";

      // ------------------------------------------------------------------
      // SIZE & LAYOUT
      // ------------------------------------------------------------------
      const sizeClass = size ? `osn-btn--${size}` : "";
      const blockClass = block ? "osn-btn--block" : "";

      // ------------------------------------------------------------------
      // UTILITIES
      // ------------------------------------------------------------------
      const radiusClass = radius || "br-15";

      const textColorClass = this.data.colorClass || "";

      const bgClass = type === "primary" ? bg : "";

      // ------------------------------------------------------------------
      // STATES
      // ------------------------------------------------------------------
      const stateClasses = [
        // shared states
        isDisabled && "osn-btn--disabled",
        pressed && "osn-btn--pressed",

        // variant-specific states
        isDisabled && `${variantClass}--disabled`,
        pressed && `${variantClass}--pressed`,
      ];

      // ------------------------------------------------------------------
      // FINAL CLASS LIST
      // ------------------------------------------------------------------
      const classList = [
        baseClass,
        variantClass,
        bgClass,
        textColorClass,
        radiusClass,
        sizeClass,
        blockClass,
        ...stateClasses,
      ];

      // ------------------------------------------------------------------
      // APPLY TO VIEW
      // ------------------------------------------------------------------
      this.setData({
        isDisabled,
        buttonClass: classList.filter(Boolean).join(" "),
      });
    },

    /**
     * Handle button tap
     * Emits event only if interactive
     */
    executionAction() {
      if (!this.data.isDisabled) {
        this.triggerEvent("onPress");
      }
    },

    /**
     * Touch start → enable pressed state
     */
    onPressStart() {
      if (!this.data.isDisabled) {
        this.setData({ pressed: true });
      }
    },

    /**
     * Touch end / cancel → reset pressed state
     */
    onPressEnd() {
      this.setData({ pressed: false });
    },
  },
});

