import { formatDuration } from "../../../utils/formatters/index";

Component({
  options: {
    styleIsolation: "isolated",
  },
  properties: {
    id: {
      type: String,
      value: "",
    },
    from: {
      type: String,
      value: "",
    },
    to: {
      type: String,
      value: "",
    },
    departDate: {
      type: Date,
      value: "",
    },
    returnDate: {
      type: Date,
      value: "",
    },
    isOneWay: {
      type: Boolean,
      value: false,
    },
    mode: {
      type: String,
      value: "result",
    },
    title: {
      type: String,
      value: "",
    },
    segments: {
      type: Array,
      value: [],
    },
    expanded: {
      type: Boolean,
      value: false,
    },
    time: {
      type: Object,
      value: {},
    },
    stops: {
      type: String,
      value: "",
    },
    duration: {
      type: String,
      value: "",
    },
    type: {
      type: String,
      value: "",
    },
    image: {
      type: String,
      value: "",
    },
    price: {
      type: String,
      value: "",
    },
    note: {
      type: String,
      value: "",
    },
    airline: {
      type: Object,
      value: {},
    },
    payload: {
      type: Object,
      value: null,
    },
    itinerary: {
      type: Array,
      value: [],
      observer: "updateDisplayLegs",
    },
  },

  data: {
    displayLegs: [],
  },

  lifetimes: {
    attached() {
      this.updateDisplayLegs(this.properties.itinerary);
    },
  },

  methods: {
    updateDisplayLegs(itinerary = []) {
      const itineraryLegs =
        Array.isArray(itinerary) && itinerary.length
          ? itinerary
          : this.properties.payload?.itinerary || [];
      const legs = itineraryLegs.length
        ? itineraryLegs
        : [
            {
              origin_airport_code: this.properties.from,
              destination_airport_code: this.properties.to,
              duration: this.properties.duration,
              num_stops: this.properties.stops === "Direct" ? 0 : undefined,
              segments: [
                {
                  departure_time: {
                    date: this.properties.departDate,
                    time: this.properties.time?.departure,
                  },
                  arrival_time: { time: this.properties.time?.arrival },
                },
              ],
            },
          ];

      this.setData({
        displayLegs: legs.map((leg, index) => {
          const segments = leg.segments || [];
          const first = segments[0] || {};
          const last = segments[segments.length - 1] || first;
          const departure = first.departure_time || {};
          const arrival = last.arrival_time || {};
          const isRoundTrip = legs.length === 2;

          return {
            label:
              legs.length > 2
                ? `Leg ${index + 1}`
                : index === 0
                  ? "Outbound"
                  : "Inbound",
            date: departure.date || "",
            from: leg.origin_airport_code || first.departure_code || "",
            to: leg.destination_airport_code || last.arrival_code || "",
            departureTime: departure.time || "",
            arrivalTime: arrival.time || "",
            duration: formatDuration(
              typeof leg.duration === "string" ? leg.duration : "",
              Number(leg.duration) > 1000
                ? Math.round(Number(leg.duration) / 60)
                : Number(leg.duration),
            ),
            stops:
              Number(leg.num_stops) === 0
                ? "Direct"
                : `${leg.num_stops || 0} stop${Number(leg.num_stops) === 1 ? "" : "s"}`,
            icon: isRoundTrip && index === 1 ? "airSn" : "airBn",
          };
        }),
      });
    },

    handleSummaryDetails() {
      this.triggerEvent("details", {
        id: this.properties.id,
        mode: "summary",
        segments: this.properties.segments,
        expanded: this.properties.expanded,
      });
    },

    handleContinue() {
      this.triggerEvent("continue", {
        id: this.properties.id,
        from: this.properties.from,
        to: this.properties.to,
        dates: this.properties.dates,
        type: this.properties.type,
      });
    },
    handleDetailsFlight() {
      const payload = this.properties.payload || {};

      const itinerary =
        this.properties.itinerary && this.properties.itinerary.length
          ? this.properties.itinerary
          : payload?.itinerary;

      const airline =
        this.properties.airline && this.properties.airline.name
          ? this.properties.airline
          : payload.airline;

      // Emit a details event to the parent with the complete selected result payload.
      this.triggerEvent("details", {
        ...payload,
        id: this.properties.id,
        from: this.properties.from,
        to: this.properties.to,
        departDate: this.properties.departDate,
        returnDate: this.properties.returnDate,
        time: this.properties.time,
        stops: this.properties.stops,
        duration: this.properties.duration,
        price: this.properties.price,
        note: this.properties.note,
        airline,
        itinerary,
      });
    },
  },
});

