Component({
  properties: {
    // one entry per flight leg, e.g. [{code:'YUL - YYZ'}, {code:'YYZ - YUL'}]
    legs: {
      type: Array,
      value: [],
    },
    // A/B | C/D/E | F/G layout, '' marks an aisle gap
    columns: {
      type: Array,
      value: ["A", "B", "", "C", "D", "E", "", "F", "G"],
    },
    rowStart: { type: Number, value: 30 },
    rowEnd: { type: Number, value: 45 },
    // rows that are exit rows get an EXIT tag on both sides
    exitRows: { type: Array, value: [41] },
    // occupied seats, e.g. ['30A','30B','31C', ...] - taken by other passengers, not selectable
    occupiedSeats: { type: Array, value: [] },
    // reserved seats, e.g. ['35A','35B', ...] - held/blocked seats shown in blue, not selectable
    reservedSeats: { type: Array, value: [] },
    // removed seats, e.g. ['34D'] - leave the position empty while preserving the row spacing
    removedSeats: {
      type: Array,
      value: [
        "14A",
        "15A",
        "14B",
        "15B",
        "14F",
        "15F",
        "14G",
        "15G",
        "40A",
        "41A",
        "40B",
        "41B",
        "40F",
        "41F",
        "40G",
        "41G",
      ],
    },
    // pre-selected: 'star' = the traveler's own pick, 'ring' = a companion pick
    starSeat: { type: String, value: "" },
    ringSeat: { type: String, value: "" },
    ringTooltip: { type: String, value: "" },
    passengerCount: { type: Number, value: 0 },
    pricePerSeat: { type: Number, value: 0 },
    currency: { type: String, value: "USD" },
    flight: {
      type: Object,
      value: {
        airline: "Air Cote d'Ivoire",
        number: "HF725",
        duration: "1h 40m",
      },
    },
  },

  data: {
    currentLeg: 0,
    rows: [],
    selectedSeatsByLeg: [],
    selectedCount: 0,
    totalPrice: 0,
  },

  lifetimes: {
    attached() {
      const initialSeats = [this.data.starSeat, this.data.ringSeat].filter(
        Boolean,
      );
      const limitedInitialSeats =
        this.data.passengerCount > 0
          ? initialSeats.slice(0, this.data.passengerCount)
          : initialSeats;
      this.setData({ selectedSeatsByLeg: [limitedInitialSeats] });
      this.buildGrid();
    },
  },

  methods: {
    buildGrid() {
      const {
        rowStart,
        rowEnd,
        exitRows,
        columns,
        occupiedSeats,
        reservedSeats,
        removedSeats,
        ringTooltip,
      } = this.data;
      const selectedSeats =
        this.data.selectedSeatsByLeg[this.data.currentLeg] || [];
      const selectedSet = new Set(selectedSeats);
      const occupiedSet = new Set(occupiedSeats);
      const reservedSet = new Set(reservedSeats);
      const removedSet = new Set(removedSeats);
      const rows = [];
      let selected = 0;

      for (let r = rowStart; r <= rowEnd; r++) {
        const seats = columns.map((col) => {
          if (col === "") return { col: "", rowNumber: r };
          const seatId = `${r}${col}`;
          let status = "available";
          let tooltip = "";

          if (removedSet.has(seatId)) {
            return { col, status: "removed", tooltip, seatId };
          }
          if (occupiedSet.has(seatId)) {
            status = "occupied";
          }
          if (reservedSet.has(seatId)) {
            status = "reserved";
          }
          if (status === "available" && selectedSet.has(seatId)) {
            status = seatId === this.data.ringSeat ? "ring" : "star";
            selected++;
          }
          if (status === "ring") tooltip = ringTooltip;
          return { col, status, tooltip, seatId };
        });

        rows.push({
          rowNumber: r,
          exit: exitRows.indexOf(r) !== -1,
          seats,
        });
      }

      this.setData({
        rows,
        selectedCount: selected,
        totalPrice: (selected * this.data.pricePerSeat).toFixed(2),
      });
    },

    onSwitchLeg(e) {
      const index = Number(e.currentTarget.dataset.index);
      if (index === this.data.currentLeg) return;

      const selectedSeatsByLeg = [...this.data.selectedSeatsByLeg];
      if (selectedSeatsByLeg[index] === undefined) {
        const outboundSeats = selectedSeatsByLeg[0] || [];
        const occupiedSet = new Set(this.data.occupiedSeats);
        const reservedSet = new Set(this.data.reservedSeats);
        const removedSet = new Set(this.data.removedSeats);
        const availableReturnSeats = outboundSeats.filter(
          (seatId) =>
            !occupiedSet.has(seatId) &&
            !reservedSet.has(seatId) &&
            !removedSet.has(seatId),
        );
        selectedSeatsByLeg[index] =
          this.data.passengerCount > 0
            ? availableReturnSeats.slice(0, this.data.passengerCount)
            : availableReturnSeats;
      }

      this.setData({ currentLeg: index, selectedSeatsByLeg }, () => {
        this.buildGrid();
        this.triggerEvent("legchange", {
          index,
          selectedSeats: this.data.selectedSeatsByLeg[index] || [],
        });
      });
    },

    onTapSeat(e) {
      const { row, col } = e.currentTarget.dataset;
      if (col === "") return;
      const seatId = `${row}${col}`;

      // occupied and reserved seats are locked - taps are ignored entirely
      const targetRow = this.data.rows.find((r) => r.rowNumber === Number(row));
      const targetSeat =
        targetRow && targetRow.seats.find((s) => s.col === col);
      if (
        targetSeat &&
        ["occupied", "reserved", "removed"].includes(targetSeat.status)
      ) {
        return;
      }
      const wasSelected =
        targetSeat && ["star", "ring"].includes(targetSeat.status);
      const currentSeats =
        this.data.selectedSeatsByLeg[this.data.currentLeg] || [];
      let selectedSeats = wasSelected
        ? currentSeats.filter((selectedSeat) => selectedSeat !== seatId)
        : [...currentSeats];

      if (!wasSelected) {
        if (
          this.data.passengerCount > 0 &&
          selectedSeats.length >= this.data.passengerCount
        ) {
          selectedSeats.pop();
        }
        if (this.data.passengerCount > 0) selectedSeats.push(seatId);
      }
      const selectedSet = new Set(selectedSeats);

      const rows = this.data.rows.map((r) => {
        const seats = r.seats.map((s) => {
          if (
            s.col === "" ||
            s.status === "occupied" ||
            s.status === "reserved"
          ) {
            return s;
          }
          if (selectedSet.has(s.seatId)) {
            return {
              ...s,
              status: s.seatId === this.data.ringSeat ? "ring" : "star",
              tooltip:
                s.seatId === this.data.ringSeat ? this.data.ringTooltip : "",
            };
          }
          return { ...s, status: "available", tooltip: "" };
        });
        return { ...r, seats };
      });

      const selectedCount = rows.reduce(
        (sum, r) =>
          sum +
          r.seats.filter((s) => s.status === "star" || s.status === "ring")
            .length,
        0,
      );
      const selectedSeatsByLeg = [...this.data.selectedSeatsByLeg];
      selectedSeatsByLeg[this.data.currentLeg] = selectedSeats;

      this.setData({
        rows,
        selectedSeatsByLeg,
        selectedCount,
        totalPrice: (selectedCount * this.data.pricePerSeat).toFixed(2),
      });

      this.triggerEvent("seattap", {
        seatId,
        selected: !wasSelected,
        selectedCount,
        legIndex: this.data.currentLeg,
        selectedSeats,
      });
    },

    onBack() {
      this.triggerEvent("back");
    },

    onSkip() {
      this.triggerEvent("skip");
    },

    onNext() {
      this.triggerEvent("next", {
        selectedSeats: this.data.selectedSeatsByLeg[this.data.currentLeg] || [],
        selectedSeatsByLeg: this.data.selectedSeatsByLeg,
        legIndex: this.data.currentLeg,
        totalPrice: this.data.totalPrice,
      });
    },
  },
});

