Component({
  options: {
    virtualHost: true,
  },

  properties: {
    // Lets a consuming page render the card already expanded (e.g. a
    // review/confirmation screen where the rules should be visible without
    // an extra tap). Defaults to false so existing consumers are unaffected.
    open: {
      type: Boolean,
      value: false,
