      if (banner && (banner.title || banner.subtitle)) {
        if (banner.title) patch.bannerTitle = banner.title;
        if (banner.subtitle) patch.bannerSubtitle = banner.subtitle;
      }
      if (Array.isArray(items) && items.length) {
        patch.rules = items;
      }
      if (Object.keys(patch).length) this.setData(patch);
    },
  },

