Component({
  options: {
    virtualHost: true,
  },

  properties: {
    // Lets a consuming page render the card already expanded (e.g. a
    // review/confirmation screen where the allowance should be visible
    // without an extra tap). Defaults to false so existing consumers are
    // unaffected.
    open: {
      type: Boolean,
      value: false,
    },
    // Lets a consuming page hide the per-type count badges in the header
    // (some screens, e.g. a review screen, show only the title). Defaults
    // to true so existing consumers are unaffected.
    showSummaryBadges: {
      type: Boolean,
      value: true,
    },
    // Optional API-driven content. A non-empty list replaces the built-in demo
    // content; otherwise the card keeps its defaults (existing consumers are
    // unaffected).
    summary: {
      type: Array,
      value: null,
    },
    routeList: {
      type: Array,
      value: null,
    },
  },

  observers: {
    "summary, routeList": function (summary, routeList) {
      const patch = {};
      if (Array.isArray(summary) && summary.length) {
        patch.summaryBadges = summary;
      }
      if (Array.isArray(routeList) && routeList.length) {
        patch.routes = routeList;
