Component({
  options: {
    multipleSlots: true,
  },
  data: {
    isSelected: false,
    formattedDisplayValue: "",
    selectedYear: new Date().getFullYear(),
    selectedMonth: new Date().getMonth() + 1,
    selectedDay: new Date().getDate(),
    selectedDateValue: "",
    todayYear: new Date().getFullYear(),
    todayMonth: new Date().getMonth() + 1,
    todayDay: new Date().getDate(),
    calendarDays: [],
    filteredSuggestions: [],
    isDatePickerOpen: false,
    monthNames: [
      "Janvier",
      "Février",
      "Mars",
      "Avril",
      "Mai",
      "Juin",
      "Juillet",
      "Août",
      "Septembre",
      "Octobre",
      "Novembre",
      "Décembre",
    ],
    dayNames: ["Di", "Lu", "Ma", "Me", "Je", "Ve", "Sa"],
  },
  properties: {
    label: String,
    value: String,
    displayValue: String,
    placeholder: String,
    icon: String,
    type: {
      type: String,
      value: "text",
    },
    fieldName: String,
    legIndex: Number,
    minDate: String,
    suggestions: Array,
    closeOtherPickers: Boolean,
  },
  observers: {
    value(value) {
      const parsedDate = this.parseDateValue(value);
      const nextData = {
        formattedDisplayValue:
          this.data.displayValue || this.formatFrenchDate(value),
        selectedDateValue: value || "",
      };

      if (parsedDate.year) {
        nextData.selectedYear = parsedDate.year;
        nextData.selectedMonth = parsedDate.month;
        nextData.selectedDay = parsedDate.day;
      }

      this.setData(nextData, () => {
        this.updateCalendarDays();
        this.filterSuggestions(value || "");
      });
    },
    displayValue(value) {
      this.setData({ formattedDisplayValue: value || "" });
    },
    suggestions() {
      this.filterSuggestions(this.data.value || "");
    },
  },
  methods: {
    attached() {
      const defaultDate = this.getMinimumDate();
      const parsedDate = this.parseDateValue(this.data.value || defaultDate);
      this.setData({
        selectedDateValue: this.data.value || defaultDate,
        selectedYear: parsedDate.year,
        selectedMonth: parsedDate.month,
        selectedDay: parsedDate.day,
      });
      this.updateCalendarDays();
      this.filterSuggestions(this.data.value || "");
    },
    parseDateValue(dateString) {
      if (!dateString) return {};

      const parts = dateString.split("-");
      if (parts.length !== 3) return {};

      const [year, month, day] = parts.map(Number);
      if (!year || !month || !day) return {};

      return { year, month, day };
    },
    formatFrenchDate(dateString) {
      if (!dateString) return "";

      const parsedDate = this.parseDateValue(dateString);
      if (!parsedDate.year) return dateString;

      const safeDate = new Date(
        parsedDate.year,
        parsedDate.month - 1,
        parsedDate.day,
      );
      const weekdays = ["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"];
      const months = [
        "Jan",
        "Feb",
        "Mar",
        "Apr",
        "May",
        "Jun",
        "Jul",
        "Aug",
        "Sep",
        "Oct",
        "Nov",
        "Dec",
      ];

      return `${weekdays[safeDate.getDay()]}, ${months[parsedDate.month - 1]} ${parsedDate.day}`;
    },
    getTodayDate() {
      const today = new Date();
      const year = today.getFullYear();
      const month = String(today.getMonth() + 1).padStart(2, "0");
      const day = String(today.getDate()).padStart(2, "0");
      return `${year}-${month}-${day}`;
    },
    getMinimumDate() {
      const today = this.getTodayDate();
      const minDate = this.data.minDate;
      return minDate && this.compareDateValues(minDate, today) > 0
        ? minDate
        : today;
    },
    compareDateValues(firstDate, secondDate) {
      if (!firstDate || !secondDate) return 0;

      const [firstYear, firstMonth, firstDay] = firstDate
        .split("-")
        .map(Number);
      const [secondYear, secondMonth, secondDay] = secondDate
        .split("-")
        .map(Number);

      const firstDateValue = new Date(firstYear, firstMonth - 1, firstDay);
      const secondDateValue = new Date(secondYear, secondMonth - 1, secondDay);

      return firstDateValue.getTime() - secondDateValue.getTime();
    },
    isDateDisabled(day) {
      if (!day) return true;

      const date = `${this.data.selectedYear}-${String(this.data.selectedMonth).padStart(2, "0")}-${String(day).padStart(2, "0")}`;
      return this.compareDateValues(date, this.getMinimumDate()) < 0;
    },
    handleInput(event) {
      this.setData({ isSelected: false });
      const value = event.detail.value;
      this.filterSuggestions(value);
      this.triggerEvent("input", {
        value,
        fieldName: this.data.fieldName,
        legIndex: this.data.legIndex,
      });
    },
    handleFocus() {
      // on handleFocus reset input value to empty string and isSelected to false
      this.setData({ value: "", isSelected: false });
    },
    handleSuggestionSelect(event) {
      const suggestion = event.currentTarget.dataset.suggestion;
      if (!suggestion) return;

      const selectedValue = suggestion.value || suggestion.label || "";
      this.setData({ filteredSuggestions: [], isSelected: true }, () => {
        this.triggerEvent("input", {
          value: selectedValue,
          fieldName: this.data.fieldName,
          legIndex: this.data.legIndex,
        });
      });
    },
    filterSuggestions(inputValue) {
      const query = `${inputValue || ""}`.trim().toLowerCase();
      const suggestions = Array.isArray(this.data.suggestions)
        ? this.data.suggestions
        : [];

      if (!query) {
        this.setData({ filteredSuggestions: [] });
        return;
      }

      // Flatten: City entries expand into one row per nested airport;
      // Airport entries (e.g. DAL) pass through as a single row.
      const flattened = suggestions.reduce((acc, item) => {
        if (
          (item?.Type || item?.type) === "City" &&
          Array.isArray(item.Airports || item.airports)
        ) {
          (item.Airports || item.airports).forEach((airport) => {
            const cityName = airport.CityName || airport.cityName || "";
            const code =
              airport.IATACode || airport.iataCode || airport.code || "";
            const label = `${cityName} (${code})`;
            acc.push({
              label,
              value: label,
              code,
              cityName,
              airportName: airport.Name || airport.name || "",
              raw: airport,
            });
          });
        } else if (item) {
          const cityName = item.CityName || item.cityName || "";
          const code = item.IATACode || item.iataCode || item.code || "";
          const label = `${cityName} (${code})`;
          acc.push({
            label,
            value: label,
            code,
            cityName,
            airportName: item.Name || item.name || "",
            raw: item,
          });
        }
        return acc;
      }, []);

      const matches = flattened.filter((row) => {
        const haystack = [row.label, row.airportName, row.cityName, row.code]
          .filter(Boolean)
          .join(" ")
          .toLowerCase();
        return haystack.includes(query);
      });

      this.setData({ filteredSuggestions: matches.slice(0, 6) });
    },
    openDatePicker() {
      if (this.data.type !== "date") return;

      const defaultDate = this.getMinimumDate();
      const parsedDate = this.parseDateValue(
        this.data.selectedDateValue || this.data.value || defaultDate,
      );
      if (parsedDate.year) {
        this.setData({
          selectedYear: parsedDate.year,
          selectedMonth: parsedDate.month,
          selectedDay: parsedDate.day,
          selectedDateValue:
            this.data.selectedDateValue || this.data.value || defaultDate,
        });
      }

      this.triggerEvent("openOtherPicker", {
        fieldName: this.data.fieldName,
      });

      this.setData({ isDatePickerOpen: true }, () => {
        this.updateCalendarDays();
      });
    },
    closeDatePicker() {
      this.setData({ isDatePickerOpen: false });
    },
    previousMonth() {
      const month = this.data.selectedMonth - 1;
      const year = this.data.selectedYear;
      this.setData(
        {
          selectedMonth: month < 1 ? 12 : month,
          selectedYear: month < 1 ? year - 1 : year,
        },
        () => {
          this.updateCalendarDays();
        },
      );
    },
    nextMonth() {
      const month = this.data.selectedMonth + 1;
      const year = this.data.selectedYear;
      this.setData(
        {
          selectedMonth: month > 12 ? 1 : month,
          selectedYear: month > 12 ? year + 1 : year,
        },
        () => {
          this.updateCalendarDays();
        },
      );
    },
    selectDay(event) {
      const day = event.currentTarget.dataset.day;
      if (!day || this.isDateDisabled(day)) return;

      const selectedDate = `${this.data.selectedYear}-${String(this.data.selectedMonth).padStart(2, "0")}-${String(day).padStart(2, "0")}`;
      const displayValue = this.formatFrenchDate(selectedDate);

      this.setData({
        selectedDay: day,
        selectedDateValue: selectedDate,
        formattedDisplayValue: displayValue,
        isDatePickerOpen: false,
      });

      this.triggerEvent("dateChange", {
        value: selectedDate,
        fieldName: this.data.fieldName,
        legIndex: this.data.legIndex,
      });
    },
    isToday(day) {
      return (
        day &&
        this.data.todayYear === this.data.selectedYear &&
        this.data.todayMonth === this.data.selectedMonth &&
        this.data.todayDay === day
      );
    },
    isSelected(day) {
      if (!day || !this.data.selectedDateValue) return false;

      const parsedDate = this.parseDateValue(this.data.selectedDateValue);
      return (
        parsedDate.day === day &&
        parsedDate.year === this.data.selectedYear &&
        parsedDate.month === this.data.selectedMonth
      );
    },
    isDateCellDisabled(day) {
      return this.isDateDisabled(day);
    },
    isPastDate(day) {
      // "Past" is always relative to the real calendar date (today),
      // independent of any minDate restriction used for isDateDisabled.
      if (!day) return false;
      if (this.isToday(day)) return false;

      const date = `${this.data.selectedYear}-${String(this.data.selectedMonth).padStart(2, "0")}-${String(day).padStart(2, "0")}`;
      return this.compareDateValues(date, this.getTodayDate()) < 0;
    },
    buildCellClass(day) {
      const disabled = this.isDateDisabled(day);
      const past = this.isPastDate(day);
      const today = this.isToday(day);
      const selected = this.isSelected(day);

      let cellClass = disabled ? "date-cell--disabled" : "date-cell--enabled";

      if (past) cellClass += " date-cell--past";
      if (today) cellClass += " date-cell--today";
      if (selected) cellClass += " date-cell--selected";

      return cellClass;
    },
    updateCalendarDays() {
      const year = this.data.selectedYear;
      const month = this.data.selectedMonth;
      const firstDay = new Date(year, month - 1, 1);
      const lastDay = new Date(year, month, 0);
      const daysInMonth = lastDay.getDate();
      const startDay = firstDay.getDay();
      const cells = [];
      let day = 1;

      for (let index = 0; index < 42; index++) {
        const isCurrentMonth = day <= daysInMonth && index >= startDay;
        if (isCurrentMonth) {
          cells.push({
            day,
            isCurrentMonth: true,
            cellClass: this.buildCellClass(day),
          });
          day += 1;
        } else {
          cells.push({
            day: null,
            isCurrentMonth: false,
            cellClass: "date-cell--empty",
          });
        }
      }

      this.setData({ calendarDays: cells });
    },
  },
});

