<view class="flight-search-field">
    <view class="field-icon">
        <osn-icon icon="{{icon}}" height="30" width="30" />
    </view>
    <view class="field-content">
        <text class="field-label">{{label}}</text>
        <block wx:if="{{type === 'date'}}">
            <view class="date-trigger" bindtap="openDatePicker">
                <view class="field-input">
                    {{formattedDisplayValue || displayValue || value || placeholder}}
                </view>
            </view>
            <view wx:if="{{isDatePickerOpen}}" class="date-picker-panel">
                <view class="date-picker-header">
                    <view class="date-picker-nav" bindtap="previousMonth">‹</view>
                    <view class="date-picker-title">
                        {{monthNames[selectedMonth - 1]}} {{selectedYear}}
                    </view>
                    <view class="date-picker-nav" bindtap="nextMonth">›</view>
                </view>
                <view class="date-picker-weekdays">
                    <block wx:for="{{dayNames}}" wx:key="*this">
                        <view class="weekday">{{item}}</view>
                    </block>
                </view>
                <view class="date-picker-grid">
                    <block wx:for="{{calendarDays}}" wx:key="index">
                        <view wx:if="{{item.isCurrentMonth}}" class="date-cell {{item.cellClass}}" data-day="{{item.day}}" bindtap="selectDay">
                            {{item.day}}
                        </view>
                        <view wx:else class="date-cell date-cell--empty"></view>
                    </block>
                </view>
            </view>
        </block>
        <block wx:else>
            <view class="text-input-wrapper">
                <input class="field-input" value="{{value}}" placeholder="{{placeholder}}" bindinput="handleInput" bindfocus="handleFocus" />
                <view wx:if="{{filteredSuggestions.length > 0 && isSelected=== false }}" class="suggestion-list">
                    <block wx:for="{{filteredSuggestions}}" wx:key="label">
                        <view class="suggestion-item" data-suggestion="{{item}}" bindtap="handleSuggestionSelect">
                            <text class="suggestion-label">{{item.cityName}} {{item.code}}</text>
                        </view>
                    </block>
                </view>
            </view>
        </block>
    </view>
</view>
