/**
 * Reusable technical-stop row displayed between two flight segments.
 *
 * @property {string} label - Stop duration and passenger instruction.
 */
Component({
  options: {
    styleIsolation: 'isolated'
  },

  properties: {
    label: { type: String, value: '' }
  },

  data: {
    formattedLabel: ''
