/**
 * Complete itinerary leg orchestrator (outbound or return).
 *
 * Renders the leg heading/date, delegates each visual block to a focused
 * child component and enriches the child's `expand` event with the leg id.
 *
 * @property {object|null} leg - Leg data with segments, summary and stay label.
 * @property {boolean} isLast - Enables final spacing for the last displayed leg.
 * @fires expand - `{ legId, segmentId }` when a segment detail icon is pressed.
 */
Component({
  options: {
    // Shared styles are required by the SAS runtime so timeline styles imported
    // by this component can reach its nested visual components.
    styleIsolation: 'isolated'
  },

  properties: {
    leg: {
      type: Object,
      value: null
    },
    isLast: {
      type: Boolean,
      value: false
    }
  },

  methods: {
    handleSegmentExpand(event) {
      // Keep the segment card reusable: flight-leg adds only its own context.
      this.triggerEvent('expand', {
        legId: this.properties.leg && this.properties.leg.id,
        segmentId: event.detail.segmentId
      });
    }
  }
});

