// ============================================================================
// i18n ENGINE
// Detects user's system language, loads translations, provides t() function
// ============================================================================

import { storage } from "../storage.js";
import fr from "./locales/fr.js";
import en from "./locales/en.js";

// ── Configuration ───────────────────────────────────────
const SUPPORTED_LOCALES = ["fr"]; // , en
const DEFAULT_LOCALE = "fr";
const STORAGE_KEY = "app_locale";

// ── Locale Registry ─────────────────────────────────────
const locales = { fr, en };

// ── Current State ───────────────────────────────────────
let currentLocale = DEFAULT_LOCALE;
let currentStrings = en;

/**
 * Detects the user's preferred locale from system settings.
 * @returns {string} Locale code ('fr', 'en')
 */
const detectLocale = () => {
  try {
    const sysLang = wx.getSystemInfoSync().language || "";
    const normalized = sysLang.split(/[-_]/)[0].toLowerCase();
    console.log(SUPPORTED_LOCALES, normalized, sysLang);
    return SUPPORTED_LOCALES.includes(normalized) ? normalized : DEFAULT_LOCALE;
  } catch (e) {
    return DEFAULT_LOCALE;
  }
};

/**
 * Initializes the i18n system.
 * Call once in App.onLaunch(), before any page renders.
 *
 * Priority: stored preference > system language > default (fr)
 */
export const init = () => {
  const stored = storage.get(STORAGE_KEY);
  const locale = stored || detectLocale();
  setLocale(locale);
};

/**
 * Changes the active locale.
 * @param {string} locale - Locale code
 */
export const setLocale = (locale) => {
  if (!locales[locale]) {
    console.warn(
      `[i18n] Locale '${locale}' not available, using '${DEFAULT_LOCALE}'`,
    );
    locale = DEFAULT_LOCALE;
  }

  currentLocale = locale;
  currentStrings = locales[locale];
  storage.set(STORAGE_KEY, locale);

  // Update EventBus so pages can react
  try {
    const app = getApp();
    if (app?.globalData?.eventBus) {
      app.globalData.eventBus.setState("app.locale", locale);
    }
  } catch (e) {
    // getApp() may not be available during very early init
  }
};

/**
 * Returns the current locale code.
 * @returns {string}
 */
export const getLocale = () => currentLocale;

/**
 * Core translation function.
 * Looks up a key and optionally interpolates {variables}.
 *
 * @param {string} key - Translation key (e.g., 'home.hero.line1')
 * @param {Object} [params] - Interpolation variables
 * @returns {string} Translated string, or the key itself as fallback
 */
export const t = (key, params) => {
  let str = currentStrings[key];

  // Fallback to French, then to raw key
  if (str === undefined) {
    str = fr[key];
    if (str === undefined) {
      console.warn(`[i18n] Missing key: '${key}'`);
      return key;
    }
  }

  if (params) {
    Object.keys(params).forEach((param) => {
      str = str.replace(
        new RegExp(`\\{${param}\\}`, "g"),
        String(params[param]),
      );
    });
  }

  return str;
};

/**
 * Returns translation strings as a flat object.
 * Used to pass the dictionary to page data for WXML binding.
 *
 * @param {string} [prefix] - Optional prefix filter (e.g., 'home.')
 * @returns {Object} Flat key-value translation strings
 */
export const getStrings = (prefix) => {
  if (!prefix) return { ...currentStrings };

  const subset = {};
  const keys = Object.keys(currentStrings);
  for (let i = 0; i < keys.length; i++) {
    if (keys[i].indexOf(prefix) === 0) {
      subset[keys[i]] = currentStrings[keys[i]];
    }
  }
  return subset;
};

