// PAYMENT (Orange Money)
// ============================================================================

/**
 * Initiates Orange Money payment via native plugin
 *
 * @async
 * @param {Object} options - Payment options
 * @param {number} options.amount - Amount in USD
 * @param {string} options.orderId - Unique order reference
 * @param {string} options.description - Payment description
 * @param {string} [options.customerMsisdn] - Customer phone number
 * @returns {Promise<PaymentResultData>} Payment result
 * @throws {Error} If payment fails or is cancelled
 *
 * @example
 * const payment = await payWithOrangeMoney({
 *   amount: 500,
 *   orderId: 'ORD-12345',
 *   description: 'Fly from Dakar to Paris',
 * });
 * if (payment.status === 'SUCCESS') {
 *   // book flight, show confirmation, etc.
 * }
 */
export const payWithOrangeMoney = async ({
  amount,
  orderId,
  description,
  customerMsisdn,
  serviceId,
  idService,
  txnid,
  caction,
}) => {
  try {
    /** @type {MerchantPayResponseData} */
    const response = await withTimeout(
      invokePlugin("merchantPay", {
        amount: String(amount),
        currency: PAYMENT_CONFIG.CURRENCY,
        receiverName: PAYMENT_CONFIG.MERCHANT_NAME,
        receiver: PAYMENT_CONFIG.MERCHANT_CODE,
        orderId,
        orderDescription: description,
        // Carry the order id as serviceId/idService so the txn-verify oracle can
        // exact-match this debit later (money-safety recovery).
        ...(serviceId && { serviceId }),
        ...(idService && { idService }),
        // Identical-transaction retry (merchant-pay): confirmed duplicate.
        ...(txnid && { txnid }),
        ...(caction != null && { caction }),
        ...(customerMsisdn && { customerMsisdn }),
      }),
      PAY_TIMEOUT_MS,
      "Payment timed out",
    );

    // invokePlugin already unwraps res.data, so return directly
    return { status: "SUCCESS", ...response };
  } catch (error) {
    console.warn("[Native] payWithOrangeMoney failed:", error.message);

    // Only use fallback in development mode
    if (__DEV__) {
      return {
        status: "SUCCESS",
        transactionId: `DEV-${Date.now()}`,
        orderId,
        amount,
        activationCode: `LPA:1$smdp.orange-sonatel.com$DEV-${Date.now()}`,
      };
    }

    throw error;
  }
};
