  PACKAGE_AVAILABILITY:
    "/storefront-api/check-availability/{searchId}/{packageId}",
  FARE_RULES:
    "/storefront-api/get-baggage-and-fare-rules-v2/{searchId}/{packageId}",
  TAX_SURCHARGE: "/storefront-api/get-tax-breakdown/{searchId}/{packageId}",
  FARE_FAMILY_OPTIONS:
    "/storefront-api/get-fare-family-options-and-fare-rules/{searchId}/{packageId}/{packageId}",
};

const storefrontPath = (template, searchId, packageId) =>
  template
    .replaceAll("{searchId}", encodeURIComponent(String(searchId)))
    .replaceAll("{packageId}", encodeURIComponent(String(packageId)));

const upstreamError = (data, fallback) => {
  if (data?.result === "error" || data?.success === false) {
    const error = new Error(data.error_message || data.reason || fallback);
    error.code = data.error_code;
    return error;
  }
  return null;
};

/**
 * Substitutes `{name}` placeholders in an endpoint template.
 * @param {string} template - e.g. "/storefront-api/x/{searchId}/{packageId}"
 * @param {Object<string,string>} params - e.g. { searchId, packageId }
 * @returns {string} Concrete path with every placeholder encoded and replaced.
 * @throws {Error} When a placeholder has no matching, non-empty value.
 */
const buildPath = (template, params = {}) =>
  template.replace(/\{(\w+)\}/g, (_, key) => {
    const value = params[key];
    if (value === undefined || value === null || value === "") {
      throw new Error(`Missing "${key}" for ${template}`);
    }
    return encodeURIComponent(String(value));
  });

// ============================================================================
// BACKEND API CLASS
// ============================================================================

/**
 * Service for your application's API operations.
 * All methods automatically handle authentication.
 *
 * Pattern from eSIM:
 * 1. Call authenticate() before each request
 * 2. Use httpClient for HTTP operations
 * 3. Use sculpt for response transformation
 *
 * @class BackendAPI
 */
class BackendAPI {
  /** @type {import('./http').HttpClient} */
  #client = httpClient;

  /**
   * Autocompletes city names for flight search.
   * @async
   * @param {string} query - Partial city name or airport code
   * @returns {Promise<Array>} List of matching cities/airports
   */
  async getAutocompleteCity(query) {
    const normalizedQuery = String(query || "").trim();
    if (!normalizedQuery) return [];

    const res = await this.#client.get(ENDPOINTS.AUTOCOMPLETE_CITY, {
      query: { q: normalizedQuery },
      baseUrl: config.PUBLIC_BASE_URL,
    });
    if (!res.success) {
      throw new Error(
        res.error?.message || "Failed to fetch autocomplete results",
      );
    }
    const items = Array.isArray(res?.data) ? res.data : [];

    const airportsCity = items.flatMap((item) =>
      mapAirportEntity(item, AirportSchema),
    );

    return airportsCity;
  }

  /**
   * Fetches  fares for a flight search.
   *
   * @async
   * @param {Object} params - Flight search parameters
   * @param {string} params.departDate - Outbound departure date
   * @param {string} params.originIata - Outbound origin airport
   * @param {string} params.destinationIata - Outbound destination airport
   * @param {string} params.returnDate - Return departure date
   * @param {string} params.siteName - Site name sent in the request header
   * @param {string} [params.currency='XOF'] - Fare currency
   * @param {string} [params.type='roundtrip'] - Trip type: 'roundtrip', 'oneway', or 'multicity'
   * @param {string} [params.seat_class='economy'] - Seat class: 'economy', 'business', etc.
   * @param {Object} [params.passengerCount] - Passenger infos
   * @returns {Promise<Object|Array>} Fares returned by the API
   */

  async GetPhares({
    departDate,
    originIata,
    destinationIata,
    returnDate,
    segments, // for multicity: [{ date, from, to }, ...]
    siteName = config.SITENAME,
    type,
    seat_class,
    passengerCount,
    affiliateId = config.AFFILIATE_ID,
    apiUser = config.API_USER,
    apiPass = config.API_PASS,
    siteId = config.SITE_ID,
    campaignId = config.CAMPAIGN,
    currency = "XOF",
  } = {}) {
    const tripType = type || "roundtrip";

    const query = {
      affiliate_id: affiliateId,
      api_user: apiUser,
      api_pass: apiPass,
      site_id: siteId,
      campaign: campaignId,
      currency,
      type: tripType,
      seat_class: seat_class || "economy",
      num_adults: passengerCount?.adults || 1,
      num_children: passengerCount?.children || 0,
      num_infants: passengerCount?.infants + passengerCount?.infantsOnLap || 0,
      show_amenities: 1,
      flexible_date: 0,
      nearby_airports: 0,
    };

    // Build segN_date / segN_from / segN_to dynamically depending on trip type
    if (tripType === "multicity") {
      if (!Array.isArray(segments) || segments.length === 0) {
        throw new Error("multicity requires a non-empty `segments` array");
      }
      segments.forEach((seg, i) => {
        query[`seg${i}_date`] = seg.date;
        query[`seg${i}_from`] = seg.from;
        query[`seg${i}_to`] = seg.to;
      });
    } else {
      // oneway or roundtrip both start with seg0
      query.seg0_date = departDate || "";
      query.seg0_from = originIata;
      query.seg0_to = destinationIata;

      if (tripType === "roundtrip") {
        query.seg1_date = returnDate || "";
        query.seg1_from = destinationIata;
        query.seg1_to = originIata;
      }
      // oneway: no seg1_* keys at all
    }

    const res = await this.#client.get(ENDPOINTS.FARES, {
      query,
      siteName,
    });
    if (!res.success) {
      throw new Error(res.error?.message || "Failed to fetch fares");
    }

    const normalizedInput = {
      ...res?.data,
      packages:
        res?.data?.packages &&
        typeof res?.data?.packages === "object" &&
        !Array.isArray(res?.data?.packages)
          ? Object.values(res?.data?.packages)
          : res?.data?.packages,
    };

    const fares = sculpt.data({
      data: normalizedInput,
      to: FaresSchema,
    });
    return fares;
  }

  async getFareFamilyOptions(searchId, packageId) {
    const res = await this.#client.get(
      storefrontPath(ENDPOINTS.FARE_FAMILY_OPTIONS, searchId, packageId),
    );
    if (!res.success) {
      throw new Error(res.error?.message || "Failed to fetch fare families");
    }
    const error = upstreamError(res.data, "Failed to fetch fare families");
    if (error) throw error;
    return sculpt.data({
      data: { families: normalizeFareFamilies(res.data) },
      to: FareFamilyResponseSchema,
    });
  }

  async applyUpgrade(searchId, packageId, fareFamilyIndex) {
    const res = await this.#client.post(
      storefrontPath(ENDPOINTS.UPGRADE_FLIGHT, searchId, packageId),
      { ff: Number(fareFamilyIndex) },
    );
    if (!res.success) {
      throw new Error(res.error?.message || "Failed to apply fare upgrade");
    }
    const error = upstreamError(res.data, "Failed to apply fare upgrade");
    if (error) throw error;
    const normalized = normalizeUpgradeResponse(res.data);
    return sculpt.data({
      data: normalized,
      to: UpgradeResponseSchema,
    });
  }

  async checkAvailability(searchId, packageId) {
    const res = await this.#client.get(
      storefrontPath(ENDPOINTS.PACKAGE_AVAILABILITY, searchId, packageId),
    );
    if (!res.success) {
      throw new Error(res.error?.message || "Failed to check availability");
    }
    const data = res.data || {};
    if (data.success === false || data.result === "error") {
      const error = upstreamError(data, "Flight is no longer available");
      throw error || new Error("Flight is no longer available");
    }
    return sculpt.data({
      data: normalizeAvailability(data),
      to: AvailabilitySchema,
    });
  }

  async book(payload, currency) {
    const res = await this.#client.post(ENDPOINTS.BOOKING, payload, {
      headers: {
        Currency: currency,
      },
    });
    if (!res.success) {
      throw new Error(res.error?.message || "Failed to create booking");
    }
    const data = res.data || {};
    const error = upstreamError(data, "Booking failed");
    if (error) throw error;
    if (!data.booking_id && !data.booking_details && data.error) {
      throw new Error(data.reason || data.error || "Booking failed");
    }
    return sculpt.data({
      data: normalizeBookingResponse(data),
      to: BookingResponseSchema,
    });
