// ============================================================================
// SHARED DEFENSIVE READERS
// The storefront-read documents (baggage/fare rules, tax breakdown) are opaque
// in the upstream contract (`additionalProperties: true`, no field names), so
// every value below is resolved through a list of candidate paths with a safe
// fallback. When a real payload does not match, the schema yields an empty
// model. These readers do not call the API or update page state.
// ============================================================================

/**
 * Check whether a value is a non-array object.
 * @param {*} value - Value to inspect.
 * @returns {boolean} Whether the value is an object.
 * @example isPlainObject({});
 */
export const isPlainObject = (value) =>
  value !== null && typeof value === "object" && !Array.isArray(value);

/**
 * Read the first non-empty candidate path.
 * @param {Object} source - API document.
 * @param {string[]} paths - Candidate dot paths.
 * @returns {*} First available value, or undefined.
 * @example pickPath({ totals: { base: 10 } }, ['totals.base']);
 */
export const pickPath = (source, paths) => {
  for (const path of paths) {
    const value = String(path)
      .split(".")
      .reduce(
        (acc, part) =>
          isPlainObject(acc) || Array.isArray(acc) ? acc[part] : undefined,
        source,
      );
    if (value !== undefined && value !== null && value !== "") return value;
  }
  return undefined;
};

/** A map keyed by id or an array both become an array of entries. */
const toEntryList = (value) =>
  Array.isArray(value)
    ? value
    : isPlainObject(value)
      ? Object.keys(value).map((key) => ({ key, ...(isPlainObject(value[key]) ? value[key] : { value: value[key] }) }))
      : [];

/**
 * Read a number or a dot-decimal monetary string.
 * @param {*} value - Monetary value.
 * @returns {number} Finite amount, or zero.
 * @example toAmount('1 234.50');
 */
export const toAmount = (value) => {
  if (typeof value === "number") return Number.isFinite(value) ? value : 0;
  const numeric = Number(String(value ?? "").replace(/[^\d.-]/g, ""));
  return Number.isFinite(numeric) ? numeric : 0;
};

const isTruthyFlag = (value) =>
  value === true ||
  value === 1 ||
  ["1", "true", "yes", "y", "allowed", "included"].includes(
    String(value ?? "").trim().toLowerCase(),
  );

const PTC_LABELS = {
  adt: "Adult",
  adult: "Adult",
  cnn: "Child",
  chd: "Child",
  child: "Child",
  inf: "Infant",
  ins: "Infant (in seat)",
  infant: "Infant",
};

const ptcLabel = (code) =>
  PTC_LABELS[String(code || "").trim().toLowerCase()] ||
  String(code || "").trim().toUpperCase() ||
  "Passenger";

/**
 * Normalize package fares into passenger-type quote lines.
 * @param {Object} faresNode - Search package fares.
 * @returns {Object[]} Normalized price lines.
 * @example buildFareBreakdown({ adt: { quantity: 1, total: 100 } });
 */
export function buildFareBreakdown(faresNode) {
  if (!isPlainObject(faresNode)) return [];
  return Object.keys(faresNode)
    .filter((key) => isPlainObject(faresNode[key]))
    .map((key) => {
      const fare = faresNode[key];
      const quantity =
        toAmount(
          pickPath(fare, ["quantity", "qty", "count", "num_passengers", "pax"]),
        ) || 0;
      const total = toAmount(pickPath(fare, ["total", "total_fare", "amount"]));
      const base = toAmount(pickPath(fare, ["base", "base_fare", "fare"]));
      const tax = toAmount(
        pickPath(fare, ["tax", "taxes", "tax_total", "total_tax"]),
      );
      return {
        ptc: String(fare.type || key).toUpperCase(),
        code: String(key).toLowerCase(),
        label: ptcLabel(fare.type || key),
        quantity,
        base,
        tax,
        total: total || base + tax,
      };
    })
    .filter((line) => line.quantity > 0 || line.total > 0);
}

/**
 * Normalize baggage groups from supported candidate shapes.
 * @param {Object|Object[]} data - API document.
 * @returns {Object[]} Baggage by passenger type and direction.
 * @example extractBaggageGroups({ baggage: [] });
 */
export function extractBaggageGroups(data) {
  const root =
    pickPath(data, [
      "baggage",
      "baggage_allowance",
      "baggages",
      "baggage_info",
      "bags",
    ]) ?? data;

  const readPiece = (node, paths) => {
    const bag = pickPath(node, paths);
    if (bag === undefined) return null;
    if (isPlainObject(bag)) {
      const quantity = toAmount(
        pickPath(bag, ["quantity", "pieces", "count", "qty"]),
      );
      return {
        included:
          isTruthyFlag(pickPath(bag, ["included", "is_included", "allowed"])) ||
          quantity > 0,
        quantity: quantity || undefined,
        weight: pickPath(bag, [
          "weight",
          "max_weight",
          "weight_kg",
          "allowance",
          "size",
        ]),
      };
    }
    return {
      included: isTruthyFlag(bag) || toAmount(bag) > 0,
      quantity: toAmount(bag) || undefined,
    };
  };

  const pushGroup = (out, ptc, direction, node) => {
    if (!isPlainObject(node)) return;
    out.push({
      ptc: String(ptc || "ADT").toUpperCase(),
      direction: String(direction ?? "0"),
      routeLabel: pickPath(node, [
        "route",
        "route_label",
        "od",
        "origin_destination",
        "segment",
      ]),
      personalItem: readPiece(node, [
        "personal_item",
        "personal",
        "personalItem",
        "pi",
      ]),
      carryOn: readPiece(node, [
        "carry_on",
        "carryon",
        "carryOn",
        "hand",
        "cabin",
      ]),
      checked: readPiece(node, [
        "checked",
        "checked_bag",
        "checkedBag",
        "hold",
        "hold_bag",
      ]),
    });
  };

  const groups = [];
  if (Array.isArray(root)) {
    root.forEach((node, index) =>
      pushGroup(
        groups,
        pickPath(node, ["ptc", "passenger_type", "type"]),
        pickPath(node, ["direction", "leg", "od_index", "group"]) ?? index,
        node,
      ),
    );
  } else if (isPlainObject(root)) {
    Object.keys(root).forEach((ptcKey) => {
      const byPtc = root[ptcKey];
      const looksLikeLeaf =
        isPlainObject(byPtc) &&
        ["checked", "carry_on", "carryon", "personal_item"].some(
          (leaf) => leaf in byPtc,
        );
      if (looksLikeLeaf) {
        pushGroup(groups, ptcKey, "0", byPtc);
      } else if (isPlainObject(byPtc)) {
        Object.keys(byPtc).forEach((dirKey) =>
          pushGroup(groups, ptcKey, dirKey, byPtc[dirKey]),
        );
      }
    });
  }
  return groups;
}

/**
 * Normalize fare-rule groups from supported candidate shapes.
 * @param {Object|Object[]} data - API document.
 * @returns {Object[]} Fare rules by passenger type and direction.
 * @example extractFareRuleGroups({ fare_rules: [] });
 */
export function extractFareRuleGroups(data) {
  const root =
    pickPath(data, [
      "fare_rules",
      "fareRules",
      "rules",
      "fare_rule",
      "penalties",
    ]) ?? data;

  const readGroup = (ptc, direction, node) => {
    if (!isPlainObject(node)) return null;
    const penalties = isPlainObject(
      pickPath(node, ["penalties", "penalty", "changes"]),
    )
      ? pickPath(node, ["penalties", "penalty", "changes"])
      : node;
    return {
      ptc: String(ptc || "ADT").toUpperCase(),
      direction: String(direction ?? "0"),
      brandName: pickPath(node, [
        "fare_family",
        "fare_family_name",
        "brand",
        "brand_name",
        "fare_basis",
      ]),
      cabin: pickPath(node, ["cabin", "cabin_class", "cabin_name", "class"]),
      changeable: isTruthyFlag(
        pickPath(penalties, [
          "changeable",
          "change_allowed",
          "changes_allowed",
          "exchangeable",
        ]),
      ),
      changeFee: pickPath(penalties, [
        "change_fee",
        "change_penalty",
        "exchange_fee",
      ]),
      refundable: isTruthyFlag(
        pickPath(penalties, [
          "refundable",
          "refund_allowed",
          "cancellation_allowed",
        ]),
      ),
      refundFee: pickPath(penalties, [
        "refund_fee",
        "cancel_fee",
        "cancellation_fee",
      ]),
      texts: [
        pickPath(node, ["text", "rule_text", "description", "details"]),
      ]
        .flat()
        .filter(Boolean),
    };
  };

  const groups = [];
  if (Array.isArray(root)) {
    root.forEach((node, index) => {
      const group = readGroup(
        pickPath(node, ["ptc", "passenger_type", "type"]),
        pickPath(node, ["direction", "leg", "group"]) ?? index,
        node,
      );
      if (group) groups.push(group);
    });
  } else if (isPlainObject(root)) {
    Object.keys(root).forEach((ptcKey) => {
      const byPtc = root[ptcKey];
      const looksLikeLeaf =
        isPlainObject(byPtc) &&
        ["changeable", "refundable", "penalties", "text"].some(
          (leaf) => leaf in byPtc,
        );
      if (looksLikeLeaf) {
        const group = readGroup(ptcKey, "0", byPtc);
        if (group) groups.push(group);
      } else if (isPlainObject(byPtc)) {
        Object.keys(byPtc).forEach((dirKey) => {
          const group = readGroup(ptcKey, dirKey, byPtc[dirKey]);
          if (group) groups.push(group);
        });
      }
    });
  }
  return groups;
}

/**
 * Normalize tax lines from supported candidate shapes.
 * @param {Object} data - API document.
 * @returns {Object[]} Non-zero tax lines.
 * @example extractTaxLines({ taxes: [{ code: 'XT', amount: 5 }] });
 */
export function extractTaxLines(data) {
  const root =
    pickPath(data, [
      "taxes",
      "tax_breakdown",
      "breakdown",
      "lines",
      "items",
      "tax_lines",
    ]) ?? [];
  return toEntryList(root)
    .map((entry) => ({
      code: pickPath(entry, ["code", "tax_code", "key", "id"]) || "",
      label:
        pickPath(entry, ["label", "name", "description", "title"]) ||
        pickPath(entry, ["code", "tax_code", "key"]) ||
        "Tax",
      amount: toAmount(
        pickPath(entry, ["amount", "value", "total", "price"]),
      ),
    }))
    .filter((line) => line.amount !== 0);
}

