// ============================================================================
// FLIGHT DETAILS HELPERS
// Build the Flight details view model without storage, navigation or page state.
// ============================================================================

import { formatDuration, formatPrice } from "../formatters/index";
import { getLocale, t } from "../i18n/index.js";

/**
 * Translates weekday and month abbreviations already formatted by the mapper.
 *
 * @param {string} value - Formatted date label.
 * @returns {string} Localized date label.
 */
function getDateLabel(value) {
  return String(value || "").replace(
    /\b(Mon|Tue|Wed|Thu|Fri|Sat|Sun|Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Sept|Oct|Nov|Dec)\b/g,
    (token) => t(`flightDetails.date.${token === "Sep" ? "Sept" : token}`),
  );
}

/**
 * Converts an AM/PM time label to 24-hour format for French.
 *
 * @param {string} value - Time label returned by the mapper.
 * @returns {string} Localized time label.
 */
function getTimeLabel(value) {
  const label = String(value || "");
  if (getLocale() !== "fr") return label;
  const match = label.match(/^(\d{1,2}):([0-5]\d)(:[0-5]\d)?\s*([AP]M)$/i);
  if (!match || Number(match[1]) < 1 || Number(match[1]) > 12) return label;
  const hours =
    (Number(match[1]) % 12) + (match[4].toUpperCase() === "PM" ? 12 : 0);
  return `${String(hours).padStart(2, "0")}:${match[2]}${match[3] || ""}`;
}

/**
 * Localizes the minute unit in an already formatted duration.
 *
 * @param {string} value - Formatted duration, for example "2h 30m".
 * @returns {string} Localized duration.
 */
function getDurationLabel(value) {
  return value.replace(/(\d+)\s*m\b/g, (_, count) =>
    t("flightDetails.duration.minutes", { count }),
  );
}

/**
 * Returns a location name only when its IATA code matches.
 *
 * @param {Object|string} value - Search location.
 * @param {string} code - IATA code to match.
 * @returns {string} Matching location name or an empty string.
 */
function getLocationName(value, code) {
  if (value && typeof value === "object") {
    return value.code === code ? value.name || value.label || "" : "";
  }
  const match = String(value || "").match(/^(.+?)\s*\(([^)]+)\)$/);
  return match && match[2] === code ? match[1].trim() : "";
}

/**
 * Builds the departure or arrival data displayed for a segment.
 *
 * @param {Object} segment - Normalized API segment.
 * @param {string} side - "departure" or "arrival".
 * @param {string} code - Endpoint IATA code.
 * @param {Object} booking - Flight details source data.
 * @returns {Object} Display-ready endpoint.
 */
function getEndpoint(segment, side, code, booking) {
  const locations = [
    booking.from,
    booking.to,
    ...(booking.multiCityLegs || []).flatMap((leg) => [leg.from, leg.to]),
  ];
  const schedule = segment[`${side}_time`] || {};
  return {
    code,
    city:
      locations
        .map((location) => getLocationName(location, code))
        .find(Boolean) || "",
    airport: segment[`${side}_airport_name`] || "",
    date: getDateLabel(schedule.date),
    time: getTimeLabel(schedule.time),
  };
}

/**
 * Formats a segment or leg duration.
 *
 * @param {number|string} value - Duration in seconds or already formatted text.
 * @returns {string} Display-ready duration.
 */
function getDuration(value) {
  if (typeof value === "string" && /[hm]/.test(value)) {
    return getDurationLabel(formatDuration(value));
  }
  const seconds = Number(value);
  return Number.isFinite(seconds) && seconds > 0
    ? getDurationLabel(formatDuration("", Math.round(seconds / 60)))
    : "";
}

/**
 * Parses a complete timestamp only when it contains an explicit timezone.
 *
 * @param {string} value - Raw API timestamp.
 * @returns {number|null} Timestamp in milliseconds or null.
 */
function getTimestamp(value) {
  if (typeof value !== "string") return null;
  const match = value.match(
    /^(\d{4}-\d{2}-\d{2})[T ](?:[01]\d|2[0-3]):[0-5]\d(?::[0-5]\d(?:\.\d{1,3})?)?(?:Z|[+-](?:0\d|1[0-4]):[0-5]\d)$/i,
  );
  if (!match) return null;
  const date = new Date(`${match[1]}T00:00:00Z`);
  if (
    !Number.isFinite(date.getTime()) ||
    date.toISOString().slice(0, 10) !== match[1]
  ) {
    return null;
  }
  const timestamp = Date.parse(value.replace(" ", "T"));
  return Number.isFinite(timestamp) ? timestamp : null;
}

/**
 * Builds the connection label between two segments of the same leg.
 *
 * @param {Object} segment - Segment arriving at the connection.
 * @param {Object|undefined} next - Following segment.
 * @param {string} arrivalCode - Arrival airport code.
 * @returns {string} Connection label.
 */
function getConnectionLabel(segment, next, arrivalCode) {
  if (!next) return "";
  const departureCode = next.departure_code || "";
  const airport = arrivalCode || departureCode;
  const connection =
    arrivalCode && departureCode && arrivalCode !== departureCode
      ? t("flightDetails.airportChange", {
          from: arrivalCode,
          to: departureCode,
        })
      : airport
        ? t("flightDetails.connection", { airport })
        : t("flightDetails.connectionUnknownAirport");
  const arrival = getTimestamp(segment.arrival_time?.raw);
  const departure = getTimestamp(next.departure_time?.raw);
  if (arrival === null || departure === null || departure <= arrival) {
    return connection;
  }
  const minutes = Math.round((departure - arrival) / 60000);
  return minutes > 0
    ? t("flightDetails.connectionWithDuration", {
        connection,
        duration: getDurationLabel(formatDuration("", minutes)),
      })
    : connection;
}

/**
 * Adapts the selected flight to the Flight details components.
 *
 * @param {Object} booking - Selected flight and search locations.
 * @returns {Object|null} Display-ready itinerary or null.
 */
export function createFlightDetails(booking = {}) {
  const flight = booking.selectedFlight || {};
  const itinerary = Array.isArray(flight.itinerary) ? flight.itinerary : [];
  const tripType = String(
    flight.info?.trip_type || booking.activeTab || "",
  ).toLowerCase();
  const isRoundTrip = tripType === "roundtrip";
  const legs = itinerary
    .map((leg, legIndex) => {
      const sourceSegments = Array.isArray(leg?.segments)
        ? leg.segments.filter(Boolean)
        : [];
      const segments = sourceSegments.map((segment, index) => {
        const fromCode =
          segment.departure_code ||
          (index === 0 ? leg.origin_airport_code : "") ||
          "";
        const toCode =
          segment.arrival_code ||
          (index === sourceSegments.length - 1
            ? leg.destination_airport_code
            : "") ||
          "";
        const airline =
          segment.carrier || segment.airline || flight.airline || {};
        const name =
          typeof airline === "string"
            ? airline
            : airline.name || airline.code || "";
        return {
          id: `leg-${legIndex + 1}-segment-${index + 1}`,
          departure: getEndpoint(segment, "departure", fromCode, booking),
          arrival: getEndpoint(segment, "arrival", toCode, booking),
          carrier: {
            name: name || t("flightDetails.notProvided"),
            logo: airline.logo || "",
            fallbackLabel:
              airline.code || name.slice(0, 3).toUpperCase() || "—",
            theme: airline.theme || "",
            framed: airline.framed !== false,
          },
          duration: getDuration(
            segment.duration ??
              (sourceSegments.length === 1 ? leg.duration : null),
          ),
          stopAfter: getConnectionLabel(
            segment,
            sourceSegments[index + 1],
            toCode,
          ),
        };
      });
      if (!segments.length) return null;

      const first = segments[0];
      const last = segments[segments.length - 1];
      const destination = last.arrival.city || last.arrival.code;
      const count = leg.num_stops;
      const stops =
        count !== null &&
        count !== undefined &&
        count !== "" &&
        Number.isFinite(Number(count))
          ? Math.max(segments.length - 1, Math.floor(Number(count)))
          : segments.length - 1;

      return {
        id: isRoundTrip
          ? legIndex === 0
            ? "outbound"
            : "return"
          : `leg-${legIndex + 1}`,
        title: destination
          ? t("flightDetails.flightTo", { destination })
          : t("flightDetails.title"),
        direction: isRoundTrip
          ? t(
              legIndex === 0
                ? "flightDetails.direction.departure"
                : "flightDetails.direction.return",
            )
          : itinerary.length === 1
            ? t("flightDetails.direction.departure")
            : t("flightDetails.direction.flight", { number: legIndex + 1 }),
        dateLabel: first.departure.date,
        travelDate: first.departure.date,
        duration: getDuration(leg.duration),
        stopsLabel:
          stops === 0
            ? t("flightDetails.stops.direct")
            : t(
                stops === 1
                  ? "flightDetails.stops.one"
                  : "flightDetails.stops.other",
                { count: stops },
              ),
        segments,
        summary: {
          city: destination,
          dateTimeLabel: [last.arrival.date, last.arrival.time]
            .filter(Boolean)
            .join(", "),
        },
        stayLabel: "",
      };
    })
    .filter(Boolean);

  if (!legs.length) return null;

  const quote = flight.prices?.total_price;
  const hasQuote =
    quote !== null &&
    quote !== undefined &&
    quote !== "" &&
    Number.isFinite(Number(quote));
  const seats = flight.info?.seats_available;
  return {
    legs,
    scarcityCount:
      seats !== null &&
      seats !== undefined &&
      seats !== "" &&
      Number.isFinite(Number(seats))
        ? Math.max(0, Number(seats))
        : null,
    total: {
      amount: hasQuote
        ? formatPrice(Number(quote), {
            locale: "fr-FR",
            includeCurrency: false,
          })
        : t("flightDetails.notAvailable"),
      currency: flight.info?.currency || "",
      caption: t("flightDetails.total.caption"),
    },
    hasQuote,
  };
}

/**
 * Builds the compact itinerary summary consumed by the next booking step.
 *
 * @param {Object} details - Model returned by createFlightDetails.
 * @returns {Object[]} Compact leg summaries.
 */
export function createTripSummary(details) {
  return details.legs.map((leg) => {
    const first = leg.segments[0];
    const last = leg.segments[leg.segments.length - 1];
    return {
      id: leg.id,
      dateLabel: leg.dateLabel,
      direction: leg.direction,
      airlineLogo: first.carrier.logo,
      fromCode: first.departure.code,
      fromTime: first.departure.time,
      toCode: last.arrival.code,
      toTime: last.arrival.time,
      stopLabel: leg.stopsLabel,
      duration: leg.duration,
    };
  });
}

