// ============================================================================
// PASSENGER INFORMATION HELPERS
// Adapt the storefront-read API models (baggage/fare rules, tax breakdown) and
// the selected package to the passenger information page + component props.
// These functions never call the API or mutate page state.
// ============================================================================

import { formatPrice } from "../formatters/index";
import { TRAVEL_CABIN_CLASSES } from "../constants/index";
import { t } from "../i18n/index";
import { getGenderOptions } from "./passengerForm";

const BAGGAGE_ICONS = {
  personal: "/assets/icons/global/baggage-icon-orange.png",
  carryon: "/assets/icons/global/baggage-icon-blue.png",
  checked: "/assets/icons/global/baggage-icon-gray.png",
};
const FARE_RULE_ICONS = {
  check: "/assets/icons/fare-rules/check.png",
  dash: "/assets/icons/fare-rules/dash.png",
  x: "/assets/icons/fare-rules/x.png",
};

// FlightHub PTC code → the internal passenger-count key used across the booking
// flow (`buildPassengers` in the flights page uses the same keys).
const PTC_TO_COUNT_KEY = {
  adt: "adults",
  adult: "adults",
  cnn: "children",
  chd: "children",
  child: "children",
  inf: "infants",
  ins: "infants",
  infant: "infants",
};
const COUNT_KEY_ORDER = ["adults", "children", "infants", "infantsOnLap"];

const isObject = (value) =>
  value !== null && typeof value === "object" && !Array.isArray(value);

const asArray = (value) => (Array.isArray(value) ? value.filter(Boolean) : []);

const getItinerary = (booking) => {
  const flight = booking.selectedFlight || {};
  return Array.isArray(flight.itinerary) ? flight.itinerary.filter(Boolean) : [];
};

const isRoundTrip = (booking) => {
  const flight = booking.selectedFlight || {};
  return (
    String(flight.info?.trip_type || booking.activeTab || "").toLowerCase() ===
    "roundtrip"
  );
};

const directionLabel = (booking, index, total) => {
  if (isRoundTrip(booking)) return index === 0 ? t("passengerInformation.direction.departure") : t("passengerInformation.direction.return");
  return total === 1 ? t("passengerInformation.direction.departure") : t("passengerInformation.direction.flight", { number: index + 1 });
};

const cabinLabel = (booking) => {
  const flight = booking.selectedFlight || {};
  const fromConstant = TRAVEL_CABIN_CLASSES.find(
    (item) => item.value === booking.selectedCabin,
  );
  return (
    (fromConstant ? t(`passengerInformation.cabin.${fromConstant.value}`) : "") ||
    (flight.info?.seat_class
      ? String(flight.info.seat_class).replace(/^\w/, (c) => c.toUpperCase())
      : "")
  );
};

// ============================================================================
// PASSENGER ROWS
// ============================================================================

/**
 * Passenger-type counts, taken from the selected package `fares` breakdown when
 * it is conclusive, otherwise from the stored search passenger counts.
 *
 * @param {Object} booking
 * @returns {{ adults: number, children: number, infants: number, infantsOnLap: number }}
 * @example derivePassengerCounts(booking);
 */
export function derivePassengerCounts(booking) {
  const breakdown = asArray(booking.selectedFlight?.fares?.breakdown);
  const fromPackage = { adults: 0, children: 0, infants: 0, infantsOnLap: 0 };
  breakdown.forEach((line) => {
    const key = PTC_TO_COUNT_KEY[String(line.code || "").toLowerCase()];
    if (key) fromPackage[key] += Math.max(0, Math.round(Number(line.quantity) || 0));
  });
  if (Object.values(fromPackage).some((count) => count > 0)) return fromPackage;

  const counts = booking.passengerCounts || {};
  const fromSearch = {
    adults: Math.max(0, Math.round(Number(counts.adults) || 0)),
    children: Math.max(0, Math.round(Number(counts.children) || 0)),
    infants: Math.max(0, Math.round(Number(counts.infants) || 0)),
    infantsOnLap: Math.max(0, Math.round(Number(counts.infantsOnLap) || 0)),
  };
  if (Object.values(fromSearch).some((count) => count > 0)) return fromSearch;

  return { adults: Math.max(1, asArray(booking.passengers).length), children: 0, infants: 0, infantsOnLap: 0 };
}

/**
 * Builds the passenger cards for the page, preserving any values the traveller
 * already typed (matched by position), while the type/label/badges come from
 * the selected package.
 *
 * @param {Object} booking
 * @returns {Object[]} Passenger rows compatible with the page form + validation.
 * @example createPassengerRows(booking);
 */
export function createPassengerRows(booking) {
  const counts = derivePassengerCounts(booking);
  const existing = asArray(booking.passengers);
  const rows = [];
  COUNT_KEY_ORDER.forEach((key) => {
    for (let i = 0; i < (counts[key] || 0); i += 1) {
      const position = rows.length;
      const saved = existing[position] || {};
      const typeLabel = t(`passengerInformation.type.${key}`);
      const gender = saved.gender || (position === 0 ? "male" : "");
      rows.push({
        ...saved,
        id: saved.id || `passenger-${position + 1}`,
        passengerType: key,
        label: t("passengerInformation.passenger", { number: position + 1 }),
        badges:
          position === 0
            ? [
                { id: "primary", text: t("passengerInformation.primaryContact") },
                { id: key, text: typeLabel },
              ]
            : [{ id: key, text: typeLabel }],
        givenNames: saved.givenNames || "",
        surnames: saved.surnames || "",
        dob: saved.dob || "",
        gender,
        genderLabel: getGenderOptions().find((option) => option.value === gender)?.label || "",
        contact: isObject(saved.contact) ? saved.contact : {},
      });
    }
  });
  // Never drop a traveller (and their typed details) because the package
  // breakdown was missing or smaller than what the search already produced.
  const filledExisting = existing.filter(
    (p) => p && (p.givenNames || p.surnames || p.dob),
  ).length;
  if (rows.length < Math.max(filledExisting, existing.length ? 1 : 0)) {
    return existing;
  }
  if (!rows.length && existing.length) return existing;
  return rows;
}

// ============================================================================
// FARE RULES  →  <osn-fare-rules banner="..." items="..." />
// ============================================================================

const pickGroupForPtc = (groups, ptc = "ADT") => {
  const list = asArray(groups);
  return (
    list.find((group) => String(group.ptc).toUpperCase() === ptc) || list[0] || null
  );
};

/**
 * @param {Object} model - `BaggageAndFareRulesSchema` output.
 * @param {Object} booking
 * @returns {{ banner: { title: string, subtitle: string }, items: Object[] }|null}
 * @example createFareRules(model, booking);
 */
export function createFareRules(model, booking) {
  const group = pickGroupForPtc(model && model.fareRuleGroups);
  if (!group) return null;

  const airlineName =
    booking.selectedFlight?.itinerary?.[0]?.segments?.[0]?.carrier?.name ||
    booking.selectedFlight?.airline?.name ||
    "";
  const cabin = group.cabin || cabinLabel(booking);
  const items = [];

  if (group.changeable) {
    items.push({
      id: "fare-rule-change-allowed",
      kind: "check",
      icon: FARE_RULE_ICONS.check,
      text: group.changeFee
        ? t("passengerInformation.rules.changeFee", { fee: group.changeFee })
        : t("passengerInformation.rules.changeAllowed"),
    });
  } else {
    items.push({
      id: "fare-rule-change-not-allowed",
      kind: "x",
      icon: FARE_RULE_ICONS.x,
      text: t("passengerInformation.rules.changeDenied"),
    });
  }

  if (group.refundable) {
    items.push({
      id: "fare-rule-refundable",
      kind: "check",
      icon: FARE_RULE_ICONS.check,
      text: group.refundFee
        ? t("passengerInformation.rules.refundFee", { fee: group.refundFee })
        : t("passengerInformation.rules.refundable"),
    });
  } else {
    items.push({
      id: "fare-rule-non-refundable",
      kind: "x",
      icon: FARE_RULE_ICONS.x,
      text: t("passengerInformation.rules.nonRefundable"),
    });
  }

  asArray(group.texts).forEach((line, index) => {
    const text = String(line || "").trim();
    if (text) {
      items.push({
        id: `fare-rule-text-${index + 1}`,
        kind: "dash",
        icon: FARE_RULE_ICONS.dash,
        text,
      });
    }
  });

  if (!items.length) return null;
  return {
    banner: {
      title: [airlineName, group.brandName].filter(Boolean).join(" ") || t("passengerInformation.rules.title"),
      subtitle: cabin ? t("passengerInformation.rules.cabin", { cabin }) : "",
    },
    items,
  };
}

// ============================================================================
// BAGGAGE ALLOWANCE  →  <osn-baggage-allowance summary="..." routeList="..." />
// ============================================================================

const pieceSubtitle = (piece) => {
  if (!piece) return t("passengerInformation.baggage.notIncluded");
  if (!piece.included) return t("passengerInformation.baggage.notIncluded");
  const count = Number(piece.quantity) > 0 ? Math.round(piece.quantity) : 1;
  return t(count === 1 ? "passengerInformation.baggage.one" : "passengerInformation.baggage.other", { count });
};

/**
 * @param {Object} model - `BaggageAndFareRulesSchema` output.
 * @param {Object} booking
 * @returns {{ summary: Object[], routeList: Object[] }|null}
 * @example createBaggageAllowance(model, booking);
 */
export function createBaggageAllowance(model, booking) {
  const groups = asArray(model && model.baggageGroups);
  if (!groups.length) return null;

  const itinerary = getItinerary(booking);
  // One direction per leg; pair each leg with the ADT baggage group in order,
  // then by explicit direction key, finally by position.
  const adtGroups = groups.filter(
    (group) => String(group.ptc).toUpperCase() === "ADT",
  );
  const orderedGroups = adtGroups.length ? adtGroups : groups;

  const routeList = itinerary
    .map((leg, index) => {
      const group =
        orderedGroups.find(
          (candidate) => String(candidate.direction) === String(index),
        ) ||
        orderedGroups[index] ||
        orderedGroups[0];
      if (!group) return null;
      const from = leg.origin_airport_code || leg.segments?.[0]?.departure_code || "";
      const to =
        leg.destination_airport_code ||
        leg.segments?.[leg.segments.length - 1]?.arrival_code ||
        "";
      const tag = directionLabel(booking, index, itinerary.length);
      const items = [
        {
          id: `baggage-${index}-personal`,
          kind: "personal",
          icon: BAGGAGE_ICONS.personal,
          title: t("passengerInformation.baggage.personal"),
          subtitle: pieceSubtitle(group.personalItem),
        },
        {
          id: `baggage-${index}-carryon`,
          kind: "carryon",
          icon: BAGGAGE_ICONS.carryon,
          title: t("passengerInformation.baggage.carryon"),
          value: group.carryOn?.weight ? String(group.carryOn.weight) : "",
          subtitle: pieceSubtitle(group.carryOn),
        },
        {
          id: `baggage-${index}-checked`,
          kind: "checked",
          icon: BAGGAGE_ICONS.checked,
          title: t("passengerInformation.baggage.checked"),
          value: group.checked?.weight ? String(group.checked.weight) : "",
          subtitle: pieceSubtitle(group.checked),
        },
      ];
      return {
        id: `baggage-route-${index}`,
        title: from && to ? `${from} → ${to}` : tag,
        tag,
        tagTone: index === 0 ? "departure" : "return",
        items,
      };
    })
    .filter(Boolean);

  if (!routeList.length) return null;

  const first = orderedGroups[0] || {};
  const badgeCount = (piece) =>
    piece && piece.included
      ? String(Number(piece.quantity) > 0 ? Math.round(piece.quantity) : 1)
      : "0";
  const summary = [
    {
      id: "personal",
      label: badgeCount(first.personalItem) === "0" ? "1" : badgeCount(first.personalItem),
      tone: "accent",
      icon: BAGGAGE_ICONS.personal,
    },
    {
      id: "carryon",
      label: badgeCount(first.carryOn),
      tone: first.carryOn?.included ? "accent" : "muted",
      icon: BAGGAGE_ICONS.carryon,
    },
    {
      id: "checked",
      label: badgeCount(first.checked),
      tone: first.checked?.included ? "accent" : "muted",
      icon: BAGGAGE_ICONS.checked,
    },
  ];

  return { summary, routeList };
}

// ============================================================================
// PRICE BREAKDOWN  →  footer total + expandable lines
// ============================================================================

const money = (amount, currency) =>
  `${formatPrice(Number(amount) || 0, { locale: "fr-FR", includeCurrency: false })}${
    currency ? ` ${currency}` : ""
  }`;

/**
 * Footer total and (when expanded) the line items, preferring the tax-breakdown
 * endpoint and falling back to the selected package quote.
 *
 * @param {Object} taxModel - `TaxBreakdownSchema` output (may be null).
 * @param {Object} booking
 * @returns {{ total: string, amount: string, currency: string, lines: Object[], hasBreakdown: boolean }}
 * @example createPriceBreakdown(taxModel, booking);
 */
export function createPriceBreakdown(taxModel, booking) {
  const flight = booking.selectedFlight || {};
  const packageCurrency = flight.info?.currency || "";
  const packageTotal = Number(flight.prices?.total_price);

  const tax = isObject(taxModel) ? taxModel : {};
  const currency = tax.currency || packageCurrency || "USD";
  const totalValue =
    Number(tax.total) > 0
      ? Number(tax.total)
      : Number.isFinite(packageTotal) && packageTotal > 0
        ? packageTotal
        : 0;

  // Prefer the tax-breakdown detail (base fare + individual tax lines); only
  // fall back to the per passenger-type quote lines when the endpoint gave
  // nothing usable. Mixing both would double-count the total.
  const lines = [];
  const taxLines = asArray(tax.lines).filter(
    (line) => line && Number(line.amount) !== 0,
  );
  const hasTaxDetail = Number(tax.baseFare) > 0 || taxLines.length > 0;

  if (hasTaxDetail) {
    if (Number(tax.baseFare) > 0) {
      lines.push({
        id: "price-base-fare",
        label: t("passengerInformation.price.baseFare"),
        amount: money(tax.baseFare, currency),
      });
    }
    taxLines.forEach((line, index) => {
      lines.push({
        id: `price-tax-${line.code || index}`,
        label: line.label && line.label !== "Tax" ? line.label : t("passengerInformation.price.tax"),
        amount: money(line.amount, currency),
      });
    });
    if (!taxLines.length && Number(tax.taxTotal) > 0) {
      lines.push({
        id: "price-taxes",
        label: t("passengerInformation.price.taxes"),
        amount: money(tax.taxTotal, currency),
      });
    }
  } else {
    asArray(flight.fares?.breakdown).forEach((line) => {
      if (!line || !(line.quantity > 0)) return;
      lines.push({
        id: `price-${line.code}`,
        label: `${line.quantity} × ${PTC_TO_COUNT_KEY[line.code] ? t(`passengerInformation.type.${PTC_TO_COUNT_KEY[line.code]}`) : line.label}`,
        amount: money(line.total || line.base + line.tax, currency),
      });
    });
  }

  const amount = totalValue > 0 ? money(totalValue, "").trim() : "0";
  return {
    amount,
    total: totalValue > 0 ? money(totalValue, currency) : "",
    currency,
    lines,
    hasBreakdown: lines.length > 0,
  };
}

