// ============================================================================
// REVIEW HELPERS
// Build localized review data from the booking, without requests or mutation.
// ============================================================================

import { t } from "../i18n/index";
import { reviewPassengers } from "./passengerForm";
import { createFareRules, createBaggageAllowance, createPriceBreakdown } from "./passengerInformation";

/**
 * Identify the search/package pair associated with checkout documents.
 * @param {Object} booking - Booking session.
 * @returns {string} Stable cache key, or an empty string when IDs are missing.
 * @example getCheckoutKey(booking);
 */
export const getCheckoutKey = (booking) => {
  const searchId = booking.searchId || booking.results?.id;
  const packageId = booking.selectedFlight?.id;
  return searchId && packageId ? JSON.stringify([String(searchId), String(packageId)]) : "";
};

/**
 * Rebuild translated checkout props from cached normalized API models.
 * Legacy sessions without models keep their existing component props.
 * @param {Object} booking - Booking session.
 * @returns {Object} Fare rules, baggage and price props.
 * @example createCheckoutView(booking);
 */
export const createCheckoutView = (booking) => {
  const cache = booking.passengerCheckout;
  if (!cache) {
    return {
      fareRules: booking.fareRules || null,
      baggageAllowance: booking.baggageAllowance || null,
      priceBreakdown: booking.priceBreakdown || null,
    };
  }
  const matches = cache.key === getCheckoutKey(booking);
  const rules = matches ? cache.rules : null;
  const tax = matches ? cache.tax : null;
  return {
    fareRules: rules ? createFareRules(rules, booking) : null,
    baggageAllowance: rules ? createBaggageAllowance(rules, booking) : null,
    priceBreakdown: createPriceBreakdown(tax, booking),
  };
};

/**
 * Create the fare/passenger group while retaining groups owned by other steps.
 * @param {Object} booking - Booking with price breakdown and totals.
 * @param {Object[]} passengers - Passenger summary rows.
 * @returns {Object[]} Review price groups.
 * @example createReviewPriceBreakdown(booking, reviewPassengers(booking.passengers));
 */
export const createReviewPriceBreakdown = (booking, passengers) => {
  const price = booking.priceBreakdown || null;
  const currency = price?.currency || booking.totals?.currency || "USD";
  const total = price?.amount || booking.totals?.current || "0";
  const group = price?.lines?.length
    ? {
        id: "fare",
        label: t("review.fareAndTaxes"),
        amount: price.total || `${total} ${currency}`,
        items: price.lines.map(({ id, label, amount }) => ({ id, label, amount })),
      }
    : {
        id: "passengers",
        label: t("review.passengers"),
        amount: `${total} ${currency}`,
        items: passengers.map((p) => ({
          id: `price-${p.id}`, label: p.name, amount: t("review.included"),
        })),
      };
  const previous = Array.isArray(booking.reviewPriceBreakdown) ? booking.reviewPriceBreakdown : [];
  let replaced = false;
  const groups = previous.flatMap((item) => {
    if (item.id !== "fare" && item.id !== "passengers") return [item];
    if (replaced) return [];
    replaced = true;
    return [group];
  });
  return replaced ? groups : [group, ...groups];
};

/**
 * Assemble Review page props from the booking and seat-review state.
 * @param {Object} booking - Booking session.
 * @param {Object} [reviewState={}] - Seat state from the booking EventBus.
 * @returns {Object} Fields for Page.setData().
 * @example createReviewView(booking, reviewState);
 */
export const createReviewView = (booking, reviewState = {}) => {
  const checkout = createCheckoutView(booking);
  const passengers = booking.passengers?.length
    ? reviewPassengers(booking.passengers) : booking.reviewPassengers || [];
  return {
    reviewTripTitle: booking.trip?.title || t("passengerInformation.yourTrip"),
    reviewTripSubtitle: t("review.subtitle"),
    reviewTripSegments: booking.tripSummarySegments || [],
    reviewPassengers: passengers,
    reviewPriceBreakdown: createReviewPriceBreakdown({ ...booking, ...checkout }, passengers),
    reviewTotalAmount: checkout.priceBreakdown?.amount || booking.totals?.current || "0",
    reviewCurrency: checkout.priceBreakdown?.currency || booking.totals?.currency || reviewState.currency || "USD",
    reviewSeatRequests: reviewState.seatRequests || [],
    reviewSeatTotal: reviewState.seatTotal || "0.00",
    reviewFareRulesBanner: checkout.fareRules?.banner || null,
    reviewFareRulesItems: checkout.fareRules?.items || null,
    reviewBaggageSummary: checkout.baggageAllowance?.summary || null,
