import { TRAVEL_CABIN_CLASSES } from "../constants/index";
import { getLocale, t } from "../i18n/index.js";
import { sculpt } from "../json-sculpt/sculpt.js";

/** Converts a stored amount to an integer usable for calculations. */
export const valueOf = (value) =>
  Number.parseInt(String(value || "0").replace(/\D/g, ""), 10) || 0;

/** Formats an amount using the French number format required by the upgrade. */
export const price = (value) =>
  new Intl.NumberFormat("fr-FR").format(Math.round(value || 0));

/** Prepares fare families for the upgrade-flight cards. */
export const createUpgradeFares = (families = []) =>
  families.map((family, index) => ({
    ...family,
    id: family.id || `fare-family-${index}`,
    name: family.name || `Fare family ${index + 1}`,
    cabin: family.cabin || "Economy",
    price: family.price || `+ ${price(family.surcharge)} USD`,
    surcharge: Number(family.surcharge) || 0,
  }));

/** Transforms an airport entry using the provided JSON Sculpt schema. */
export const mapAirportEntity = (item, airportSchema) => {
  const mapAirport = (airport) =>
    sculpt.data({ data: airport, to: airportSchema });
  return Array.isArray(item?.Airports)
    ? item.Airports.map(mapAirport)
    : [mapAirport(item)];
};

/** Normalizes the different fare-family response shapes. */
export const normalizeFareFamilies = (data) => {
  const families =
    [
      data?.fare_families,
      data?.fare_family_options,
      data?.families,
      data?.options,
      data,
    ].find((value) => Array.isArray(value)) || [];

  return families.map((family, index) => ({
    id:
      family.id ||
      family.code ||
      family.fare_family_id ||
      `fare-family-${index}`,
    ff: family.ff ?? family.index ?? index,
    name: family.name || family.title || family.fare_family_name || "",
    cabin: family.cabin || family.cabin_class || "",
    price: family.price || family.amount || family.total || "",
    surcharge:
      family.surcharge ??
      family.price?.difference ??
      family.price_difference ??
      0,
    recommended: Boolean(family.recommended || family.is_recommended),
    features: family.features || family.benefits || [],
  }));
};

/** Reduces an upgrade response to the package and identifier needed by the flow. */
export const normalizeUpgradeResponse = (data) => ({
  upgraded_package: data?.upgraded_package
