    .trim()
    .toUpperCase();

/** Normalizes the availability response consumed by the payment page. */
export const normalizeAvailability = (data) => ({
  success: data?.success !== false && data?.result !== "error",
  error_message: data?.error_message || data?.reason || "",
});

/** Extracts the reference and email consumed by the confirmed page. */
export const normalizeBookingResponse = (data) => ({
  booking_id:
    data?.booking_id ||
    data?.booking_reference ||
    data?.booking_details?.booking_id ||
    "",
  booking_reference:
