});

/**
 * Determines whether the primary search action should be disabled for the current
 * itinerary form and selected tab.
 *
 * The validation rules differ by trip type: multi-city requires every leg to be
 * fully populated and in the future, one-way requires origin/destination and a
 * valid departure date, and round-trip requires a valid date range.
 */
export const computeSearchButtonDisabled = (activeTab, form) => {
  if (activeTab === "multiCity") {
    return !form.multiCityLegs.every(
      (leg) => leg.from && leg.to && leg.date && leg.date >= getTodayIsoDate(),
    );
  }

  if (activeTab === "oneWay") {
    return !(
      form.from &&
      form.to &&
      form.departDate &&
      form.departDate >= getTodayIsoDate()
    );
  }

  const isValidReturnDate =
    !!form.departDate &&
    !!form.returnDate &&
    form.departDate >= getTodayIsoDate() &&
    form.returnDate > form.departDate;

  return !(form.from && form.to && isValidReturnDate);
};

/**
 * Normalizes a location value into a stable shape containing both a display name
 * and an IATA code. It accepts either an object payload or a string such as
 * "Paris (CDG)".
 */
export const parseLocation = (value) => {
  if (value && typeof value === "object") {
    return {
      name: value.name || value.label || value.value || "",
      code: value.code || "",
    };
  }

  const raw = String(value || "").trim();
  const match = raw.match(/^(.+?)\s*\(([^)]+)\)$/);
  return {
    name: match ? match[1].trim() : raw,
    code: match ? match[2].trim() : "",
  };
};

/**
 * Converts a list of multi-city legs into a normalized structure so downstream
 * code can safely consume location data regardless of the original input format.
 */
export const normalizeMultiCityLegs = (legs = []) => {
  return legs.map((leg) => ({
    ...leg,
    from: parseLocation(leg.from),
    to: parseLocation(leg.to),
  }));
};

/**
 * Builds a deterministic cache key for the flight result query. This ensures the
 * same search parameters produce a consistent identity and avoids duplicated
 * fetches for equivalent requests.
 */
export const createResultsCacheKey = (
  payload,
  passengerCounts,
  selectedCabin,
) => {
  return JSON.stringify({
    activeTab: payload.activeTab || "roundTrip",
    from: payload.from || "",
    to: payload.to || "",
    departDate: payload.departDate || "",
    returnDate: payload.returnDate || "",
    multiCityLegs: payload.multiCityLegs || [],
    nonstopOnly: Boolean(payload.nonstopOnly),
    removeLowCost: Boolean(payload.removeLowCost),
    passengerCounts,
    selectedCabin,
    searchId: payload.bookingReference || payload.searchId || "",
  });
};

/**
 * Returns a human-readable label for a location, including the code when one is
 * available so the UI can display compact but informative location names.
 */
export const getLocationLabel = (location) => {
  const parsed = parseLocation(location);
  return parsed.code ? `${parsed.name} (${parsed.code})` : parsed.name;
};

/**
 * Converts multi-city leg data into a display-safe representation where each
 * location is already formatted as a label string instead of a raw object.
 */
export const normalizeMultiCityDisplayLegs = (legs = []) => {
  return legs.map((leg) => ({
    ...leg,
    from: getLocationLabel(leg.from),
    to: getLocationLabel(leg.to),
  }));
};

/**
 * Formats the date range used in the recent-search card. The display depends on
 * the selected trip type so each tab shows the most relevant booking period.
 */
export const getRecentSearchDates = (searchForm, activeTab) => {
  if (activeTab === "roundTrip") {
    return `${formatFrenchDate(searchForm.departDate)} - ${formatFrenchDate(searchForm.returnDate)}`;
  }

  if (activeTab === "multiCity") {
    return searchForm.multiCityLegs
      .map((leg) => formatFrenchDate(leg.date))
      .filter(Boolean)
      .join(" - ");
  }

  return formatFrenchDate(searchForm.departDate);
};

/**
 * Checks whether at least one fare package represents a non-stop itinerary.
 * This is used to decide whether a direct-fare badge or filter should be shown.
 */
export const hasDirectFare = (fares) => {
  const packages = Array.isArray(fares?.packages)
    ? fares.packages
    : Object.values(fares?.packages || {});

  return packages.some((fare) => {
    const itinerary = Array.isArray(fare?.itinerary) ? fare.itinerary : [];
    return (
      itinerary.length > 0 &&
      itinerary.every((leg) => Number(leg?.num_stops) === 0)
    );
  });
};

/**
 * Persists the latest search in local storage and returns the updated recent-search
 * list. The most recent query is always kept at the front so the UI can render a
 * compact history with predictable ordering.
 */
export const saveRecentSearch = (searchForm, activeTab) => {
  const recentSearch = {
    id: Date.now(),
    from: getLocationLabel(searchForm.from),
    to: getLocationLabel(searchForm.to),
    dates: getRecentSearchDates(searchForm, activeTab),
    type:
      activeTab === "multiCity"
        ? "Multi-city"
        : activeTab === "oneWay"
          ? "One-way"
          : "Round trip",
    image: "/assets/images/cover_search.png",
    activeTab,
    departDate: searchForm.departDate,
    departDateDisplay: searchForm.departDateDisplay,
    returnDate: searchForm.returnDate,
    returnDateDisplay: searchForm.returnDateDisplay,
    multiCityLegs: searchForm.multiCityLegs,
    nonstopOnly: searchForm.nonstopOnly,
    removeLowCost: searchForm.removeLowCost,
  };
  const stored = wx.getStorageSync(RECENT_SEARCHES_STORAGE_KEY);
  const previous = Array.isArray(stored) ? stored : [];
  const next = [
    recentSearch,
    ...previous.filter((item) => item.id !== recentSearch.id),
  ].slice(0, 6);
  wx.setStorageSync(RECENT_SEARCHES_STORAGE_KEY, next);
  return next;
};

// ============================================================================
// FLIGHT DETAILS — utilitaires internes et fonctions exportées pour les pages
// ============================================================================

/**
 * Traduit les jours et mois du libellé de date anglais, même depuis le cache.
 *
 * @param {string} value - Date déjà formatée par le mapper.
 * @returns {string} Date traduite sans recalcul du jour ni du fuseau horaire.
 */
function getDateLabel(value) {
  return String(value || "").replace(
    /\b(Mon|Tue|Wed|Thu|Fri|Sat|Sun|Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Sept|Oct|Nov|Dec)\b/g,
    (token) => t(`flightDetails.date.${token === "Sep" ? "Sept" : token}`),
  );
}

/**
 * Adapte la notation AM/PM au format 24 heures pour le français.
 *
 * @param {string} value - Heure affichée fournie par le mapper.
 * @returns {string} Heure localisée, sans changement du fuseau ou de l'instant du vol.
 */
function getTimeLabel(value) {
  const label = String(value || "");
  if (getLocale() !== "fr") return label;
  const match = label.match(/^(\d{1,2}):([0-5]\d)(:[0-5]\d)?\s*([AP]M)$/i);
  if (!match || Number(match[1]) < 1 || Number(match[1]) > 12) return label;
  const hours =
    (Number(match[1]) % 12) + (match[4].toUpperCase() === "PM" ? 12 : 0);
  return `${String(hours).padStart(2, "0")}:${match[2]}${match[3] || ""}`;
}

/**
 * Traduit l'abréviation des minutes d'une durée déjà mise en forme.
 *
 * @param {string} value - Durée formatée, par exemple « 2h 30m ».
 * @returns {string} Durée avec les unités de la langue active.
 */
function getDurationLabel(value) {
  return value.replace(/(\d+)\s*m\b/g, (_, count) =>
    t("flightDetails.duration.minutes", { count }),
  );
}

/**
 * Retrouve un nom de ville uniquement lorsque son code correspond à l'aéroport demandé.
 *
 * @param {Object|string} value - Lieu de recherche sous forme d'objet ou de texte.
 * @param {string} code - Code de l'aéroport à identifier.
 * @returns {string} Nom correspondant, ou chaîne vide sans correspondance.
 */
function getLocationName(value, code) {
  if (value && typeof value === "object") {
    return value.code === code ? value.name || value.label || "" : "";
  }
  const match = String(value || "").match(/^(.+?)\s*\(([^)]+)\)$/);
  return match && match[2] === code ? match[1].trim() : "";
}

/**
 * Prépare les données d'affichage du départ ou de l'arrivée d'un segment.
 *
 * @param {Object} segment - Segment normalisé provenant de l'API.
 * @param {string} side - « departure » ou « arrival ».
 * @param {string} code - Code de l'aéroport concerné.
 * @param {Object} booking - Session contenant les lieux de la recherche.
 * @returns {Object} Code, ville, aéroport, date et heure, sans inventer les données absentes.
 */
function getEndpoint(segment, side, code, booking) {
  const locations = [
    booking.from,
    booking.to,
    ...(booking.multiCityLegs || []).flatMap((leg) => [leg.from, leg.to]),
  ];
  const schedule = segment[`${side}_time`] || {};
  return {
    code,
    city:
      locations
        .map((location) => getLocationName(location, code))
        .find(Boolean) || "",
    airport: segment[`${side}_airport_name`] || "",
    date: getDateLabel(schedule.date),
    time: getTimeLabel(schedule.time),
  };
}

/**
 * Formate une durée de vol et traduit son unité de minutes.
 *
 * @param {number|string} value - Durée numérique en secondes ou texte déjà formaté.
 * @returns {string} Durée localisée, ou chaîne vide si elle n'est pas exploitable.
 */
function getDuration(value) {
  if (typeof value === "string" && /[hm]/.test(value))
    return getDurationLabel(formatDuration(value));
  const seconds = Number(value);
  return Number.isFinite(seconds) && seconds > 0
    ? getDurationLabel(formatDuration("", Math.round(seconds / 60)))
    : "";
}

/**
 * Valide un horaire complet avec fuseau explicite pour calculer une correspondance.
 *
 * @param {string} value - Horaire original conservé dans departure_time.raw ou arrival_time.raw.
 * @returns {number|null} Instant en millisecondes, ou null si le format/date/fuseau est inexploitable.
 */
function getTimestamp(value) {
  if (typeof value !== "string") return null;
  const match = value.match(
    /^(\d{4}-\d{2}-\d{2})[T ](?:[01]\d|2[0-3]):[0-5]\d(?::[0-5]\d(?:\.\d{1,3})?)?(?:Z|[+-](?:0\d|1[0-4]):[0-5]\d)$/i,
  );
  if (!match) return null;
  const date = new Date(`${match[1]}T00:00:00Z`);
  if (
    !Number.isFinite(date.getTime()) ||
    date.toISOString().slice(0, 10) !== match[1]
  )
    return null;
  const timestamp = Date.parse(value.replace(" ", "T"));
  return Number.isFinite(timestamp) ? timestamp : null;
}

/**
 * Construit le libellé d'escale entre deux segments du même trajet.
 *
 * @param {Object} segment - Segment qui arrive à l'escale.
 * @param {Object|undefined} next - Segment suivant, absent après la dernière arrivée.
 * @param {string} arrivalCode - Code de l'aéroport d'arrivée du segment actuel.
 * @returns {string} Correspondance ou changement d'aéroport, avec durée si calculable ; sinon chaîne vide en fin de trajet.
 */
function getConnectionLabel(segment, next, arrivalCode) {
  if (!next) return "";
  const departureCode = next.departure_code || "";
  const airport = arrivalCode || departureCode;
  const connection =
    arrivalCode && departureCode && arrivalCode !== departureCode
      ? t("flightDetails.airportChange", {
          from: arrivalCode,
          to: departureCode,
        })
      : airport
        ? t("flightDetails.connection", { airport })
        : t("flightDetails.connectionUnknownAirport");
  const arrival = getTimestamp(segment.arrival_time?.raw);
  const departure = getTimestamp(next.departure_time?.raw);
  // A missing/ambiguous timestamp must not become an invented waiting time.
  if (arrival === null || departure === null || departure <= arrival)
    return connection;
  const minutes = Math.round((departure - arrival) / 60000);
  return minutes > 0
    ? t("flightDetails.connectionWithDuration", {
        connection,
        duration: getDurationLabel(formatDuration("", minutes)),
      })
    : connection;
}

/**
 * Adapte selectedFlight aux composants de Flight details, sans requête API ni sauvegarde.
 *
 * @param {Object} booking - Session contenant le vol sélectionné et les lieux de recherche.
 * @returns {Object|null} Trajets, segments, disponibilité et prix, ou null sans itinéraire exploitable.
 */
export function createFlightDetails(booking) {
  const flight = booking.selectedFlight || {};
  const itinerary = Array.isArray(flight.itinerary) ? flight.itinerary : [];
  const tripType = String(
    flight.info?.trip_type || booking.activeTab || "",
  ).toLowerCase();
  const isRoundTrip = tripType === "roundtrip";
  const legs = itinerary
    .map((leg, legIndex) => {
      const sourceSegments = Array.isArray(leg?.segments)
        ? leg.segments.filter(Boolean)
        : [];
      const segments = sourceSegments.map((segment, index) => {
        const fromCode =
          segment.departure_code ||
          (index === 0 ? leg.origin_airport_code : "") ||
          "";
        const toCode =
          segment.arrival_code ||
          (index === sourceSegments.length - 1
            ? leg.destination_airport_code
            : "") ||
          "";
        const airline =
          segment.carrier || segment.airline || flight.airline || {};
        const name =
          typeof airline === "string"
            ? airline
            : airline.name || airline.code || "";
        return {
          id: `leg-${legIndex + 1}-segment-${index + 1}`,
          departure: getEndpoint(segment, "departure", fromCode, booking),
          arrival: getEndpoint(segment, "arrival", toCode, booking),
          carrier: {
            name: name || t("flightDetails.notProvided"),
            logo: airline.logo || "",
            fallbackLabel:
              airline.code || name.slice(0, 3).toUpperCase() || "—",
            theme: airline.theme || "",
            framed: airline.framed !== false,
          },
          // Older cached results may not contain the segment duration.
          // Only a direct flight can safely fall back to the total leg duration.
          duration: getDuration(
            segment.duration ??
              (sourceSegments.length === 1 ? leg.duration : null),
          ),
          stopAfter: getConnectionLabel(
            segment,
            sourceSegments[index + 1],
            toCode,
          ),
        };
      });
      if (!segments.length) return null;
      const first = segments[0];
      const last = segments[segments.length - 1];
      const destination = last.arrival.city || last.arrival.code;
      const count = leg.num_stops;
      const stops =
        count !== null &&
        count !== undefined &&
        count !== "" &&
        Number.isFinite(Number(count))
          ? Math.max(segments.length - 1, Math.floor(Number(count)))
          : segments.length - 1;
      return {
        id: isRoundTrip
          ? legIndex === 0
            ? "outbound"
            : "return"
          : `leg-${legIndex + 1}`,
        title: destination
          ? t("flightDetails.flightTo", { destination })
          : t("flightDetails.title"),
        direction: isRoundTrip
          ? t(
              legIndex === 0
                ? "flightDetails.direction.departure"
                : "flightDetails.direction.return",
            )
          : itinerary.length === 1
            ? t("flightDetails.direction.departure")
            : t("flightDetails.direction.flight", { number: legIndex + 1 }),
        dateLabel: first.departure.date,
        travelDate: first.departure.date,
        duration: getDuration(leg.duration),
        stopsLabel:
          stops === 0
            ? t("flightDetails.stops.direct")
            : t(
                stops === 1
                  ? "flightDetails.stops.one"
                  : "flightDetails.stops.other",
                { count: stops },
              ),
        segments,
        summary: {
          city: destination,
          dateTimeLabel: [last.arrival.date, last.arrival.time]
            .filter(Boolean)
            .join(", "),
        },
        // A connection is only between segments of this leg, never between trip legs.
        stayLabel: "",
      };
    })
    .filter(Boolean);
  if (!legs.length) return null;

  const quote = flight.prices?.total_price;
  const hasQuote =
    quote !== null &&
    quote !== undefined &&
    quote !== "" &&
    Number.isFinite(Number(quote));
  const seats = flight.info?.seats_available;
  return {
    legs,
    scarcityCount:
      seats !== null &&
      seats !== undefined &&
      seats !== "" &&
      Number.isFinite(Number(seats))
        ? Math.max(0, Number(seats))
        : null,
    total: {
      amount: hasQuote
        ? formatPrice(Number(quote), {
            locale: "fr-FR",
            includeCurrency: false,
          })
        : t("flightDetails.notAvailable"),
      currency: flight.info?.currency || "",
      caption: t("flightDetails.total.caption"),
    },
    hasQuote,
  };
}

/**
 * Construit le résumé de chaque trajet destiné aux étapes suivantes de la réservation.
 *
 * @param {Object} details - Modèle non nul retourné par createFlightDetails.
 * @returns {Object[]} Résumés du premier départ à la dernière arrivée de chaque trajet.
 */
export function createTripSummary(details) {
  return details.legs.map((leg) => {
    const first = leg.segments[0];
    const last = leg.segments[leg.segments.length - 1];
    return {
      id: leg.id,
      dateLabel: leg.dateLabel,
      direction: leg.direction,
      airlineLogo: first.carrier.logo,
      fromCode: first.departure.code,
      fromTime: first.departure.time,
      toCode: last.arrival.code,
      toTime: last.arrival.time,
      stopLabel: leg.stopsLabel,
      duration: leg.duration,
    };
  });
}

// ============================================================================
// TRIP DETAILS — préparation des données et du récapitulatif PDF
// ============================================================================

/**
 * Prépare les résumés des trajets à partir des segments API avec les mêmes formats que Flight details.
 * @param {Object} booking - Session contenant le vol sélectionné et la classe de cabine.
 * @returns {Object[]} Trajets affichables ; aucun trajet de démonstration ajouté.
 */
function getTripFlights(booking) {
  const flight = booking.selectedFlight || {};
  const itinerary = Array.isArray(flight.itinerary) ? flight.itinerary : [];
  const isRoundTrip =
    String(flight.info?.trip_type || booking.activeTab || "").toLowerCase() ===
    "roundtrip";
  const cabin = TRAVEL_CABIN_CLASSES.some(
    (item) => item.value === booking.selectedCabin,
  )
    ? t(`tripDetails.cabin.${booking.selectedCabin}`)
    : "";
  return itinerary
    .map((leg, index) => {
      const segments = Array.isArray(leg?.segments)
        ? leg.segments.filter(Boolean)
        : [];
      if (!segments.length) return null;
      const first = segments[0];
      const last = segments[segments.length - 1];
      const count = leg.num_stops;
      const stops =
        count !== null &&
        count !== undefined &&
        count !== "" &&
        Number.isFinite(Number(count))
          ? Math.max(segments.length - 1, Math.floor(Number(count)))
          : segments.length - 1;
      return {
        id: isRoundTrip
          ? index === 0
            ? "outbound"
            : "return"
          : `leg-${index + 1}`,
        date: getDateLabel(first.departure_time?.date),
        direction: isRoundTrip
          ? t(
              index === 0
                ? "flightDetails.direction.departure"
                : "flightDetails.direction.return",
            )
          : itinerary.length === 1
            ? t("flightDetails.direction.departure")
            : t("flightDetails.direction.flight", { number: index + 1 }),
        cabin,
        logo: first.carrier?.logo || flight.airline?.logo || "",
        from: leg.origin_airport_code || first.departure_code || "",
        departureTime: getTimeLabel(first.departure_time?.time),
        to: leg.destination_airport_code || last.arrival_code || "",
        arrivalTime: getTimeLabel(last.arrival_time?.time),
        type:
          stops === 0
            ? t("flightDetails.stops.direct")
            : t(
                stops === 1
                  ? "flightDetails.stops.one"
                  : "flightDetails.stops.other",
                { count: stops },
              ),
        duration: getDuration(leg.duration),
      };
    })
    .filter(Boolean);
}

/**
 * Retrouve le nom de la destination parmi les lieux de la recherche.
 * @param {Object} booking - Session contenant les destinations.
 * @param {Object[]} flights - Résumés des trajets du voyage.
 * @returns {string} Nom de destination, code aéroport ou chaîne vide.
 */
function getTripDestinationName(booking, flights) {
  const destination =
    flights[flights.length - 1]?.id === "return"
      ? flights[0]?.to
      : flights[flights.length - 1]?.to;
  const locations = [
    booking.to,
    ...(booking.multiCityLegs || []).map((leg) => leg.to),
  ];
  for (const location of locations) {
    if (
      location &&
      typeof location === "object" &&
      location.code === destination
    ) {
      return location.name || location.label || destination;
    }
    const match = String(location || "").match(/^(.+?)\s*\(([^)]+)\)$/);
    if (match && match[2] === destination) return match[1].trim();
  }
  return destination || "";
}

/**
 * Prépare le récapitulatif du devis API sans utiliser les montants de démonstration.
 * @param {Object} booking - Session contenant le prix du vol et les effectifs.
 * @param {Object[]} passengers - Passagers utilisés si les effectifs manquent.
 * @returns {Object} Prix, devise, libellés et disponibilité du devis ; aucune confirmation de paiement.
 */
function getTripPriceSummary(booking, passengers) {
  const flight = booking.selectedFlight || {};
  const quote = flight.prices?.total_price;
  const currency = flight.info?.currency || "";
  const hasQuote =
    quote !== null &&
    quote !== undefined &&
    quote !== "" &&
    Number.isFinite(Number(quote));
  const amount = hasQuote
    ? formatPrice(Number(quote), { locale: "fr-FR", includeCurrency: false })
    : "";
  const total = amount
    ? [amount, currency].filter(Boolean).join(" ")
    : t("tripDetails.notAvailable");
  const counts = booking.passengerCounts || {};
  const types = ["adults", "children", "infants", "infantsOnLap"];
  const labels = types
    .filter((key) => Number(counts[key]) > 0)
    .map((key) => `${counts[key]} × ${t(`tripDetails.passengerType.${key}`)}`);
  const passengerLabel =
    labels.join(", ") ||
    (passengers.length
      ? t(
          passengers.length === 1
            ? "tripDetails.passengers.one"
            : "tripDetails.passengers.other",
          { count: passengers.length },
        )
      : "");

  // The search API total already includes all passengers and taxes.
  // billing/review totals currently contain demo amounts, so do not reuse them.
  return {
    hasQuote,
    passengersTotal: total,
    passengers:
      hasQuote && passengerLabel
        ? [{ label: passengerLabel, value: total }]
        : [],
    addonsTotal: t("tripDetails.notAvailable"),
    addonLines: [],
    taxesTotal: t(
      hasQuote ? "tripDetails.included" : "tripDetails.notAvailable",
    ),
    taxes: [],
    finalTotal: total,
    note: [
      currency ? t("tripDetails.price.currencyNote", { currency }) : "",
      t("tripDetails.price.quoteNote"),
    ]
      .filter(Boolean)
      .join("\n"),
  };
}

/**
 * Traduit le numéro d'un passager généré par l'application sans remplacer un libellé personnalisé.
 * @param {string} label - Libellé conservé dans la session.
 * @param {number} index - Position du passager, à partir de zéro.
 * @returns {string} Libellé localisé ou libellé personnalisé inchangé.
 */
function getTripTravellerLabel(label, index) {
  const match = String(label || "").match(/^(?:Passenger|Passager) (\d+)$/i);
  return !label || match
    ? t("tripDetails.traveller.number", {
        number: match ? match[1] : index + 1,
      })
    : label;
}

/**
 * Traduit les valeurs connues du genre tout en conservant les autres valeurs reçues.
 * @param {Object} passenger - Données du passager.
 * @returns {string} Genre localisé, libellé fourni ou chaîne vide.
 */
function getTripTravellerGender(passenger) {
  const gender = String(
    passenger.gender || passenger.genderLabel || "",
  ).toLowerCase();
  return ["male", "female"].includes(gender)
    ? t(`tripDetails.gender.${gender}`)
    : passenger.genderLabel || passenger.gender || "";
}

/**
 * Adapte la session aux composants Trip details sans requête API ni sauvegarde.
 * @param {Object} booking - Session de réservation et éventuelle réponse serveur.
 * @returns {Object} Voyage, statut, références, passagers, billets, contact et récapitulatif.
 */
export function createTripDetails(booking) {
  const flights = getTripFlights(booking);
  const destination = getTripDestinationName(booking, flights);
  const passengers =
    Array.isArray(booking.passengers) && booking.passengers.length
      ? booking.passengers.filter(Boolean)
      : Array.isArray(booking.reviewPassengers)
        ? booking.reviewPassengers.filter(Boolean)
        : [];
  const contact = {
    ...(booking.contact || {}),
    ...(passengers[0]?.contact || {}),
  };
  const response = booking.bookingResponse || {};
  const reference =
    !response.error && response.success !== false
      ? response.booking_id || ""
      : "";
  const status = String(booking.bookingStatus || "pending").toLowerCase();
  const knownStatus = [
    "confirmed",
    "ticketed",
    "cancelled",
    "pending",
  ].includes(status)
    ? status
    : "pending";
  const travellers = passengers.map((passenger, index) => ({
    id: passenger.id || `traveller-${index + 1}`,
    tag: getTripTravellerLabel(passenger.label, index),
    name:
      [passenger.givenNames, passenger.surnames].filter(Boolean).join(" ") ||
      passenger.name ||
      "",
    birthDate: getDateLabel(
      formatShortDate(passenger.dob || passenger.birthDate || ""),
    ),
    gender: getTripTravellerGender(passenger),
  }));
  return {
    title: destination
      ? t("tripDetails.tripTo", { destination })
      : t("tripDetails.yourTrip"),
    statusLabel: t(`tripDetails.status.${knownStatus}`),
    isConfirmed: status === "confirmed" || status === "ticketed",
    // A local AFR-* search reference and the simulated payment are not a PNR.
    bookingReference: String(reference),
    confirmation: booking.airlineConfirmation || "",
    flights,
    actions: (
      booking.tripActions || [
        {
          id: "rules",
          icon: "info-square",
          external: false,
        },
      ]
    )
      .filter((action) => action && action.id === "rules")
      .map((action) => ({ ...action, label: t("tripDetails.action.rules") })),
    travellers,
    tickets: (booking.tickets || [])
      .filter((ticket) => ticket?.number)
      .map((ticket, index) => ({
        id: ticket.id || `ticket-${index + 1}`,
        traveller:
          ticket.traveller ||
          travellers.find((traveller) => traveller.id === ticket.passengerId)
            ?.name ||
          "",
        number: String(ticket.number),
      })),
    // Non-empty values avoid the unchanged component's demonstration fallbacks.
    contact: {
      phone: contact.phone || t("tripDetails.notProvided"),
      email: contact.email || t("tripDetails.notProvided"),
    },
    price: getTripPriceSummary(booking, passengers),
  };
}

/**
 * Convertit le texte en ASCII pour conserver les offsets du générateur PDF existant.
 * @param {*} value - Texte à écrire dans le PDF.
 * @returns {string} Texte compatible avec la police Courier standard ; accents translittérés.
 */
const pdfText = (value) =>
  String(value ?? "")
    .normalize("NFD")
    .replace(/[\u00a0\u202f]/g, " ")
    .replace(/×/g, "x")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/[^\x20-\x7E]/g, "");

/**
 * Construit les lignes traduites du PDF à partir du récapitulatif Billing affiché.
 * @param {Object} payload - Objet contenant trip et ses informations de facturation.
 * @returns {string[]} Lignes à transmettre au générateur PDF.
 */
export const invoiceLines = (payload) => {
  const price = payload.trip?.price || {};
  const bookingReference =
    payload.bookingReference ||
    payload.trip?.bookingReference ||
    payload.trip?.confirmation ||
    "-";
  // Regroupe un titre, son total et les lignes de détail d’une section Billing.
  const section = (title, total, items = []) => [
    `${title}: ${total || "-"}`,
    ...items.map((item) => `  ${item.label || ""}: ${item.value || "-"}`),
    "",
  ];

  return [
    t("tripDetails.invoice.heading"),
    t("tripDetails.price.title"),
    ...(bookingReference !== "-"
      ? [t("tripDetails.invoice.reference", { reference: bookingReference })]
      : []),
    "",
    ...section(
      t("tripDetails.price.passengers"),
      price.passengersTotal,
      price.passengers,
    ),
    ...section(
      t("tripDetails.price.addons"),
      price.addonsTotal,
      price.addonLines,
    ),
    ...section(t("tripDetails.price.taxes"), price.taxesTotal, price.taxes),
    `${t("tripDetails.price.total")}: ${price.finalTotal || "-"}`,
    "",
    ...String(price.note || "").split("\n"),
  ];
};

/**
 * Génère le document PDF paginé en mémoire, sans accès au stockage ni ouverture native.
 * @param {string[]} lines - Lignes du récapitulatif Billing.
 * @returns {string} Contenu PDF à enregistrer puis ouvrir depuis la page.
 */
export const createInvoicePdf = (lines) => {
  // Standard Courier has a fixed width: 76 characters at 10.5pt fit on A4.
  // Keep the file ASCII so PDF byte offsets also match JavaScript string lengths.
  const rows = lines.flatMap((line) => {
    let text = pdfText(line);
    const wrapped = [];
    while (text.length > 76) {
      const space = text.lastIndexOf(" ", 76);
      const end = space > 0 ? space : 76;
      wrapped.push(text.slice(0, end));
      text = text.slice(end).trimStart();
    }
    return [...wrapped, text];
  });
  const pages = [];
  for (let index = 0; index < rows.length; index += 32) {
    pages.push(rows.slice(index, index + 32));
  }
  const objects = [
    "<< /Type /Catalog /Pages 2 0 R >>",
    `<< /Type /Pages /Kids [${pages.map((_, index) => `${4 + index * 2} 0 R`).join(" ")}] /Count ${pages.length} >>`,
    "<< /Type /Font /Subtype /Type1 /BaseFont /Courier >>",
  ];
  pages.forEach((page, pageIndex) => {
    const commands = page.map((line, index) => {
      const text = line.replace(/([\\()])/g, "\\$1");
      const size = pageIndex === 0 && index === 0 ? 18 : 10.5;
      return `BT /F1 ${size} Tf 50 ${790 - index * 22} Td (${text}) Tj ET`;
    });
    const pageLabel = pdfText(
      t("tripDetails.invoice.page", {
        page: pageIndex + 1,
        total: pages.length,
      }),
    );
    commands.push(`BT /F1 9 Tf 50 40 Td (${pageLabel}) Tj ET`);
    const content = commands.join("\n");
    objects.push(
      `<< /Type /Page /Parent 2 0 R /MediaBox [0 0 595 842] /Resources << /Font << /F1 3 0 R >> >> /Contents ${5 + pageIndex * 2} 0 R >>`,
      `<< /Length ${content.length} >>\nstream\n${content}\nendstream`,
    );
  });
  let pdf = "%PDF-1.4\n";
  const offsets = [0];
  objects.forEach((object, index) => {
    offsets.push(pdf.length);
    pdf += `${index + 1} 0 obj\n${object}\nendobj\n`;
  });
  const xref = pdf.length;
  pdf += `xref\n0 ${objects.length + 1}\n0000000000 65535 f \n`;
  offsets.slice(1).forEach((offset) => {
    pdf += `${String(offset).padStart(10, "0")} 00000 n \n`;
  });
  return `${pdf}trailer\n<< /Size ${objects.length + 1} /Root 1 0 R >>\nstartxref\n${xref}\n%%EOF`;
};

