import { formatShortDate } from "../formatters/index";
import { t } from "../i18n/index";

/**
 * Localized options with stable gender values.
 * @returns {Object[]} Form/view data.
 * @example getGenderOptions();
 */
export const getGenderOptions = () => [
  { label: t("passengerInformation.male"), value: "male" },
