  { code: "ML", label: t("passengerInformation.country.ML") },
  { code: "SN", label: t("passengerInformation.country.SN") },
];
/**
 * Check a validation result.
 * @param {Object} [errors={}] - Field errors.
 * @returns {boolean} Form/view data.
 * @example hasErrors({ email: 'Required' });
 */
export const hasErrors = (errors = {}) =>
  Object.keys(errors).some((field) => Boolean(errors[field]));
/**
 * Merge legacy contact with the primary traveller contact.
 * @param {Object[]} [passengers=[]] - Stored travellers.
 * @param {Object} [legacyContact={}] - Legacy root contact.
 * @returns {Object} Form/view data.
 * @example getPrimaryPassengerContact(passengers, booking.contact);
 */
export const getPrimaryPassengerContact = (passengers = [], legacyContact = {}) => ({
  ...(legacyContact && typeof legacyContact === "object" ? legacyContact : {}),
  ...(passengers[0]?.contact || {}),
});
/**
 * Attach contact to the primary passenger without mutation.
 * @param {Object[]} [passengers=[]] - Stored travellers.
 * @param {Object} [contact={}] - Primary contact.
 * @returns {Object[]} Form/view data.
 * @example attachPrimaryPassengerContact(passengers, contact);
 */
export const attachPrimaryPassengerContact = (passengers = [], contact = {}) =>
  passengers.map((passenger, index) =>
    index === 0
      ? {
          ...passenger,
          contact: { ...(passenger.contact || {}), ...contact },
        }
      : passenger,
  );
/**
 * Validate required fields and matching emails in the current language.
 * @param {Object[]} [passengers=[]] - Form rows.
 * @param {Object} [contact={}] - Contact form.
 * @returns {Object} Form/view data.
 * @example validatePassengerForm(passengers, contact);
 */
export const validatePassengerForm = (passengers = [], contact = {}) => {
  const items = Array.isArray(passengers) ? passengers : [];
  const contactDetails = contact && typeof contact === "object" ? contact : {};
  const passengerErrors = items.map((passenger) => ({
    givenNames: String(passenger?.givenNames || "").trim()
      ? ""
      : t("passengerInformation.error.givenNames"),
    surnames: String(passenger?.surnames || "").trim()
      ? ""
      : t("passengerInformation.error.surnames"),
    dob: String(passenger?.dob || "").trim()
      ? ""
      : t("passengerInformation.error.dob"),
    gender: getGenderOptions().some((option) => option.value === passenger?.gender)
      ? ""
      : t("passengerInformation.error.gender"),
  }));
  const email = String(contactDetails.email || "").trim();
  const confirmEmail = String(contactDetails.confirmEmail || "").trim();
  const contactErrors = {
    phone: String(contactDetails.phone || "").trim()
      ? ""
      : t("passengerInformation.error.phone"),
    email: !email
      ? t("passengerInformation.error.email.required")
      : /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)
        ? ""
        : t("passengerInformation.error.email.invalid"),
    confirmEmail: !confirmEmail
      ? t("passengerInformation.error.confirmEmail.required")
      : email === confirmEmail
        ? ""
        : t("passengerInformation.error.confirmEmail.mismatch"),
  };
  return {
    passengerErrors,
    contactErrors,
    isValid: Boolean(
      items.length &&
      passengerErrors.every((errors) => !hasErrors(errors)) &&
      !hasErrors(contactErrors),
    ),
  };
};
/**
 * Build summary rows without modifying the traveller records.
 * @param {Object[]} [items=[]] - Form rows.
 * @returns {Object[]} Form/view data.
 * @example reviewPassengers(booking.passengers);
 */
export const reviewPassengers = (items = []) =>
  items.map((p, index) => ({
    id: p.id,
    name:
      [p.givenNames, p.surnames].filter(Boolean).join(" ") ||
