// ============================================================================
// BOOKING PAYLOAD
// Pure helpers; no API requests or page state updates.
// ============================================================================

/**
 * getSearchId: prepare booking data without side effects.
 * @param {Object} booking - Existing booking value.
 * @returns {string} Extracted value.
 * @example getSearchId(booking);
 */
export const getSearchId = (booking) =>
  booking?.results?.id || booking?.results?.search_id || booking?.searchId;
/**
 * getPackageId: prepare booking data without side effects.
 * @param {Object} booking - Existing booking value.
 * @returns {string} Extracted value.
 * @example getPackageId(booking);
 */
export const getPackageId = (booking) =>
  booking?.selectedFlight?.package_id || booking?.selectedFlight?.id;
/**
 * getContact: prepare booking data without side effects.
 * @param {Object} booking - Existing booking value.
 * @returns {Object} Extracted value.
 * @example getContact(booking);
 */
export const getContact = (booking) =>
  booking?.passengers?.[0]?.contact || booking?.contact || {};
/**
 * passengerType: prepare booking data without side effects.
 * @param {string} value - Existing booking value.
 * @returns {string} Extracted value.
 * @example passengerType('children');
 */
export const passengerType = (value) =>
  value === "children" ? "CNN" : value === "infants" || value === "infantsOnLap" ? "INF" : "ADT";

/**
 * getBookPayload: prepare booking data without side effects.
 * @param {Object} booking - Booking session.
 * @param {Object} [config={}] - Affiliate/campaign configuration.
 * @param {Object} [reviewState={}] - Seat review state.
 * @returns {Object} Existing booking API payload.
 * @example getBookPayload(booking, config, reviewState);
 */
export const getBookPayload = (booking, config = {}, reviewState = {}) => {
  const passengers = Array.isArray(booking.passengers) ? booking.passengers : [];
  const contact = getContact(booking);
  const payment = booking.payment || {};
  const payload = {
    search_id: getSearchId(booking),
    package_id: getPackageId(booking),
    affiliate_id: Number(booking.affiliate_id || config.AFFILIATE_ID),
    campaign_id: Number(booking.campaign_id || config.CAMPAIGN),
    client_ip_address: booking.clientIpAddress || "",
    client_http_user_agent: booking.clientHttpUserAgent || "AfriTrip Mini Program",
    contact_email: contact.email || "",
    billing_phone_country: contact.country?.code || contact.phoneCountry || "",
    billing_phone: contact.phone || "",
    billing_addr1: booking.billing?.address || "",
    billing_city: booking.billing?.city || "",
    billing_country: booking.billing?.country || contact.country?.code || "",
    billing_region: booking.billing?.region || "",
    billing_postal_code: booking.billing?.postalCode || "",
    seats_confirmed: reviewState.totalSeatCount ? 1 : 0,
    seat_selections: payment.seatSelections || {},
  };
  passengers.forEach((passenger, index) => {
    const number = index + 1;
    payload[`pax${number}_ptc`] = passengerType(passenger.passengerType);
    payload[`pax${number}_first_name`] = passenger.givenNames || "";
    payload[`pax${number}_middle_name`] = passenger.middleName || "";
    payload[`pax${number}_last_name`] = passenger.surnames || "";
    payload[`pax${number}_gender`] = passenger.gender || "";
    payload[`pax${number}_dob`] = passenger.dob || "";
    if (passenger.ffProgram) payload[`pax${number}_ff_program`] = passenger.ffProgram;
    if (passenger.ffNumber) payload[`pax${number}_ff_number`] = passenger.ffNumber;
  });
  return {
    ...payload,
    ...Object.fromEntries(
      ["cc_first_name", "cc_last_name", "cc_cvv", "cc_expiry_month", "cc_expiry_year", "cc_number"]
        .filter((key) => payment[key] !== undefined)
        .map((key) => [key, payment[key]]),
    ),
  };
};

