      const keyValidation = Validator.validateStateKey(key);
      if (!keyValidation.valid) {
        this._log(`❌ Invalid state key: ${keyValidation.error}`);
        return [];
      }
      return this.stateHistory.filter(change => change.key === key);
    }
    return [...this.stateHistory];
  }

