import { storage } from "../storage";

export const BOOKING_STORAGE_KEY = "afritrip.booking.payload.v1";
export const BOOKING_CHANGED_EVENT = "booking.payload.changed";
export const BOOKING_REVIEW_STATE_KEY = "booking.review";

const getBus = () => getApp().globalData.eventBus;

export const loadBooking = () => {
  const payload =
    storage.get(BOOKING_STORAGE_KEY, null) ||
    getApp().globalData.bookingPayload ||
    {};
  getApp().globalData.bookingPayload = payload;
  return payload;
};

/**
 * Load a projection of the booking payload containing only the requested keys.
 * This avoids loading or passing the entire booking object to pages that only
 * need a subset of fields.
 * @param {string[]} keys - array of top-level keys to keep (e.g. ['passengers','totals'])
 * @returns {Object} projected booking object
 */
export const loadBookingProjection = (keys = []) => {
  const full = loadBooking() || {};
  if (!Array.isArray(keys) || keys.length === 0) return full;
  const projected = {};
  keys.forEach((k) => {
    if (Object.prototype.hasOwnProperty.call(full, k)) {
      projected[k] = full[k];
    }
  });
  return projected;
};

export const saveBooking = (payload, source = "unknown") => {
  const nextPayload = { ...(payload || {}), updatedAt: Date.now() };
  storage.set(BOOKING_STORAGE_KEY, nextPayload);
  getApp().globalData.bookingPayload = nextPayload;
  getBus().emit(BOOKING_CHANGED_EVENT, { payload: nextPayload, source });
  return nextPayload;
};

export const updateBooking = (changes, source) =>
  saveBooking({ ...loadBooking(), ...(changes || {}) }, source);

export const clearBooking = () => {
  storage.remove(BOOKING_STORAGE_KEY);
  getApp().globalData.bookingPayload = null;
  getBus().emit(BOOKING_CHANGED_EVENT, { payload: null, source: "clear" });
};

export const subscribeBooking = (callback, namespace = "booking-page") =>
  getBus().on(
    BOOKING_CHANGED_EVENT,
    ({ payload, source }) => {
      callback(payload, source);
    },
    { namespace },
  );

