// ============================================================================
// i18n BEHAVIOR
// Injects translation data (_t) and t() method into pages and components
//
// USAGE:
//   import { i18nBehavior } from '../../utils/behaviors/i18n.js';
//
//   Page({
//     behaviors: [i18nBehavior],
//     // ...
//   });
//
// IN WXML:
//   <text>{{ _t['home.hero.line1'] }}</text>
//   <osn-typography message="{{ _t['new.title'] }}" />
// ============================================================================

import { t, getStrings, getLocale } from '../i18n/index.js';

export const i18nBehavior = Behavior({
  data: {
    _t: {},
    _locale: '',
  },

  // ── Component lifecycle ─────────────────────────────────
  lifetimes: {
    attached() {
      this._loadI18nStrings();
      this._subscribeToLocaleChanges();
    },

    detached() {
      if (this._i18nUnsub) {
        this._i18nUnsub();
        this._i18nUnsub = null;
      }
    },
  },

  // ── Component reacts to host page showing ───────────────
  pageLifetimes: {
    show() {
      this._loadI18nStrings();
    },
  },

  methods: {
    // ── Page lifecycle (merged when behavior is used with Page()) ──
    onLoad() {
      this._loadI18nStrings();
      this._subscribeToLocaleChanges();
    },

    onShow() {
      this._loadI18nStrings();
    },

    onUnload() {
      if (this._i18nUnsub) {
        this._i18nUnsub();
        this._i18nUnsub = null;
      }
    },

    /**
     * Translation function for JS-side use (toasts, modals, errors)
     * @param {string} key - Translation key
     * @param {Object} [params] - Interpolation parameters
     * @returns {string}
     */
    t(key, params) {
      return t(key, params);
    },

    /** @private */
    _loadI18nStrings() {
      this.setData({
        _t: getStrings(),
        _locale: getLocale(),
      });
    },

    /** @private */
    _subscribeToLocaleChanges() {
      // Guard against double-subscription
      if (this._i18nUnsub) return;

      try {
        const app = getApp();
        if (app?.globalData?.eventBus) {
          this._i18nUnsub = app.globalData.eventBus.onState('app.locale', () => {
            this._loadI18nStrings();
          });
        }
      } catch (e) {
        // Component may be attached before app is fully ready
      }
    },
  },
});

