import { init as initI18n, t } from "../../utils/i18n/index.js";

const PROJECTION_FIELDS = [
  "selectedFlight", "activeTab", "selectedCabin", "passengerCounts",
  "passengers", "reviewPassengers", "contact", "tripActions",
  "bookingResponse", "bookingStatus", "airlineConfirmation", "tickets",
  "to", "multiCityLegs",
];

Page({
  behaviors: [i18nBehavior],
  data: { trip: {}, tripScrollTop: 0 },

  onLoad() {
    initI18n();
    this._loadI18nStrings();
    this._subscribeToLocaleChanges();
    this.source = `trip-details-${Date.now()}`;
    this.unsubscribe = subscribeBooking((payload, source) => {
      if (source !== this.source) this.refresh(payload);
    }, this.source);
    this.unsubscribeLocale = getApp().globalData.eventBus.onState("app.locale", () => {
      if (!this.isDisposed) this.refresh();
    }, { namespace: this.source });
    this.refresh();
  },

  onShow() {
    this._loadI18nStrings();
    this.refresh();
  },
  onUnload() {
    this.isDisposed = true;
    if (this.unsubscribe) this.unsubscribe();
    if (this.unsubscribeLocale) this.unsubscribeLocale();
    if (this._i18nUnsub) {
      this._i18nUnsub();
      this._i18nUnsub = null;
    }
  },

  refresh(payload = null) {
    const booking = payload || loadBookingProjection(PROJECTION_FIELDS) || {};
    const trip = createTripDetails(booking);
    this.payload = { ...booking, trip, bookingReference: trip.bookingReference };
    this.setData({ trip, tripScrollTop: 0 });
  },

  handleTripBookingCopy() {
    if (this.payload.bookingReference) wx.setClipboardData({ data: this.payload.bookingReference });
  },

  handleTripCopy() {
    const confirmation = this.payload.trip?.confirmation;
    if (confirmation) wx.setClipboardData({ data: confirmation });
  },

  handleTripPhone(event) {
    const phoneNumber = String(event.detail.phone || "").replace(/[^\d+]/g, "");
    if (phoneNumber) wx.makePhoneCall({ phoneNumber });
  },

  handleTripShare() { wx.showToast({ title: t("tripDetails.action.shareTrip"), icon: "none" }); },
  handleTripPrintItinerary() { wx.showToast({ title: t("tripDetails.action.print"), icon: "none" }); },
  async handleTripDownload() {
    if (this.isExportingInvoice || this.isDisposed) return;
    // Export the displayed Billing snapshot, even before a booking is confirmed.
    const trip = this.data.trip;
    if (!trip?.price?.hasQuote) {
      wx.showToast({ title: t("tripDetails.error.noPrice"), icon: "none" });
      return;
    }
    if (!wx.env?.USER_DATA_PATH || typeof wx.getFileSystemManager !== "function" || typeof wx.openDocument !== "function") {
      wx.showToast({ title: t("tripDetails.error.pdfUnsupported"), icon: "none" });
      return;
    }
    this.isExportingInvoice = true;
    let errorMessage = t("tripDetails.error.pdfCreate");
    try {
      // Reuse one app-owned export file instead of filling local storage on every tap.
      const filePath = `${wx.env.USER_DATA_PATH}/afritrip-billing-summary.pdf`;
      await new Promise((resolve, reject) => wx.getFileSystemManager().writeFile({
        filePath,
        data: createInvoicePdf(invoiceLines({ trip })),
        encoding: "utf8",
        success: resolve,
        fail: reject,
      }));
      if (this.isDisposed) return;
      errorMessage = t("tripDetails.error.pdfOpen");
      // Tencent's native document viewer accepts a local PDF file path.
      await new Promise((resolve, reject) => wx.openDocument({
        filePath, fileType: "pdf", success: resolve, fail: reject,
      }));
    } catch {
      if (!this.isDisposed) wx.showToast({ title: errorMessage, icon: "none" });
    } finally {
      this.isExportingInvoice = false;
    }
  },
  handleTripAction(event) {
    wx.showToast({ title: t(event.detail.id === "rules" ? "tripDetails.action.rules" : "tripDetails.action.generic"), icon: "none" });
  },
  handleTripFlightAction(event) {
    const action = event.detail.action;
    const key = action === "Baggage info" ? "tripDetails.action.baggage"
      : action === "Flight details" ? "tripDetails.action.flightDetails" : "tripDetails.action.flight";
    wx.showToast({ title: t(key), icon: "none" });
  },
});

