Fichier `index.js` :
```
import { i18nBehavior } from "../../utils/behaviors/i18n";
import { init, t } from "../../utils/i18n/index";
import {
  getGenderOptions,
  getCountryOptions,
  hasErrors,
  getPrimaryPassengerContact,
  attachPrimaryPassengerContact,
  validatePassengerForm,
  reviewPassengers,
} from "../../utils/helpers/passengerForm";
import {
  createReviewPriceBreakdown,
  createCheckoutView,
  getCheckoutKey,
} from "../../utils/helpers/review";
import {
  loadBookingProjection,
  updateBooking,
  subscribeBooking,
} from "../../utils/booking/session";
import { navigateTo } from "../../utils/helpers/navigation";
import { BOOKING_ROUTES } from "../../utils/booking/routes";
import { backendAPI } from "../../utils/apis/index";
import { createPassengerRows } from "../../utils/helpers/passengerInformation";

Page({
  behaviors: [i18nBehavior],
  data: {
    passengers: [],
    phone: "",
    email: "",
    confirmEmail: "",
    genderOptions: [],
    countryOptions: [],
    countryIndex: 0,
    expandedPassengerIndex: -1,
    passengerTripExpanded: false,
    passengerFooterExpanded: true,
    passengerFormValid: false,
    validationAttempted: false,
    passengerErrors: [],
    contactErrors: {},
    passengerTotalCurrency: "USD",
    passengerFareRulesBanner: null,
    passengerFareRulesItems: null,
    passengerBaggageSummary: null,
    passengerBaggageRoutes: null,
    passengerPriceLines: [],
  },
  onLoad() {
    init();
    this._loadI18nStrings();
    this._subscribeToLocaleChanges();
    this.unsubscribeLocale = getApp().globalData.eventBus.onState("app.locale", () => {
      if (!this.isDisposed) this.refresh();
    });
    this.source = `passengers-${Date.now()}`;
    this.unsubscribe = subscribeBooking((p, s) => {
      if (s !== this.source) this.refresh(p);
    }, this.source);
    this.refresh();
    this.loadCheckoutData();
  },
  onShow() {
    this._loadI18nStrings();
    this.refresh();
    this.loadCheckoutData();
  },
  onUnload() {
    this.isDisposed = true;
    if (this.unsubscribe) this.unsubscribe();
    if (this.unsubscribeLocale) this.unsubscribeLocale();
    if (this._i18nUnsub) this._i18nUnsub();
    this._i18nUnsub = null;
  },

  // Cache normalized documents per search/package so changing language only
  // rebuilds display props. A failed endpoint can be retried on the next show.
  async loadCheckoutData() {
    if (this.checkoutLoading || this.isDisposed) return;
    const booking = loadBookingProjection([
      "searchId", "results", "selectedFlight", "passengerCheckout",
    ]) || {};
    const key = getCheckoutKey(booking);
    const cache = booking.passengerCheckout?.key === key ? booking.passengerCheckout : {};
    if (!key || (cache.rules && cache.tax)) return;
    const params = {
      searchId: booking.searchId || booking.results?.id,
      packageId: booking.selectedFlight.id,
    };
    this.checkoutLoading = true;
    try {
      const [rulesResult, taxResult] = await Promise.allSettled([
        cache.rules ? Promise.resolve(cache.rules) : backendAPI.getBaggageAndFareRules(params),
        cache.tax ? Promise.resolve(cache.tax) : backendAPI.getTaxBreakdown(params),
      ]);
      if (this.isDisposed) return;
      const full = loadBookingProjection([]) || {};
      // A response from an old selection must never replace the current quote.
      if (getCheckoutKey(full) !== key) return;
      const passengerCheckout = {
        key,
        rules: rulesResult.status === "fulfilled" ? rulesResult.value : null,
        tax: taxResult.status === "fulfilled" ? taxResult.value : null,
      };
      const changes = {
        passengerCheckout,
        ...createCheckoutView({ ...full, passengerCheckout }),
      };
      updateBooking(changes, this.source);
      this.refresh({ ...full, ...changes });
    } finally {
      this.checkoutLoading = false;
    }
  },
  // Only load the fields required by this page to avoid passing full booking
  // objects around and accidentally overwriting unrelated data.
  refresh(payload = null) {
    const PROJECTION_FIELDS = [
      "searchId",
      "results",
      "passengerCheckout",
      "passengers",
      "contact",
      "trip",
      "tripSummarySegments",
      "totals",
      "selectedFlight",
      "activeTab",
      "selectedCabin",
      "passengerCounts",
      "fareRules",
      "baggageAllowance",
      "priceBreakdown",
      "reviewPriceBreakdown",
    ];
    const booking = payload || loadBookingProjection(PROJECTION_FIELDS) || {};
    // Passenger rows come from the selected package (types/count), keeping any
    // value the traveller already typed.
    const storedPassengers = createPassengerRows(booking);
    const contact = getPrimaryPassengerContact(
      storedPassengers,
      booking.contact,
    );
    const passengers = attachPrimaryPassengerContact(storedPassengers, contact);
    const bookingWithoutRootContact = { ...booking };
    delete bookingWithoutRootContact.contact;
    this.payload = { ...bookingWithoutRootContact, ...createCheckoutView(booking), passengers };
    const validation = validatePassengerForm(passengers, contact);
    const showErrors = this.data.validationAttempted;
    const fareRules = this.payload.fareRules || null;
    const baggageAllowance = this.payload.baggageAllowance || null;
    const priceBreakdown = this.payload.priceBreakdown || null;
    const totalAmount =
      priceBreakdown?.amount || this.payload.totals?.current || "0";
    this.setData({
      passengers,
      genderOptions: getGenderOptions(),
      countryOptions: getCountryOptions(),
      phone: contact.phone || "",
      email: contact.email || "",
      confirmEmail: contact.confirmEmail || "",
      countryIndex: Math.max(
        0,
        getCountryOptions().findIndex((c) => contact.country?.code === c.code),
      ),
      passengerTripTitle: this.payload.trip?.title || t("passengerInformation.yourTrip"),
      passengerTripSegments: this.payload.tripSummarySegments || [],
      passengerTotalAmount: totalAmount,
      passengerTotalCurrency:
        priceBreakdown?.currency || this.payload.totals?.currency || "USD",
      passengerFareRulesBanner: fareRules?.banner || null,
      passengerFareRulesItems: fareRules?.items || null,
      passengerBaggageSummary: baggageAllowance?.summary || null,
      passengerBaggageRoutes: baggageAllowance?.routeList || null,
      passengerPriceLines: priceBreakdown?.lines || [],
      passengerFormValid: validation.isValid,
      passengerErrors: showErrors
        ? validation.passengerErrors
        : passengers.map(() => ({})),
      contactErrors: showErrors ? validation.contactErrors : {},
    });
  },
  persist(changes) {
    // Use updateBooking so we merge changes with the full stored booking and
    // avoid overwriting unrelated fields that this page didn't load.
    const full = updateBooking(changes, this.source);
    this.refresh(full);
  },
  updatePassenger(event, field, value) {
    const index = Number(event.currentTarget.dataset.index);
    const passengers = [...(this.payload.passengers || [])];
    passengers[index] = { ...passengers[index], [field]: value };
    this.persist({ passengers });
  },
  updateContact(field, value) {
    const passengers = [...(this.payload.passengers || [])];
    if (!passengers[0]) return;
    passengers[0] = {
      ...passengers[0],
      contact: { ...(passengers[0].contact || {}), [field]: value },
    };
    this.persist({ passengers });
  },
  handleTogglePassengerForm(event) {
    const index = Number(event.currentTarget.dataset.index);
    this.setData({
      expandedPassengerIndex:
        this.data.expandedPassengerIndex === index ? -1 : index,
    });
  },
  handleTogglePassengerTripDetails() {
    this.setData({ passengerTripExpanded: !this.data.passengerTripExpanded });
  },
  handlePassengerFooterToggle(event) {
    this.setData({ passengerFooterExpanded: event.detail.expanded });
  },
  handlePassengerInput(event) {
    this.updatePassenger(
      event,
      event.currentTarget.dataset.field,
      event.detail.value,
    );
  },
  handlePassengerDobChange(event) {
    this.updatePassenger(event, "dob", event.detail.value);
  },
  handlePassengerGenderChange(event) {
    const index = Number(event.currentTarget.dataset.index);
    const option = getGenderOptions().find((item) => item.value === event.detail.value);
    const passengers = [...(this.payload.passengers || [])];
    if (!option || !passengers[index]) return;
    passengers[index] = {
      ...passengers[index],
      gender: option.value,
      genderLabel: option.label,
    };
    this.persist({ passengers });
  },
  handlePassengerCountryChange(event) {
    this.updateContact("country", getCountryOptions()[Number(event.detail.value)]);
  },
  handlePassengerPhoneInput(event) {
    this.updateContact("phone", event.detail.value);
  },
  handlePassengerEmailInput(event) {
    this.updateContact("email", event.detail.value);
  },
  handlePassengerConfirmEmailInput(event) {
    this.updateContact("confirmEmail", event.detail.value);
  },
  handlePassengerContinue() {
    const contact = this.payload.passengers?.[0]?.contact || {};
    const validation = validatePassengerForm(this.payload.passengers, contact);
    if (!validation.isValid) {
      const firstInvalidIndex = validation.passengerErrors.findIndex(
        (errors, index) =>
          hasErrors(errors) ||
          (index === 0 && hasErrors(validation.contactErrors)),
      );
      this.setData({
        validationAttempted: true,
        passengerErrors: validation.passengerErrors,
        contactErrors: validation.contactErrors,
        expandedPassengerIndex:
          firstInvalidIndex >= 0
            ? firstInvalidIndex
            : this.data.expandedPassengerIndex,
      });
      return;
    }
    const passengers = reviewPassengers(this.payload.passengers);
    const reviewPriceBreakdown = createReviewPriceBreakdown(this.payload, passengers);
    const bookingPayload = {
      ...this.payload,
      currentStep: "seat-map",
      passengers: this.payload.passengers,
      selectedFlight: this.payload.selectedFlight,
      reviewPassengers: passengers,
      reviewPriceBreakdown,
    };
    updateBooking(bookingPayload, this.source);
    navigateTo(BOOKING_ROUTES.seatMap);
  },
});

