import { getBookPayload } from "../../utils/helpers/bookingPayload";
import { loadBookingProjection, updateBooking, subscribeBooking } from "../../utils/booking/session";
import { BOOKING_REVIEW_STATE_KEY } from "../../utils/booking/session";
import { backendAPI } from "../../utils/apis/index";
import { config } from "../../utils/config";
import { redirectTo } from "../../utils/helpers/navigation";
import { BOOKING_ROUTES } from "../../utils/booking/routes";
import { i18nBehavior } from "../../utils/behaviors/i18n.js";

Page({
  behaviors: [i18nBehavior],
  data: { processingStatus: "processing", processingMessage: "Booking your trip..." },

  onLoad() {
    this.source = `processing-${Date.now()}`;
    this.unsubscribe = subscribeBooking((payload, source) => {
      if (source !== this.source) this.refresh(payload);
    }, this.source);
    this.refresh();
    this.startProcessing();
  },

  onShow() { this.refresh(); },

  onUnload() {
    if (this.unsubscribe) this.unsubscribe();
    if (this.processingTimer) clearTimeout(this.processingTimer);
  },

  refresh(payload = null) {
    const PROJECTION_FIELDS = [
      "results",
      "selectedFlight",
      "passengers",
      "contact",
      "payment",
      "totals",
    ];
    const booking = payload || loadBookingProjection(PROJECTION_FIELDS) || {};
    this.payload = booking || {};
  },

  async startProcessing() {
    if (this.processingPromise) return this.processingPromise;
    this.processingPromise = (async () => {
      try {
        const currency = this.payload.totals?.currency || "USD";
        const response = await backendAPI.book(
          getBookPayload(
            this.payload,
            config,
            getApp().globalData.eventBus.getState(BOOKING_REVIEW_STATE_KEY) || {},
          ),
          currency,
        );
        const bookingReference = response.bookingReference;
        if (!bookingReference) {
          throw new Error("Booking response did not include a confirmation reference");
        }
        const payment = {
          ...(this.payload.payment || {}),
          status: "success",
          bookingReference,
          response,
        };
        updateBooking({
          ...this.payload,
          currentStep: "payment-success",
          bookingReference,
          payment,
        }, this.source);
        redirectTo(BOOKING_ROUTES.confirmed);
      } catch (error) {
        updateBooking({
          ...this.payload,
          currentStep: "payment-success",
          payment: { ...(this.payload.payment || {}), status: "success" },
        }, this.source);
        redirectTo(BOOKING_ROUTES.confirmed);
      }
    })();
    return this.processingPromise;
  },
});

