import { getSearchId, getPackageId } from "../../utils/helpers/bookingPayload";
import { loadBookingProjection, updateBooking, subscribeBooking } from "../../utils/booking/session";
import { backendAPI } from "../../utils/apis/index";
import { redirectTo } from "../../utils/helpers/navigation";
import { BOOKING_ROUTES } from "../../utils/booking/routes";
import { i18nBehavior } from "../../utils/behaviors/i18n.js";

Page({
  behaviors: [i18nBehavior],
  data: { paymentTotalPrice: "0", availabilityValid: null },
  onLoad() {
    this.source = `payment-${Date.now()}`;
    this.unsubscribe = subscribeBooking((p, s) => {
      if (s !== this.source) this.refresh(p);
    }, this.source);
    this.refresh();
    this.availabilityPromise = this.validateAvailability();
  },
  onShow() { this.refresh(); },
  onUnload() { if (this.unsubscribe) this.unsubscribe(); },
  refresh(payload = null) {
    const PROJECTION_FIELDS = [
      "results",
      "selectedFlight",
      "totals",
    ];
    const booking = payload || loadBookingProjection(PROJECTION_FIELDS) || {};
    this.payload = booking || {};
    this.setData({ paymentTotalPrice: this.payload.totals?.current || "0" });
  },
  async validateAvailability() {
    const searchId = getSearchId(this.payload);
    const packageId = getPackageId(this.payload);
    if (!searchId || !packageId) {
      this.setData({ availabilityValid: true });
      return true;
    }
    try {
      const availability = await backendAPI.checkAvailability(searchId, packageId);
      if (!availability.available) {
        throw new Error(availability.message || "Flight is no longer available");
      }
      this.setData({ availabilityValid: true });
      return true;
    } catch (error) {
      this.setData({ availabilityValid: false });
      wx.showToast({ title: error.message || "Flight is no longer available", icon: "none" });
      return false;
    }
  },
  async handleConfirmPayment() {
    const available = await (this.availabilityPromise || this.validateAvailability());
    if (!available) return;
    updateBooking({
      ...this.payload,
      currentStep: "payment-processing",
      payment: {
        ...(this.payload.payment || {}),
        status: "processing",
      },
    }, this.source);
    redirectTo(BOOKING_ROUTES.processing);
  },
});

