// ============================================================================
// HOME PAGE
// Demonstrates: initPromise pattern, EventBus, component usage, navigation
// ============================================================================

import {
  TRAVEL_CLASS_OPTIONS,
  TRAVEL_CABIN_CLASSES,
  STORAGE_KEYS,
} from "../../utils/constants/index";
import {
  formatFrenchDate,
  getTodayIsoDate,
} from "../../utils/formatters/index";
import { navigateTo } from "../../utils/helpers/navigation";
import { createWorkflowData } from "../../mocks/search-workflow";
import { backendAPI } from "../../utils/apis/index";
import { storage } from "../../utils/storage";
import { i18nBehavior } from "../../utils/behaviors/i18n.js";
import {
  computeSearchButtonDisabled,
  parseLocation,
  normalizeMultiCityLegs,
  createResultsCacheKey,
  getLocationLabel,
  normalizeMultiCityDisplayLegs,
  getRecentSearchDates,
  hasDirectFare,
} from "../../utils/helpers/index";

const app = getApp();
const { STATE_KEYS, EVENTS } = app.globalData;

function saveRecentSearch(searchForm, activeTab) {
  const recentSearch = {
    id: Date.now(),
    from: getLocationLabel(searchForm.from),
    to: getLocationLabel(searchForm.to),
    dates: getRecentSearchDates(searchForm, activeTab),
    type:
      activeTab === "multiCity"
        ? "Multi-city"
        : activeTab === "oneWay"
          ? "One-way"
          : "Round trip",
    image: "/assets/images/cover_search.png",
    activeTab,
    departDate: searchForm.departDate,
    departDateDisplay: searchForm.departDateDisplay,
    returnDate: searchForm.returnDate,
    returnDateDisplay: searchForm.returnDateDisplay,
    multiCityLegs: searchForm.multiCityLegs,
    nonstopOnly: searchForm.nonstopOnly,
    removeLowCost: searchForm.removeLowCost,
  };
  const stored = wx.getStorageSync(STORAGE_KEYS.RECENT_SEARCHES);
  const previous = Array.isArray(stored) ? stored : [];
  const next = [
    recentSearch,
    ...previous.filter((item) => item.id !== recentSearch.id),
  ].slice(0, 6);
  wx.setStorageSync(STORAGE_KEYS.RECENT_SEARCHES, next);
  return next;
}

Page({
  behaviors: [i18nBehavior],
  data: {
    isLoading: true,
    userName: "",
    activeTab: "roundTrip",
    activeTabLabel: "Round Trip",
    tabs: TRAVEL_CLASS_OPTIONS.ITEMS,
    todayDate: getTodayIsoDate(),
    dateValidationMessage: "",
    searchForm: {
      from: "",
      to: "",
      departDate: "",
      departDateDisplay: "",
      returnDate: "",
      returnDateDisplay: "",
      passengers: "1 Traveller, Economy",
      nonstopOnly: false,
      removeLowCost: false,
      multiCityLegs: [
        {
          id: "leg-1",
          from: "",
          to: "",
          date: "",
          dateDisplay: "",
        },
        {
          id: "leg-2",
          from: "",
          to: "",
          date: "",
          dateDisplay: "",
        },
      ],
    },
    isSearchButtonDisabled: true,
    citySuggestions: [],
    recentSearches: [],
    cardWidth: 260,
    showBottomSheet: false,
    showNoFlightsModal: false,
    noFlightsModalType: "noFlights",
    // Passenger counts used in bottom sheet
    passengerCounts: {
      adults: 1,
      children: 0,
      infants: 0,
      infantsOnLap: 0,
    },
    // Cabin class options and selection
    cabinClasses: TRAVEL_CABIN_CLASSES,
    selectedCabin: TRAVEL_CABIN_CLASSES[0].value,
    // Computed estimate string (moved to results page)
  },

  /**
   * Page initialization
   * Awaits app initialization before accessing shared state
   */
  async onLoad() {
    this.computeCardWidth();
    const storedRecentSearches = wx.getStorageSync(
      STORAGE_KEYS.RECENT_SEARCHES,
    );

    if (Array.isArray(storedRecentSearches) && storedRecentSearches.length) {
      this.setData({ recentSearches: storedRecentSearches });
    }
    // Wait for app initialization to complete (non-blocking pattern)
    await app.globalData.initPromise;

    // Read initial data from EventBus
    const userData = app.globalData.eventBus.getState(STATE_KEYS.USER_DATA);

    this.setData({
      isLoading: false,
      cardWidth: Math.floor(this.data.cardWidth),
      userName: userData?.fullName || "Guest",
    });

    // Subscribe to user data changes
    this._unsubUser = app.globalData.eventBus.onState(
      STATE_KEYS.USER_DATA,
      (data) => {
        this.setData({ userName: data?.fullName || "Guest" });
      },
    );
  },

  async fetchFares(searchForm = this.data.searchForm) {
    const origin = parseLocation(searchForm.from);
    const destination = parseLocation(searchForm.to);

    try {
      const fares = await backendAPI.GetPhares({
        departDate: searchForm?.departDate,
        originIata: origin?.code,
        destinationIata: destination?.code,
        returnDate: searchForm?.returnDate,
        segments: searchForm?.multiCityLegs?.map((leg) => ({
          date: leg.date,
          from: parseLocation(leg.from).code,
          to: parseLocation(leg.to).code,
        })),
        type: this?.data?.activeTab?.toLowerCase(),
        seat_class: this?.data?.selectedCabin,
        passengerCount: searchForm?.passengerCounts,
      });
      return fares;
    } catch (error) {
      console.error("Failed to fetch fares", error);
      return null;
    }
  },

  /**
   * Cleanup subscriptions on page unload
   */
  onUnload() {
    if (typeof this._unsubUser === "function") {
      this._unsubUser();
    }
  },

  // ==========================================================================
  // EVENT HANDLERS
  // ==========================================================================

  /**
   * Navigate to demo page
   */

  computeCardWidth() {
    const sys = wx.getWindowInfo();
    const screenWidth = sys.windowWidth;
    const sidePadding = 12;
    const gap = 10;
    const peekRatio = 0.65; // ↓ diminué de 0.5 à 0.35 => card plus petite, moins visible de la suivante

    const cardWidth = (screenWidth - sidePadding * 2 - gap) / (1 + peekRatio);

    this.setData({ cardWidth: Math.floor(cardWidth) });
  },

  /**
   * Switch between flight search types
   */
  handleSelectTab(event) {
    const value = event.currentTarget.dataset.value;
    const selectedTab = this.data.tabs.find((item) => item.value === value);
    const multiCityLegs =
      value === "multiCity"
        ? normalizeMultiCityDisplayLegs(this.data.searchForm.multiCityLegs)
        : this.data.searchForm.multiCityLegs;

    const nextState = {
      activeTab: value,
      activeTabLabel: selectedTab ? selectedTab.label : "Round Trip",
      "searchForm.multiCityLegs": multiCityLegs,
      isSearchButtonDisabled: computeSearchButtonDisabled(value, {
        ...this.data.searchForm,
        multiCityLegs,
      }),
    };

    this.setData(nextState);
  },

  /**
   * Open results page
   */
  async handleSearchFlights() {
    if (this.data.submitting) return;

    this.setData({ submitting: true });
    const searchForm = {
      ...this.data.searchForm,
      passengerCounts: this.data.passengerCounts,
      selectedCabin: this.data.selectedCabin,
    };
    const from = parseLocation(searchForm.from);
    const to = parseLocation(searchForm.to);
    const multiCityLegs = normalizeMultiCityLegs(searchForm.multiCityLegs);
    const cachedPayload =
      app.globalData.eventBus.getState(STORAGE_KEYS.BOOKING_STATE, {}) || {};
    const searchPayload = {
      ...searchForm,
      activeTab: this.data.activeTab,
      bookingReference: cachedPayload.bookingReference,
      multiCityLegs,
    };
    const cacheKey = createResultsCacheKey(
      searchPayload,
      this.data.passengerCounts,
      this.data.selectedCabin,
    );
    const hasCachedResults =
      cachedPayload.resultsCacheKey === cacheKey &&
      Array.isArray(cachedPayload.results) &&
      cachedPayload.results.length > 0;

    try {
      if (hasCachedResults) {
        navigateTo("/pages/flights/index");
        return;
      }

      const fares = await this.fetchFares(searchForm);
      if (!fares) return;
      if (fares.count === 0) {
        this.setData({
          showNoFlightsModal: true,
          noFlightsModalType: "noFlights",
        });
        return;
      }
      if (searchForm.nonstopOnly && !hasDirectFare(fares)) {
        this.setData({
          showNoFlightsModal: true,
          noFlightsModalType: "noDirectFlights",
        });
        return;
      }

      const payload = {
        ...createWorkflowData(searchPayload, fares),
        legs: [{ from }, { to }],
      };

      const recentSearches = saveRecentSearch(
        searchPayload,
        this.data.activeTab,
      );

      storage.set(STORAGE_KEYS.BOOKING, payload);
      app.globalData.bookingPayload = payload;
      app.globalData.eventBus.setState(STORAGE_KEYS.BOOKING_STATE, payload);

      this.setData({ recentSearches });
      navigateTo("/pages/flights/index");
    } finally {
      this.setData({ submitting: false });
    }
  },

  /**
   * Update a field in the search form
   */
  handleSearchFieldInput(event) {
    const { fieldName, value } = event.detail || {};
    if (!fieldName) return;

    const updatedSearchForm = {
      ...this.data.searchForm,
      [fieldName]: value,
    };

    const nextState = {
      [`searchForm.${fieldName}`]: value,
    };

    if (fieldName === "from" || fieldName === "to") {
      nextState.isSearchButtonDisabled = computeSearchButtonDisabled(
        this.data.activeTab,
        updatedSearchForm,
      );
    }

    this.setData(nextState);
    this.updateCitySuggestions(value);
  },

  /**
   * Update a field in a multi-city leg
   */
  handleMultiCityFieldInput(event) {
    const { fieldName, value, legIndex } = event.detail || {};
    if (!fieldName || legIndex === undefined) return;

    const currentLegs = [...this.data.searchForm.multiCityLegs];
    currentLegs[legIndex] = {
      ...currentLegs[legIndex],
      [fieldName]: value,
    };

    this.setData({
      [`searchForm.multiCityLegs[${legIndex}].${fieldName}`]: value,
      isSearchButtonDisabled: computeSearchButtonDisabled(this.data.activeTab, {
        ...this.data.searchForm,
        multiCityLegs: currentLegs,
      }),
    });

    this.updateCitySuggestions(value);
  },

  async updateCitySuggestions(value) {
    const query = String(value || "").trim();
    if (!query) {
      this.setData({ citySuggestions: [] });
      return;
    }

    this._autocompleteRequestId = (this._autocompleteRequestId || 0) + 1;
    const requestId = this._autocompleteRequestId;

    try {
      const suggestions = await backendAPI.getAutocompleteCity(query);
      if (requestId === this._autocompleteRequestId) {
        this.setData({ citySuggestions: suggestions });
      }
    } catch (error) {
      console.error("Failed to fetch city suggestions", error);
    }
  },

  /**
   * Update a date field in the search form
   */
  handleSearchDateChange(event) {
    const { fieldName, value } = event.detail || {};
    if (!fieldName || !value) return;

    const today = getTodayIsoDate();
    const nextSearchForm = {
      ...this.data.searchForm,
      [fieldName]: value,
    };
    let dateValidationMessage = "";

    if (fieldName === "departDate" && value < today) {
      nextSearchForm.departDate = "";
      nextSearchForm.departDateDisplay = "";
      dateValidationMessage =
        "La date de départ ne peut pas être dans le passé.";
    }

    if (fieldName === "returnDate" && nextSearchForm.departDate) {
      if (value <= nextSearchForm.departDate) {
        nextSearchForm.returnDate = "";
        nextSearchForm.returnDateDisplay = "";
        dateValidationMessage =
          "La date de retour doit être après la date de départ.";
      }
    }

    if (fieldName === "departDate" && nextSearchForm.returnDate) {
      if (nextSearchForm.returnDate <= value) {
        nextSearchForm.returnDate = "";
        nextSearchForm.returnDateDisplay = "";
        dateValidationMessage =
          "La date de retour doit être après la date de départ.";
      }
    }

    const displayValue = formatFrenchDate(nextSearchForm[fieldName]);
    nextSearchForm[`${fieldName}Display`] = displayValue;

    this.setData({
      [`searchForm.${fieldName}`]: nextSearchForm[fieldName],
      [`searchForm.${fieldName}Display`]: nextSearchForm[`${fieldName}Display`],
      "searchForm.departDate": nextSearchForm.departDate,
      "searchForm.departDateDisplay": nextSearchForm.departDateDisplay,
      "searchForm.returnDate": nextSearchForm.returnDate,
      "searchForm.returnDateDisplay": nextSearchForm.returnDateDisplay,
      dateValidationMessage,
      isSearchButtonDisabled: computeSearchButtonDisabled(
        this.data.activeTab,
        nextSearchForm,
      ),
    });
  },

  /**
   * Add a new leg to the multi-city itinerary
   */
  handleAddMultiCityLeg() {
    const currentLegs = this.data.searchForm.multiCityLegs || [];

    const nextLegs = [
      ...currentLegs,
      {
        id: `leg-${Date.now()}`,
        from: "",
        to: "",
        date: "",
        dateDisplay: "",
      },
    ];

    this.setData({
      "searchForm.multiCityLegs": nextLegs,
      isSearchButtonDisabled: computeSearchButtonDisabled(this.data.activeTab, {
        ...this.data.searchForm,
        multiCityLegs: nextLegs,
      }),
    });
  },

  /**
   * Remove a leg from the multi-city itinerary
   */
  handleRemoveMultiCityLeg(event) {
    const legIndex = Number(event.currentTarget.dataset.legIndex);
    if (Number.isNaN(legIndex)) return;

    const currentLegs = this.data.searchForm.multiCityLegs || [];
    if (currentLegs.length <= 2) return;

    const updatedLegs = currentLegs.filter((_, index) => index !== legIndex);

    this.setData({
      "searchForm.multiCityLegs": updatedLegs,
      isSearchButtonDisabled: computeSearchButtonDisabled(this.data.activeTab, {
        ...this.data.searchForm,
        multiCityLegs: updatedLegs,
      }),
    });
  },

  /**
   * Update a date field in a multi-city leg
   */
  handleMultiCityDateChange(event) {
    const { fieldName, value, legIndex } = event.detail || {};
    if (!fieldName || legIndex === undefined || !value) return;

    const today = getTodayIsoDate();
    const currentLegs = [...this.data.searchForm.multiCityLegs];
    const previousLegDate = currentLegs[legIndex - 1]?.date;
    let dateValidationMessage = "";

    if (value < today) {
      currentLegs[legIndex] = {
        ...currentLegs[legIndex],
        [fieldName]: "",
        [`${fieldName}Display`]: "",
      };
      dateValidationMessage =
        "La date de départ ne peut pas être dans le passé.";
    } else if (
      fieldName === "date" &&
      previousLegDate &&
      value < previousLegDate
    ) {
      currentLegs[legIndex] = {
        ...currentLegs[legIndex],
        [fieldName]: "",
        [`${fieldName}Display`]: "",
      };
      dateValidationMessage =
        "La date de ce trajet doit être égale ou postérieure à celle du trajet précédent.";
    } else {
      currentLegs[legIndex] = {
        ...currentLegs[legIndex],
        [fieldName]: value,
      };
    }

    const displayValue = formatFrenchDate(currentLegs[legIndex][fieldName]);

    this.setData({
      [`searchForm.multiCityLegs[${legIndex}].${fieldName}`]:
        currentLegs[legIndex][fieldName],
      [`searchForm.multiCityLegs[${legIndex}].${fieldName}Display`]:
        displayValue,
      dateValidationMessage,
      isSearchButtonDisabled: computeSearchButtonDisabled(this.data.activeTab, {
        ...this.data.searchForm,
        multiCityLegs: currentLegs,
      }),
    });
  },

  /**
   * Close other date pickers when one opens
   */
  handleCloseOtherDatePickers(event) {
    const { fieldName, legIndex } = event.detail || {};
    if (!fieldName) return;

    const dateFields = this.selectAllComponents(".date-field");
    dateFields.forEach((component) => {
      const isSameField = component?.data?.fieldName === fieldName;
      const isSameLeg = component?.data?.legIndex === legIndex;
      if (!isSameField || !isSameLeg) {
        component?.closeDatePicker?.();
      }
    });
  },

  /**
   * Update search filters from checkbox-group
   */
  handleFilterChange(event) {
    const selected = event.detail.value || [];
    const nonstopOnly = Array.isArray(selected)
      ? selected.includes("nonstop")
      : selected === "nonstop";
    const removeLowCost = Array.isArray(selected)
      ? selected.includes("lowcost")
      : selected === "lowcost";

    const nextState = {
      "searchForm.nonstopOnly": nonstopOnly,
      "searchForm.removeLowCost": removeLowCost,
    };
    this.setData(nextState);
  },

  /**
   * Handle continue button click on recent search card
   */
  handleRecentSearchContinue(event) {
    const { from, to, type, activeTab, multiCityLegs } = event.detail || {};
    const selectedTab =
      activeTab ||
      (type === "Multi-city"
        ? "multiCity"
        : type === "One-way"
          ? "oneWay"
          : "roundTrip");
    const nextSearchForm = {
      ...this.data.searchForm,
      from,
      to,
      departDate: event.detail.departDate || "",
      departDateDisplay: event.detail.departDateDisplay || "",
      returnDate: event.detail.returnDate || "",
      returnDateDisplay: event.detail.returnDateDisplay || "",
      multiCityLegs: normalizeMultiCityDisplayLegs(
        multiCityLegs || this.data.searchForm.multiCityLegs,
      ),
      nonstopOnly: Boolean(event.detail.nonstopOnly),
      removeLowCost: Boolean(event.detail.removeLowCost),
    };

    // Populate search form with the selected recent search
    this.setData(
      {
        activeTab: selectedTab,
        activeTabLabel:
          this.data.tabs.find((item) => item.value === selectedTab)?.label ||
          "Round Trip",
        searchForm: nextSearchForm,
        isSearchButtonDisabled: computeSearchButtonDisabled(
          selectedTab,
          nextSearchForm,
        ),
      },
      () => {
        this.handleSearchFlights();
      },
    );
  },
  // ==========================================================================
  // MODAL HANDLERS
  // ==========================================================================

  handleOpenBottomSheet() {
    this.setData({ showBottomSheet: true });
  },

  handleCloseBottomSheet() {
    // Update passengers display string when closing
    const pc = this.data.passengerCounts || {};
    const totalTravellers =
      (pc.adults || 0) +
      (pc.children || 0) +
      (pc.infants || 0) +
      (pc.infantsOnLap || 0);
    const cabinLabel =
      (this.data.cabinClasses || []).find(
        (c) => c.value === this.data.selectedCabin,
      )?.label || "Economy";

    this.setData({
      showBottomSheet: false,
      "searchForm.passengers": `${totalTravellers} Traveller${totalTravellers > 1 ? "s" : ""}, ${cabinLabel}`,
    });
  },

  handleCloseNoFlightsModal() {
    this.setData({
      showNoFlightsModal: false,
      noFlightsModalType: "noFlights",
    });
  },

  handleViewFlightsWithStops() {
    this.setData(
      {
        "searchForm.nonstopOnly": false,
        showNoFlightsModal: false,
        noFlightsModalType: "noFlights",
      },
      () => this.handleSearchFlights(),
    );
  },

  /**
   * Handle increment/decrement for passenger counts
   */
  handleChangePassenger(event) {
    const { passengerType, action } = event.detail || {};
    if (!passengerType || !action) return;

    const current = { ...(this.data.passengerCounts || {}) };
    const min = 0;
    const max = 9;

    if (action === "increment") {
      current[passengerType] = Math.min((current[passengerType] || 0) + 1, max);
    } else if (action === "decrement") {
      if (passengerType === "adults") {
        current[passengerType] = Math.max((current[passengerType] || 0) - 1, 1);
      } else {
        current[passengerType] = Math.max(
          (current[passengerType] || 0) - 1,
          min,
        );
      }
    }

    this.setData({ passengerCounts: current });
  },

  /**
   * Handle cabin selection change from radio-group
   */
  handleCabinChange(event) {
    const value = event.detail && event.detail.value;
    if (!value) return;
    this.setData({ selectedCabin: value });
  },

  /**
   * Compute a quick estimated price string based on passenger counts and cabin class
   */
});

