import { getSearchId, getPackageId } from "../../utils/helpers/bookingPayload";
import { valueOf, price, createUpgradeFares } from "../../utils/helpers/index";
import {
  loadBookingProjection,
  updateBooking,
  subscribeBooking,
} from "../../utils/booking/session";
import { backendAPI } from "../../utils/apis/index";
import { navigateTo } from "../../utils/helpers/navigation";
import { BOOKING_ROUTES } from "../../utils/booking/routes";
import { i18nBehavior } from "../../utils/behaviors/i18n.js";

Page({
  behaviors: [i18nBehavior],
  data: {
    upgradeFares: [],
    selectedUpgradeFare: "",
    upgradeCarouselIndex: 0,
    upgradeCarouselOffset: 0,
    upgradeTotalPrice: "0",
    showUpgradeAlert: true,
    isUpgradeLoading: false,
  },
  onLoad() {
    this.source = `upgrade-${Date.now()}`;
    this.unsubscribe = subscribeBooking((payload, source) => {
      if (source !== this.source) this.refresh(payload);
    }, this.source);
    this.refresh();
    this.loadFareFamilies();
  },
  onShow() {
    this.refresh();
  },
  onUnload() {
    if (this.unsubscribe) this.unsubscribe();
  },
  refresh(payload = null) {
    const PROJECTION_FIELDS = [
      "results",
      "selectedFlight",
      "upgradeFares",
      "selectedUpgradeFare",
      "totals",
    ];
    const booking = payload || loadBookingProjection(PROJECTION_FIELDS) || {};
    this.payload = booking || {};
    const fares = this.payload.upgradeFares || [];
    const selected = this.payload.selectedUpgradeFare || fares[0] || {};
    const index = Math.max(
      0,
      fares.findIndex((item) => item.id === selected.id),
    );
    this.setData({
      upgradeFares: fares,
      selectedUpgradeFare: selected.id || "",
      upgradeCarouselIndex: index,
      upgradeCarouselOffset: -Math.min(index * 520, 520),
      upgradeTotalPrice: this.payload.totals?.current || "0",
    });
  },
  persist(changes) {
    const full = updateBooking(
      { ...this.payload, ...(changes || {}) },
      this.source,
    );
    this.payload = full || this.payload;
  },
  async loadFareFamilies() {
    const searchId = getSearchId(this.payload);
    const packageId = getPackageId(this.payload);
    if (!searchId || !packageId) return;
    try {
      const response = await backendAPI.getFareFamilyOptions(searchId, packageId);
      const families = response?.families || [];
      if (!families.length) return;
      const upgradeFares = createUpgradeFares(families);
      this.persist({ upgradeFares });
      this.refresh(this.payload);
    } catch (error) {
      console.warn("Unable to load fare families", error);
    }
  },
  handleDismissUpgradeAlert() {
    this.setData({ showUpgradeAlert: false });
  },
  async selectFare(index) {
    const fare = (this.payload.upgradeFares || [])[index];
    if (!fare) return;
    let selectedTotal = price(
      valueOf(this.payload.totals?.base) + (fare.surcharge || 0),
    );
    const searchId = getSearchId(this.payload);
    const packageId = getPackageId(this.payload);
    if (searchId && packageId && fare.ff !== undefined) {
      this.setData({ isUpgradeLoading: true });
      try {
        const response = await backendAPI.applyUpgrade(
          searchId,
          packageId,
          fare.ff,
        );
        const upgradedPackage = response?.upgradedPackage || {};
        const upgradedPackageId =
          response?.upgradedPackageId || upgradedPackage.id;
        const upgradedTotal = upgradedPackage.total;
        selectedTotal = upgradedTotal || selectedTotal;
        this.persist({
          selectedUpgradeFare: fare,
          selectedFlight: upgradedPackageId
            ? {
                ...(this.payload.selectedFlight || {}),
                ...upgradedPackage,
                id: upgradedPackageId,
                package_id: upgradedPackageId,
              }
            : this.payload.selectedFlight,
          totals: {
            ...(this.payload.totals || {}),
            current: selectedTotal,
            currency: this.payload.totals?.currency || "USD",
          },
        });
      } catch (error) {
        wx.showToast({ title: error.message || "Upgrade unavailable", icon: "none" });
        this.setData({ isUpgradeLoading: false });
        return;
      }
      this.setData({ isUpgradeLoading: false });
    }
    this.persist({
      selectedUpgradeFare: fare,
      totals: {
        ...(this.payload.totals || {}),
        current: selectedTotal,
        currency: "USD",
      },
    });
    this.setData({
      selectedUpgradeFare: fare.id,
      upgradeCarouselIndex: index,
      upgradeCarouselOffset: -Math.min(index * 520, 520),
      upgradeTotalPrice: selectedTotal,
    });
  },
  handleSelectUpgradeFare(event) {
    const id = event.detail?.fareId || event.currentTarget.dataset.fareId;
    this.selectFare(
      (this.payload.upgradeFares || []).findIndex((item) => item.id === id),
    );
  },
  handleUpgradeCarouselNext() {
    this.selectFare(this.data.upgradeCarouselIndex + 1);
  },
  handleUpgradeCarouselPrev() {
    this.selectFare(this.data.upgradeCarouselIndex - 1);
  },
  handleUpgradeContinue() {
    if (this.data.isUpgradeLoading) return;
    this.persist({ currentStep: "passengers" });
    navigateTo(BOOKING_ROUTES.passengers);
  },
});

