import {
  BOOKING_REVIEW_STATE_KEY,
  loadBooking,
  subscribeBooking,
} from "../../utils/booking/session";
import { navigateTo } from "../../utils/helpers/navigation";
import { BOOKING_ROUTES } from "../../utils/booking/routes";

const passengerNames = (passengers = []) =>
  passengers.map((passenger, index) => ({
    name:
      [passenger.givenNames, passenger.surnames].filter(Boolean).join(" ") ||
      passenger.name ||
      `Passenger ${index + 1}`,
    seat: "No seats requested",
  }));

Page({
  data: {
    showSeatModal: false,
    selectedSeats: [],
    selectedSeatLabel: "",
    totalPrice: "0.00",
    passengers: [],
    legs: [],
    reservedSeats: [],
    occupiedSeats: [],
    starSeat: "",
    ringSeat: "",
    ringTooltip: "16 x 16",
    pricePerSeat: 25,
    currency: "USD",
    flight: {
      airline: "Air Cote d'Ivoire",
      number: "HF725",
      duration: "1h 40m",
    },
  },

  onLoad() {
    this.source = `seat-map-${Date.now()}`;
    this.unsubscribe = subscribeBooking((payload, source) => {
      if (source !== this.source) this.refresh(payload);
    }, this.source);
    this.refresh();
  },
  onShow() {
    this.refresh();
  },
  onUnload() {
    if (this.unsubscribe) this.unsubscribe();
  },
  refresh(payload = loadBooking()) {
    const booking = payload || {};
    const selectedFlight = booking.selectedFlight || {};
    const itinerary = booking.detailsItinerary || {};

    const passengers = (
      booking.passengers && booking.passengers.length
        ? booking.passengers
        : booking.reviewPassengers || []
    ).map((passenger, index) => ({
      name:
        [passenger.givenNames, passenger.surnames].filter(Boolean).join(" ") ||
        passenger.name ||
        `Passenger ${index + 1}`,
      seat: "No seats requested",
    }));
    const firstSegment = itinerary?.legs?.[0]?.segments?.[0] || {};
    const flight = {
      airline:
        firstSegment?.carrier?.name ||
        selectedFlight?.carrier?.name ||
        this.data.flight.airline,
      number:
        firstSegment?.carrier?.code ||
        selectedFlight?.carrier?.code ||
        selectedFlight?.flightNumber ||
        this.data.flight.number,
      duration:
        firstSegment?.duration ||
        selectedFlight?.duration ||
        this.data.flight.duration,
      from: selectedFlight?.from || bookingLegs[0]?.from || {},
      to: selectedFlight?.to || bookingLegs[bookingLegs.length - 1]?.to || {},
    };

    this.setData({
      passengers,
      legs: booking.legs,
      reservedSeats: selectedFlight?.reservedSeats || [],
      occupiedSeats: selectedFlight?.occupiedSeats || [],
      starSeat: selectedFlight?.starSeat || "",
      ringSeat: selectedFlight?.ringSeat || "",
      ringTooltip: selectedFlight?.ringTooltip || this.data.ringTooltip,
      pricePerSeat: Number(
        selectedFlight?.pricePerSeat || this.data.pricePerSeat,
      ),
      currency:
        selectedFlight?.currency ||
        booking?.totals?.currency ||
        this.data.currency,
      flight,
      totalPrice: "0.00",
    });
  },

  handleBack() {
    wx.navigateBack();
  },

  handleSkip() {
    wx.navigateTo({ url: "/pages/next-step/next-step" });
  },

  handleSeatTap(e) {
    const { seatId, selected, selectedCount } = e.detail;
    if (!selected) {
      const passengers = this.data.passengers.map((passenger) =>
        passenger.seat === seatId
          ? { ...passenger, seat: "No seats requested" }
          : passenger,
      );
      this.setData({ passengers });
      return;
    }

    this.setData({
      showSeatModal: true,
      selectedSeats: [seatId],
      selectedSeatLabel: seatId,
      totalPrice: (selectedCount * this.data.pricePerSeat).toFixed(2),
    });
  },

  handleNext(e) {
    const { selectedSeatsByLeg = [] } = e.detail;
    const seatRequests = this.data.legs.map((leg, index) => ({
      legIndex: index,
      leg: leg?.from?.code || leg?.to?.code,
      selectedSeats: selectedSeatsByLeg[index] || [],
      seatCount: (selectedSeatsByLeg[index] || []).length,
      price: (
        (selectedSeatsByLeg[index] || []).length * this.data.pricePerSeat
      ).toFixed(2),
      currency: this.data.currency,
    }));
    const totalSeatCount = seatRequests.reduce(
      (total, request) => total + request.seatCount,
      0,
    );
    const totalPrice = (totalSeatCount * this.data.pricePerSeat).toFixed(2);

    getApp().globalData.eventBus.setState(BOOKING_REVIEW_STATE_KEY, {
      seatRequests,
      totalSeatCount,
      seatTotal: totalPrice,
      currency: this.data.currency,
    });

    navigateTo(BOOKING_ROUTES.review);
  },

  handleCloseSeatModal() {
    this.setData({ showSeatModal: false });
  },

  handleRequestSeat(e) {
    const passengerIndex = Number(e.currentTarget.dataset.index);
    const seat = this.data.selectedSeatLabel;
    if (!seat) return;

    const passengers = this.data.passengers.map((passenger, index) =>
      index === passengerIndex
        ? { ...passenger, seat }
        : passenger.seat === seat
          ? { ...passenger, seat: "No seats requested" }
          : passenger,
    );
    this.setData({ passengers });
  },
});

