import { getContact } from "../../utils/helpers/bookingPayload";
import { loadBookingProjection, updateBooking, subscribeBooking } from "../../utils/booking/session";
import { navigateTo } from "../../utils/helpers/navigation";
import { BOOKING_ROUTES } from "../../utils/booking/routes";
import { i18nBehavior } from "../../utils/behaviors/i18n.js";

Page({
  behaviors: [i18nBehavior],
  data: { bookingReference: "", email: "" },

  onLoad() {
    this.source = `confirmed-${Date.now()}`;
    this.unsubscribe = subscribeBooking((payload, source) => {
      if (source !== this.source) this.refresh(payload);
    }, this.source);
    this.refresh();
  },

  onShow() { this.refresh(); },
  onUnload() { if (this.unsubscribe) this.unsubscribe(); },

  refresh(payload = null) {
    const PROJECTION_FIELDS = [
      "passengers",
      "contact",
      "bookingReference",
      "payment",
    ];
    const booking = payload || loadBookingProjection(PROJECTION_FIELDS) || {};
    this.payload = booking || {};
    const bookingResponse = this.payload.payment?.response || {};
    const primaryContact = getContact(this.payload);
    this.setData({
      bookingReference:
        this.payload.payment?.bookingReference ||
        this.payload.bookingReference ||
        "",
      email:
        bookingResponse.email ||
        primaryContact.email ||
        "",
      confirmedFooterMessage: this.t(
        "confirmed.email",
        { email: bookingResponse.email || primaryContact.email || "" },
      ),
    });
  },

  handleViewTripDetails() {
    updateBooking({ ...this.payload, currentStep: "trip-details" }, this.source);
    navigateTo(BOOKING_ROUTES.tripDetails);
  },
});

