import { i18nBehavior } from "../../utils/behaviors/i18n";
import { init, t } from "../../utils/i18n/index";
import { createReviewView } from "../../utils/helpers/review";
import {
  BOOKING_REVIEW_STATE_KEY,
  loadBookingProjection,
  updateBooking,
  subscribeBooking,
} from "../../utils/booking/session";
import { navigateBack, navigateTo } from "../../utils/helpers/navigation";
import { BOOKING_ROUTES } from "../../utils/booking/routes";

Page({
  behaviors: [i18nBehavior],
  data: {
    reviewTripExpanded: false,
    reviewPassengers: [],
    reviewPriceBreakdown: [],
  },
  onLoad() {
    init();
    this._loadI18nStrings();
    this._subscribeToLocaleChanges();
    this.unsubscribeLocale = getApp().globalData.eventBus.onState("app.locale", () => {
      if (!this.isDisposed) this.refresh();
    });
    this.source = `review-${Date.now()}`;
    this.unsubscribe = subscribeBooking((p, s) => {
      if (s !== this.source) this.refresh(p);
    }, this.source);
    this.refresh();
  },
  onShow() {
    this._loadI18nStrings();
    this.refresh();
  },
  onUnload() {
    this.isDisposed = true;
    if (this.unsubscribeLocale) this.unsubscribeLocale();
    if (this._i18nUnsub) this._i18nUnsub();
    this._i18nUnsub = null;
    if (this.unsubscribe) this.unsubscribe();
  },
  refresh(payload = null) {
    const PROJECTION_FIELDS = [
      "searchId", "results", "selectedFlight", "activeTab", "selectedCabin",
      "passengers", "passengerCheckout", "fareRules", "baggageAllowance", "priceBreakdown",
      "trip",
      "tripSummarySegments",
      "reviewPassengers",
      "totals",
      "reviewPriceBreakdown",
    ];
    const booking = payload || loadBookingProjection(PROJECTION_FIELDS) || {};
    this.payload = booking || {};
    const reviewState =
      getApp().globalData.eventBus.getState(BOOKING_REVIEW_STATE_KEY) || {};
    this.setData(createReviewView(this.payload, reviewState));
  },
  handleToggleReviewTripDetails() {
    this.setData({ reviewTripExpanded: !this.data.reviewTripExpanded });
  },
  handleEditReviewPassenger() {
    navigateBack();
  },
  handleReviewAutoCheckIn() {
    wx.showToast({ title: t("review.addToBooking"), icon: "none" });
  },
  handleReviewContinue() {
    updateBooking({ ...this.payload, currentStep: "payment" }, this.source);
    navigateTo(BOOKING_ROUTES.payment);
  },
});

