import { Bus } from "../../utils/event/index";
import { storage } from "../../utils/storage";
import {
  createFlightDetails,
  createTripSummary,
} from "../../utils/helpers/flightDetails";
import { navigateTo } from "../../utils/helpers/navigation";
import { BOOKING_ROUTES } from "../../utils/booking/routes";
import { i18nBehavior } from "../../utils/behaviors/i18n.js";
import { init as initI18n, t } from "../../utils/i18n/index.js";

const PROJECTION_FIELDS = [
  "selectedFlight",
  "activeTab",
  "from",
  "to",
  "multiCityLegs",
  "detailsItinerary",
  "tripSummarySegments",
  "currentStep",
  "updatedAt",
];

const BOOKING_STORAGE_KEY = "afritrip.booking.payload.v1";
const FLIGHT_DETAILS_STORAGE_KEY = "afritrip.flight-details.v1";
const BOOKING_STATE_KEY = "booking.payload";
const FLIGHT_DETAILS_STATE_KEY = "flight.details";

const isFlightDetailsPayload = (payload) =>
  payload &&
  typeof payload === "object" &&
  payload.selectedFlight &&
  typeof payload.selectedFlight === "object";

const projectFlightDetails = (payload = {}) =>
  PROJECTION_FIELDS.reduce((projection, field) => {
    if (Object.prototype.hasOwnProperty.call(payload, field)) {
      projection[field] = payload[field];
    }
    return projection;
  }, {});

/**
 * Reads the freshest Flight details payload from EventBus, then wxStorage.
 * The existing booking storage key remains a compatibility input until the
 * upstream Index and Flight results pages migrate to EventBus.
 */
const readFlightDetailsPayload = () => {
  const candidates = [
    Bus.getState(FLIGHT_DETAILS_STATE_KEY),
    Bus.getState(BOOKING_STATE_KEY),
    storage.get(FLIGHT_DETAILS_STORAGE_KEY),
    storage.get(BOOKING_STORAGE_KEY),
  ].filter(isFlightDetailsPayload);

  return candidates.reduce((freshest, candidate) => {
    if (!freshest) return candidate;
    return Number(candidate.updatedAt || 0) > Number(freshest.updatedAt || 0)
      ? candidate
      : freshest;
  }, null);
};

/**
 * Keeps the page snapshot in EventBus memory and in wxStorage.
 */
const cacheFlightDetailsPayload = (payload, notify = false) => {
  if (!isFlightDetailsPayload(payload)) return null;
  const snapshot = projectFlightDetails(payload);
  storage.set(FLIGHT_DETAILS_STORAGE_KEY, snapshot);
  Bus.setState(FLIGHT_DETAILS_STATE_KEY, snapshot, !notify);
  return snapshot;
};

/**
 * Persists changes without depending on utils/booking/session.js.
 * Writing the existing booking key keeps the following page compatible while
 * this branch remains scoped to Flight details only.
 */
const persistFlightDetailsPayload = (changes = {}) => {
  const storedBooking = storage.get(BOOKING_STORAGE_KEY, {}) || {};
  const eventBooking = Bus.getState(BOOKING_STATE_KEY, {}) || {};
  const base =
    Number(eventBooking.updatedAt || 0) > Number(storedBooking.updatedAt || 0)
      ? { ...storedBooking, ...eventBooking }
      : storedBooking;
  const nextPayload = { ...base, ...changes, updatedAt: Date.now() };

  storage.set(BOOKING_STORAGE_KEY, nextPayload);
  const app = getApp();
  if (app?.globalData) app.globalData.bookingPayload = nextPayload;
  Bus.setState(BOOKING_STATE_KEY, nextPayload);
  cacheFlightDetailsPayload(nextPayload, true);
  return nextPayload;
};

Page({
  behaviors: [i18nBehavior],
  data: {
    detailsItinerary: null,
    scarcityCount: null,
    scarcityMessage: "",
    submitting: false,
  },
  onLoad() {
    // This branch has no app-level i18n initialization yet.
    initI18n();
    // Keep behavior setup explicit because this page defines its own lifecycle methods.
    this._loadI18nStrings();
    this._subscribeToLocaleChanges();
    this.source = `flight-details-${Date.now()}`;
    this.refresh();
    this.unsubscribeFlightDetails = Bus.onState(
      FLIGHT_DETAILS_STATE_KEY,
      (change) => {
        if (!this.isDisposed && isFlightDetailsPayload(change?.value)) {
          this.refresh(change.value, false);
        }
      },
      { namespace: this.source },
    );
    // _t is refreshed by the behavior; rebuild the translated component props too.
    this.unsubscribeLocale = Bus.onState(
      "app.locale",
      () => {
        if (!this.isDisposed) this.refresh();
      },
      { namespace: this.source },
    );
  },
  onShow() {
    this._loadI18nStrings();
    this.refresh();
  },
  onUnload() {
    this.isDisposed = true;
    if (this.unsubscribeFlightDetails) this.unsubscribeFlightDetails();
    if (this.unsubscribeLocale) this.unsubscribeLocale();
    if (this._i18nUnsub) {
      this._i18nUnsub();
      this._i18nUnsub = null;
    }
  },
  refresh(payload = null, cache = true) {
    const booking = payload || readFlightDetailsPayload() || {};
    const detailsItinerary =
      booking.detailsItinerary || createFlightDetails(booking);
    const scarcityCount = detailsItinerary?.scarcityCount ?? null;
    this.payload = projectFlightDetails(booking);
    if (cache && detailsItinerary) {
      cacheFlightDetailsPayload({
        ...this.payload,
        detailsItinerary,
      });
    }
    this.setData({
      detailsItinerary,
      scarcityCount,
      scarcityMessage:
        scarcityCount > 0
          ? t(
              scarcityCount === 1
                ? "flightDetails.scarcity.one"
                : "flightDetails.scarcity.other",
              { count: scarcityCount },
            )
          : "",
    });
  },
  handleExpandFlightSegment(event) {
    const leg = this.data.detailsItinerary?.legs.find(
      (item) => item.id === event.detail?.legId,
    );
    const segment = leg?.segments.find(
      (item) => item.id === event.detail?.segmentId,
    );
    wx.showToast({
      title: segment
        ? `${segment.departure.code} → ${segment.arrival.code}`
        : t("flightDetails.title"),
      icon: "none",
    });
  },
  async handleContinueFromDetails() {
    if (this.data.submitting) return;
    const booking = readFlightDetailsPayload() || this.payload || {};
    const detailsItinerary = createFlightDetails(booking);
    if (
      !detailsItinerary ||
      !detailsItinerary.hasQuote ||
      detailsItinerary.scarcityCount === 0
    ) {
      this.refresh(booking);
      wx.showToast({
        title: t("flightDetails.error.unavailable"),
        icon: "none",
      });
      return;
    }
    this.setData({ submitting: true });
    try {
      persistFlightDetailsPayload({
        detailsItinerary,
        tripSummarySegments: createTripSummary(detailsItinerary),
        currentStep: "upgrade",
      });
      await navigateTo(BOOKING_ROUTES.upgrade);
    } catch {
      wx.showToast({ title: t("flightDetails.error.continue"), icon: "none" });
    } finally {
      if (!this.isDisposed) this.setData({ submitting: false });
    }
  },
});

