import { formatDuration } from "../../utils/formatters/index";
import {
  TRAVEL_CABIN_CLASSES,
  BASE_TICKET_PRICE,
  STORAGE_KEYS,
} from "../../utils/constants/index";
import { navigateTo } from "../../utils/helpers/navigation";
import {
  createFlightDetails,
  createTripSummary,
} from "../../utils/helpers/index";
import { BOOKING_ROUTES } from "../../utils/booking/routes";

const app = getApp();
const { flightDetails } = require("../../mocks/flight-details");
const { tripDetails } = require("../../mocks/trip-details");

const FILTERS = [
  { value: "Best", label: "Best", price: "" },
  { value: "Cheapest", label: "Cheapest", price: "" },
  { value: "Shortest", label: "Shortest", price: "" },
];
const RESULTS_PAGE_SIZE = 5;
// Taille des lots traités en arrière-plan après le premier rendu.
// Garde chaque tâche courte pour ne jamais bloquer le thread JS trop longtemps.
const BACKGROUND_CHUNK_SIZE = 20;

let preparedResultsCache = null;

const formatPrice = (amount) =>
  new Intl.NumberFormat("fr-FR").format(Math.round(amount || 0));
const priceValue = (price) => {
  if (typeof price === "number") return price;
  const normalized = String(price || "0")
    .replace(/\s/g, "")
    .replace(",", ".")
    .replace(/[^\d.-]/g, "");
  return Number.parseFloat(normalized) || 0;
};

const durationValue = (duration) => {
  if (typeof duration === "number") return duration;
  const values =
    String(duration || "")
      .match(/\d+/g)
      ?.map(Number) || [];
  return values.length > 1 ? values[0] * 60 + values[1] : values[0] || 0;
};

const stopMultiplier = (stops) => {
  const label = String(stops || "").toLowerCase();
  if (label.includes("direct")) return 1.1;
  if (label.includes("1 stop") || label.includes("1 escale")) return 0.95;
  return 0.85;
};

const getLegs = (item) => item?.itinerary || item?.legs || [];

const getLegEndpoints = (leg = {}) => {
  const segments = leg.segments || [];
  const first = segments[0] || {};
  const last = segments[segments.length - 1] || first;
  return {
    from: leg.origin_airport_code || first.departure_code || "",
    to: leg.destination_airport_code || last.arrival_code || "",
    departure: first.departure_time || {},
    arrival: last.arrival_time || {},
  };
};

const getTime = (value) => {
  if (value && typeof value === "object") return value.time || "";
  return String(value || "")
    .replace(/:00(?::00)?\s*([AP]M)?$/i, "$1")
    .trim();
};

const getDate = (value) => {
  if (value && typeof value === "object") return value.date || "";
  return String(value || "");
};

const legDurationValue = (leg = {}) => {
  const value = leg.duration || leg.totalDuration || 0;
  const numeric = Number(value);
  return numeric > 1000 ? Math.round(numeric / 60) : durationValue(value);
};

const legStops = (leg = {}) => {
  const stops = Number(leg.num_stops);
  if (Number.isFinite(stops)) {
    if (stops === 0) return "Direct";
    return `${stops} stop${stops > 1 ? "s" : ""}`;
  }
  return leg.stops || "Direct";
};

const totalForPassengers = (price, counts = {}) =>
  Math.round(
    (counts.adults || 0) * price +
      (counts.children || 0) * price * 0.75 +
      (counts.infants || 0) * price * 0.25 +
      (counts.infantsOnLap || 0) * price * 0.1,
  );

const createResultsCacheKey = (payload, passengerCounts, selectedCabin) =>
  JSON.stringify({
    activeTab: payload.activeTab || "roundTrip",
    from: payload.from || "",
    to: payload.to || "",
    departDate: payload.departDate || "",
    returnDate: payload.returnDate || "",
    multiCityLegs: payload.multiCityLegs || [],
    nonstopOnly: Boolean(payload.nonstopOnly),
    removeLowCost: Boolean(payload.removeLowCost),
    passengerCounts,
    selectedCabin,
    searchId: payload.bookingReference || payload.searchId || "",
  });

const clone = (value) => structuredClone(value);

const normalizeLocation = (location) => {
  if (location && typeof location === "object") {
    return {
      ...location,
      name: location.name || location.label || location.value || "",
      code: location.code || "",
    };
  }

  const value = String(location || "").trim();
  const closingParenthesis = value.endsWith(")") ? value.length - 1 : -1;
  const openingParenthesis =
    closingParenthesis >= 0 ? value.lastIndexOf("(", closingParenthesis) : -1;
  const code =
    openingParenthesis >= 0
      ? value.slice(openingParenthesis + 1, closingParenthesis).trim()
      : "";
  return {
    name:
      openingParenthesis >= 0
        ? value.slice(0, openingParenthesis).trim()
        : value,
    code,
  };
};

const buildPassengers = (counts = {}, existing = []) => {
  const types = [
    ["adults", "Adult"],
    ["children", "Child"],
    ["infants", "Infant"],
    ["infantsOnLap", "Infant on lap"],
  ];
  const passengers = [];
  types.forEach(([key, label]) => {
    for (let index = 0; index < Number(counts[key] || 0); index += 1) {
      const position = passengers.length;
      const saved = existing[position] || {};
      passengers.push({
        ...saved,
        id: saved.id || `passenger-${position + 1}`,
        passengerType: key,
        label: `Passenger ${position + 1}`,
        badges:
          position === 0
            ? [
                { id: "primary", text: "Primary contact" },
                { id: key, text: label },
              ]
            : [{ id: key, text: label }],
        givenNames: saved.givenNames || "",
        surnames: saved.surnames || "",
        dob: saved.dob || "",
        gender: saved.gender || (position === 0 ? "male" : ""),
      });
    }
  });
  return passengers;
};

Page({
  data: {
    filters: FILTERS,
    activeFilter: "Best",
    mockResults: [],
    summaryPrice: "-",
    hasMoreResults: false,
    isPreparingResults: false,
    isLoading: true,
  },

  onLoad() {
    const payload =
      getApp().globalData.eventBus.getState(STORAGE_KEYS.BOOKING_STATE, {}) ||
      {};
    const passengerCounts = payload.passengerCounts || {
      adults: 1,
      children: 0,
      infants: 0,
      infantsOnLap: 0,
    };
    const selectedCabin =
      payload.selectedCabin || TRAVEL_CABIN_CLASSES[0].value;
    const cabin = TRAVEL_CABIN_CLASSES.find(
      (item) => item.value === selectedCabin,
    ) || { multiplier: 1 };
    const savedResults = Array.isArray(payload?.results)
      ? payload.results
      : null;
    const packages = Array.isArray(payload?.results?.packages)
      ? payload.results.packages
      : Object.values(payload?.results?.packages || {});

    const cacheKey = createResultsCacheKey(
      payload,
      passengerCounts,
      selectedCabin,
    );

    this.payloadBase = payload;
    this.passengerCounts = passengerCounts;
    this.selectedCabin = selectedCabin;
    this.cabin = cabin;
    this.cacheKey = cacheKey;

    // Cas 1 : tout est déjà prêt en mémoire (retour arrière sur la page par ex.)
    if (preparedResultsCache?.key === cacheKey) {
      this.finalizeResults(preparedResultsCache.results, { persist: false });
      return;
    }

    // Cas 2 : résultats déjà normalisés et stockés côté session
    if (payload.resultsCacheKey === cacheKey && savedResults?.length) {
      this.finalizeResults(savedResults, { persist: false });
      return;
    }

    // Cas 3 : il faut normaliser les paquets bruts. On traite d'abord un
    // premier lot pour un affichage quasi instantané, le reste est calculé
    // juste après sans bloquer le rendu initial.
    this.rawPackages = packages;
    this.processInitialBatch();
  },

  // Normalise + calcule les prix pour un sous-ensemble de paquets bruts.
  processBatch(packages) {
    const results = this.normalizeResults(packages).map((item) => {
      const base =
        priceValue(item?.prices?.total_price || item?.fares?.total) ||
        BASE_TICKET_PRICE ||
        100000;
      const perPassenger = Math.round(
        base *
          (this.cabin.multiplier || 1) *
          stopMultiplier(item.stops) *
          (item.lowCost ? 0.9 : 1),
      );
      return {
        ...item,
        price: formatPrice(perPassenger),
        totalPrice: formatPrice(
          totalForPassengers(perPassenger, this.passengerCounts),
        ),
        note: "per passenger (estimate)",
        _numericPrice: perPassenger,
      };
    });

    return this.filterResults(results);
  },

  filterResults(results = []) {
    if (!this.payloadBase?.nonstopOnly) return results;
    return results.filter((item) => item.stops === "Direct");
  },

  // Traite juste assez de résultats pour peindre l'écran tout de suite.
  processInitialBatch() {
    const packages = this.rawPackages || [];
    const firstChunk = packages.slice(0, RESULTS_PAGE_SIZE);
    const normalizedFirst = this.processBatch(firstChunk);
    const sortedFirst = this.getSortedResults("Best", normalizedFirst);

    this.allResults = sortedFirst;
    this.visibleResultsCount = RESULTS_PAGE_SIZE;
    this.sortedByFilter = null; // pas encore fiable tant que tout n'est pas chargé

    const passengers = buildPassengers(
      this.passengerCounts,
      this.payloadBase.passengers,
    );
    this.bookingPayload = { ...this.payloadBase, passengers };

    this.setData({
      passengerCounts: this.passengerCounts,
      selectedCabin: this.selectedCabin,
      filters: this.getFilterPrices(sortedFirst),
      mockResults: sortedFirst.slice(0, RESULTS_PAGE_SIZE),
      summaryPrice: sortedFirst[0]?.totalPrice || "-",
      hasMoreResults: packages.length > RESULTS_PAGE_SIZE,
      isPreparingResults: packages.length > RESULTS_PAGE_SIZE,
      isLoading: false,
    });

    if (packages.length > RESULTS_PAGE_SIZE) {
      this.scheduleBackgroundProcessing(RESULTS_PAGE_SIZE);
    }
  },

  // Traite le reste des paquets par petits lots pour rester réactif,
  // puis fusionne, trie une seule fois pour tous les filtres, et persiste.
  scheduleBackgroundProcessing(startIndex) {
    const packages = this.rawPackages || [];
    const nextIndex = Math.min(
      startIndex + BACKGROUND_CHUNK_SIZE,
      packages.length,
    );
    const chunk = packages.slice(startIndex, nextIndex);
    const normalizedChunk = this.processBatch(chunk);

    this.allResults = (this.allResults || []).concat(normalizedChunk);

    if (nextIndex < packages.length) {
      const runNext = () => this.scheduleBackgroundProcessing(nextIndex);
      if (typeof wx !== "undefined" && wx.nextTick) {
        wx.nextTick(runNext);
      } else {
        setTimeout(runNext, 0);
      }
      return;
    }

    // Tous les paquets sont traités : on fixe le rang définitif, on
    // pré-calcule les 3 tris une bonne fois pour toutes, puis on persiste.
    const fullyNormalized = this.allResults.map((item, index) => ({
      ...item,
      rank: index + 1,
    }));
    this.finalizeResults(fullyNormalized, { persist: true });
  },

  // Point commun une fois qu'on a la liste complète des résultats normalisés :
  // pré-calcule les tris, met à jour l'affichage si le filtre courant change
  // de contenu, et sauvegarde (une seule fois, pas à chaque filtre).
  finalizeResults(results, { persist }) {
    const filteredResults = this.filterResults(results);
    this.allResults = filteredResults;
    this.sortedByFilter = this.buildSortIndexes(filteredResults);

    const activeFilter = this.data.activeFilter || "Best";
    const sorted = this.sortedByFilter[activeFilter] || filteredResults;
    this.visibleResultsCount = Math.max(
      this.visibleResultsCount || RESULTS_PAGE_SIZE,
      RESULTS_PAGE_SIZE,
    );

    if (persist) {
      const nextBookingPayload = {
        ...this.bookingPayload,
        currentStep: "results",
        results: filteredResults,
        resultsCacheKey: this.cacheKey,
      };
      app.globalData.bookingPayload = nextBookingPayload;
      app.globalData.eventBus.setState(
        STORAGE_KEYS.BOOKING_STATE,
        nextBookingPayload,
      );
      this.bookingPayload = nextBookingPayload;
      preparedResultsCache = { key: this.cacheKey, results: filteredResults };
    } else {
      this.bookingPayload = {
        ...this.bookingPayload,
        currentStep: "results",
        resultsCacheKey: this.cacheKey,
      };
      preparedResultsCache = { key: this.cacheKey, results: filteredResults };
    }

    this.setData({
      filters: this.getFilterPrices(),
      mockResults: sorted.slice(0, this.visibleResultsCount),
      summaryPrice: sorted[0]?.totalPrice || "-",
      hasMoreResults: sorted.length > this.visibleResultsCount,
      isPreparingResults: false,
      isLoading: false,
    });
  },

  onPageScroll() {
    if (!this.data.hasMoreResults || this.isLoadingMoreResults) return;

    wx.createSelectorQuery()
      .select(".page-content")
      .boundingClientRect((rect) => {
        wx.getSystemInfo({
          success: ({ windowHeight }) => {
            if (rect && rect.bottom <= windowHeight + 200) {
              this.loadMoreResults();
            }
          },
        });
      })
      .exec();
  },

  loadMoreResults() {
    const results = this.currentSortedResults();
    if (this.visibleResultsCount >= results.length) return;

    this.isLoadingMoreResults = true;
    this.visibleResultsCount = Math.min(
      this.visibleResultsCount + RESULTS_PAGE_SIZE,
      results.length,
    );
    this.setData(
      {
        mockResults: results.slice(0, this.visibleResultsCount),
        hasMoreResults: this.visibleResultsCount < results.length,
      },
      () => {
        this.isLoadingMoreResults = false;
      },
    );
  },

  normalizeResults(results = []) {
    return results.map((item, index) => {
      const legs = getLegs(item);
      const outbound = legs[0] || {};
      const inbound = legs[1] || {};
      const outboundEndpoints = getLegEndpoints(outbound);
      const inboundEndpoints = getLegEndpoints(inbound);
      const outboundDuration = legDurationValue(outbound);
      const inboundDuration = legDurationValue(inbound);

      return {
        ...item,
        id: item.id || item.package_id || `result-${index + 1}`,
        from: item.from || outboundEndpoints.from,
        to: item.to || outboundEndpoints.to,
        departDate: item.departDate || getDate(outboundEndpoints.departure),
        returnDate: item.returnDate || getDate(inboundEndpoints.departure),
        price: item.price || "-",
        note: item.note || "per passenger (taxes included)",
        time:
          item.time?.departure || item.time?.arrival
            ? item.time
            : {
                departure: getTime(outboundEndpoints.departure),
                arrival: getTime(outboundEndpoints.arrival),
              },
        airline: item.airline || { name: item.airline_name || "" },
        stops: item.stops || legStops(outbound),
        duration: item.duration || formatDuration("", outboundDuration),
        returnDuration: formatDuration("", inboundDuration),
        totalDuration: outboundDuration + inboundDuration,
        rank: item.rank || index + 1,
      };
    });
  },

  // Trie une liste selon un filtre donné (utilisé pour construire l'index
  // pré-calculé, et comme filet de sécurité si l'index n'est pas encore prêt).
  getSortedResults(filter, results = []) {
    const sorted = [...results];
    if (filter === "Cheapest")
      return sorted.sort((a, b) => priceValue(a.price) - priceValue(b.price));
    if (filter === "Shortest")
      return sorted.sort((a, b) => a.totalDuration - b.totalDuration);
    return sorted.sort((a, b) => a.rank - b.rank);
  },

  // Pré-calcule les 3 tris une seule fois par jeu de résultats complet,
  // au lieu de retrier à chaque clic sur un filtre.
  buildSortIndexes(results = []) {
    return {
      Best: this.getSortedResults("Best", results),
      Cheapest: this.getSortedResults("Cheapest", results),
      Shortest: this.getSortedResults("Shortest", results),
    };
  },

  // Résultats triés selon le filtre actif, en s'appuyant sur l'index
  // pré-calculé quand il est disponible (chargement en arrière-plan terminé).
  currentSortedResults() {
    if (this.sortedByFilter) {
      return this.sortedByFilter[this.data.activeFilter] || this.allResults;
    }
    return this.allResults || [];
  },

  getFilterPrices(resultsOverride) {
    if (this.sortedByFilter) {
      return FILTERS.map((filter) => ({
        ...filter,
        price: this.sortedByFilter[filter.value][0]?.prices.total_price || "-",
      }));
    }
    const results = resultsOverride || this.allResults || [];
    return FILTERS.map((filter) => ({
      ...filter,
      price: this.getSortedResults(filter.value, results)[0]?.price || "-",
    }));
  },

  handleFilterSelect(event) {
    const activeFilter = event.currentTarget.dataset.value;
    const results = this.sortedByFilter
      ? this.sortedByFilter[activeFilter] || this.allResults || []
      : this.getSortedResults(activeFilter, this.allResults || []);

    this.visibleResultsCount = RESULTS_PAGE_SIZE;

    this.setData({
      activeFilter,
      mockResults: results.slice(0, RESULTS_PAGE_SIZE),
      filters: this.getFilterPrices(),
      summaryPrice: results[0]?.totalPrice || "-",
      hasMoreResults: results.length > RESULTS_PAGE_SIZE,
      isLoading: false,
    });

    // UI mise à jour immédiatement ; la persistance suit avec un léger délai
    // pour absorber les clics rapides successifs.
    this.pendingFilterToSave = activeFilter;
    clearTimeout(this._saveFilterTimer);
    this._saveFilterTimer = setTimeout(() => {
      const nextBookingPayload = {
        ...this.bookingPayload,
        selectedResultFilter: this.pendingFilterToSave,
      };
      app.globalData.bookingPayload = nextBookingPayload;
      app.globalData.eventBus.setState(
        STORAGE_KEYS.BOOKING_STATE,
        nextBookingPayload,
      );
      this.bookingPayload = nextBookingPayload;
    }, 300);
  },

  handleDetailsFlight(event) {
    const eventDetail = event?.detail || {};
    const selectedFlight = {
      ...eventDetail,
      from: normalizeLocation(eventDetail.from),
      to: normalizeLocation(eventDetail.to),
    };
    const perPassenger =
      selectedFlight._numericPrice ||
      priceValue(selectedFlight.price) ||
      BASE_TICKET_PRICE;
    const totalAmount = formatPrice(
      totalForPassengers(perPassenger, this.data.passengerCounts),
    );
    const detailsItinerary = createFlightDetails({
      ...this.bookingPayload,
      selectedFlight,
    });
    const tripSummarySegments = detailsItinerary
      ? createTripSummary(detailsItinerary)
      : [];

    const trip = {
      ...clone(tripDetails),
      title: `Trip to ${selectedFlight.to.name || "your destination"}`,
      bookingReference: this.bookingPayload.bookingReference,
      confirmation:
        selectedFlight.confirmation || this.bookingPayload.bookingReference,
      contact: this.bookingPayload.contact || tripDetails.contact,
      actions:
        this.bookingPayload.tripActions || tripDetails.actions.slice(0, 1),
      price: {
        ...tripDetails.price,
        finalTotal: `${totalAmount} USD`,
        passengersTotal: `${totalAmount} USD`,
      },
    };
    const nextBookingPayload = {
      ...this.bookingPayload,
      currentStep: "flight-details",
      updatedAt: Date.now(),
      selectedFlight,
      detailsItinerary,
      tripSummarySegments,
      selectedUpgradeFare: null,
      totals: { base: totalAmount, current: totalAmount, currency: "USD" },
      trip,
    };
    app.globalData.bookingPayload = nextBookingPayload;
    app.globalData.eventBus.setState(
      STORAGE_KEYS.BOOKING_STATE,
      nextBookingPayload,
    );
    this.bookingPayload = nextBookingPayload;

    navigateTo(BOOKING_ROUTES.flightDetails);
  },
});

