      if (this.strictMode) {
        throw new Error(`Invalid event name: ${eventValidation.error}`);
      }
      this._log(`❌ Invalid event name: ${eventValidation.error}`);
      return false;
    }

    const timestamp = Date.now();
    this._log(`🚀 Emitting '${event}'`, data);

